// GERADO AUTOMATICAMENTE por scripts/gerar-template-bot.mjs a partir da pasta bot-template/.
// Não edite aqui: edite os arquivos em bot-template/ (o "npm run dev" e o "npm run build" geram de novo).
export const TEMPLATE_VERSION = "dfff1af9ae94";

export const TEMPLATE_FILES: Record<string, string> = {
  ".env.example": "# Token do bot: Developer Portal → sua aplicação → Bot → Reset Token\nDISCORD_TOKEN=\n\n# Opcional: ID de um servidor de testes. Com ele, os comandos aparecem na hora nesse servidor.\n# Sem ele, os comandos são registrados em todos os servidores (pode levar alguns minutos).\nGUILD_ID=\n",
  ".gitignore": "node_modules/\n.env\ndata/\n",
  "config.json": "{\n  \"nome\": \"Meu Bot\",\n  \"cor\": \"#5865F2\",\n  \"status\": \"Use /ajuda\",\n  \"modulos\": [\n    \"moderacao\",\n    \"automod\",\n    \"antiraid\",\n    \"verificacao\",\n    \"boasvindas\",\n    \"logs\",\n    \"convites\",\n    \"niveis\",\n    \"economia\",\n    \"reputacao\",\n    \"tickets\",\n    \"avaliacoes\",\n    \"formularios\",\n    \"sugestoes\",\n    \"enquetes\",\n    \"sorteios\",\n    \"cargos\",\n    \"cargostemp\",\n    \"callstemp\",\n    \"contadores\",\n    \"destaques\",\n    \"contagem\",\n    \"afk\",\n    \"autorespostas\",\n    \"anuncios\",\n    \"embeds\",\n    \"aniversarios\",\n    \"minecraft\",\n    \"utilidades\",\n    \"diversao\"\n  ]\n}\n",
  "extras/inicializador/inicializador.ps1": "﻿# Inicializador de bots (usado pelo \"Iniciar bot.bat\").\n# Procura no PC as pastas de bot, mostra qual é a mais nova e a mais antiga, liga o bot escolhido\n# e ajuda a mandar cópias velhas para a Lixeira. Não precisa digitar comandos.\n\n$ErrorActionPreference = 'Stop'\nAdd-Type -AssemblyName System.Windows.Forms\nAdd-Type -AssemblyName System.Drawing\nAdd-Type -AssemblyName Microsoft.VisualBasic\n[System.Windows.Forms.Application]::EnableVisualStyles()\n\n$titulo = 'Inicializador de bots'\n$pastaCache = Join-Path $env:APPDATA 'InicializadorBots'\n$arquivoCache = Join-Path $pastaCache 'bots.json'\n$fmt = 'dd/MM/yyyy HH:mm'\n$PULAR = @('node_modules', '.git', 'windows', 'program files', 'program files (x86)', 'programdata', 'appdata', '$recycle.bin',\n  'system volume information', 'recovery', 'msocache', 'perflogs', 'data', 'data-backup', '.cache', '.npm', 'steamapps', 'windowsapps')\n\nfunction Aviso([string]$texto, [string]$icone = 'Information') {\n  [void][System.Windows.Forms.MessageBox]::Show($texto, $titulo, 'OK', $icone)\n}\nfunction Pergunta([string]$texto, [string]$icone = 'Question') {\n  return ([System.Windows.Forms.MessageBox]::Show($texto, $titulo, 'YesNo', $icone) -eq [System.Windows.Forms.DialogResult]::Yes)\n}\n\n# ---------------- reconhecer um bot ----------------\nfunction EhBot([string]$pasta) {\n  return (Test-Path -LiteralPath (Join-Path $pasta 'index.js')) -and\n         (Test-Path -LiteralPath (Join-Path $pasta 'config.json')) -and\n         (Test-Path -LiteralPath (Join-Path $pasta 'src\\core\\nucleo.js'))\n}\n\nfunction InfoBot([string]$pasta) {\n  $nome = '(sem nome)'\n  try { $nome = (Get-Content -LiteralPath (Join-Path $pasta 'config.json') -Raw -Encoding UTF8 | ConvertFrom-Json).nome } catch {}\n  $versao = (Get-Item -LiteralPath (Join-Path $pasta 'index.js')).LastWriteTime\n  $dados = @(Get-ChildItem -LiteralPath (Join-Path $pasta 'data') -Filter '*.json' -File -ErrorAction SilentlyContinue)\n  $atividade = $null\n  if ($dados.Count -gt 0) { $atividade = ($dados | Sort-Object LastWriteTime -Descending | Select-Object -First 1).LastWriteTime }\n  $token = $false\n  $arqEnv = Join-Path $pasta '.env'\n  if (Test-Path -LiteralPath $arqEnv) { $token = [bool](Select-String -LiteralPath $arqEnv -Pattern '^\\s*DISCORD_TOKEN\\s*=\\s*\\S+' -Quiet) }\n  return [pscustomobject]@{ Nome = $nome; Pasta = $pasta; Versao = $versao; Atividade = $atividade; Dados = $dados.Count; Token = $token; Situacao = '' }\n}\n\n# ---------------- procurar no PC ----------------\nfunction Procurar($rotulo) {\n  $achados = New-Object System.Collections.Generic.List[string]\n  $fila = New-Object System.Collections.Generic.Queue[object]\n  # primeiro as pastas do usuário (fundo), depois a raiz de cada disco (mais raso)\n  $fila.Enqueue(@($env:USERPROFILE, 7))\n  foreach ($d in [System.IO.DriveInfo]::GetDrives()) {\n    if ($d.DriveType -eq 'Fixed' -and $d.IsReady) { $fila.Enqueue(@($d.RootDirectory.FullName, 5)) }\n  }\n  $vistas = @{}\n  $n = 0\n  while ($fila.Count -gt 0) {\n    $item = $fila.Dequeue()\n    $pasta = [string]$item[0]\n    $fundo = [int]$item[1]\n    $chave = $pasta.ToLowerInvariant().TrimEnd('\\')\n    if ($vistas.ContainsKey($chave)) { continue }\n    $vistas[$chave] = $true\n    $n++\n    if ($n % 200 -eq 0) {\n      $rotulo.Text = \"Procurando... $pasta\"\n      [System.Windows.Forms.Application]::DoEvents()\n    }\n    if (EhBot $pasta) { $achados.Add($pasta); continue }\n    if ($fundo -le 0) { continue }\n    try {\n      foreach ($sub in [System.IO.Directory]::EnumerateDirectories($pasta)) {\n        $nomeSub = [System.IO.Path]::GetFileName($sub).ToLowerInvariant()\n        if ($PULAR -contains $nomeSub -or $nomeSub.StartsWith('data-backup')) { continue }\n        $attr = [System.IO.File]::GetAttributes($sub)\n        if ($attr -band [System.IO.FileAttributes]::ReparsePoint) { continue }\n        $fila.Enqueue(@($sub, ($fundo - 1)))\n      }\n    } catch {}\n  }\n  return $achados\n}\n\nfunction SalvarCache($pastas) {\n  if (-not (Test-Path -LiteralPath $pastaCache)) { New-Item -ItemType Directory -Path $pastaCache | Out-Null }\n  ConvertTo-Json -InputObject @($pastas) | Set-Content -LiteralPath $arquivoCache -Encoding UTF8\n}\nfunction LerCache {\n  if (-not (Test-Path -LiteralPath $arquivoCache)) { return @() }\n  try { return @((Get-Content -LiteralPath $arquivoCache -Raw -Encoding UTF8 | ConvertFrom-Json) | Where-Object { $_ -and (EhBot $_) }) } catch { return @() }\n}\n\n# marca o mais novo e o mais antigo entre cópias do mesmo bot (mesmo nome)\nfunction MarcarSituacao($bots) {\n  foreach ($grupo in ($bots | Group-Object Nome)) {\n    if ($grupo.Count -lt 2) { continue }\n    $ordem = @($grupo.Group | Sort-Object Versao -Descending)\n    $ordem[0].Situacao = 'mais novo'\n    for ($k = 1; $k -lt $ordem.Count; $k++) { $ordem[$k].Situacao = 'mais antigo' }\n    if ($ordem.Count -gt 2) { for ($k = 1; $k -lt $ordem.Count - 1; $k++) { $ordem[$k].Situacao = 'antigo' } }\n  }\n}\n\n# ---------------- ligar o bot ----------------\nfunction Iniciar($bot) {\n  if (-not (Get-Command node -ErrorAction SilentlyContinue)) {\n    if (Pergunta \"Para ligar o bot, o computador precisa do Node.js (gratuito).`n`nAbrir o site para baixar agora? Instale a versão LTS e depois abra o Inicializador de novo.\") {\n      Start-Process 'https://nodejs.org/pt'\n    }\n    return\n  }\n  if (-not $bot.Token) {\n    $token = [Microsoft.VisualBasic.Interaction]::InputBox(\"Este bot ainda não tem o token.`n`nCole aqui o token do bot (Developer Portal → Bot → Reset Token):\", $titulo, '')\n    $token = $token.Trim()\n    if (-not $token) { return }\n    $arqEnv = Join-Path $bot.Pasta '.env'\n    $linhas = @()\n    if (Test-Path -LiteralPath $arqEnv) { $linhas = @(Get-Content -LiteralPath $arqEnv -Encoding UTF8 | Where-Object { $_ -notmatch '^\\s*DISCORD_TOKEN\\s*=' }) }\n    $linhas = @(\"DISCORD_TOKEN=$token\") + $linhas\n    [System.IO.File]::WriteAllLines($arqEnv, [string[]]$linhas, (New-Object System.Text.UTF8Encoding($false)))\n    $bot.Token = $true\n  }\n  $nomeJanela = ($bot.Nome -replace '[^\\p{L}\\p{N} _-]', '').Trim()\n  if (-not $nomeJanela) { $nomeJanela = 'Bot' }\n  $comando = \"title $nomeJanela && cd /d `\"$($bot.Pasta)`\" && (if not exist node_modules (echo Instalando as dependencias, aguarde... && npm install --no-audit --no-fund)) && npm start\"\n  Start-Process -FilePath 'cmd.exe' -ArgumentList '/k', $comando -WorkingDirectory $bot.Pasta\n}\n\n# ---------------- janela ----------------\n$form = New-Object System.Windows.Forms.Form\n$form.Text = $titulo\n$form.Size = New-Object System.Drawing.Size(900, 480)\n$form.StartPosition = 'CenterScreen'\n$form.Font = New-Object System.Drawing.Font('Segoe UI', 9.5)\n\n$rotulo = New-Object System.Windows.Forms.Label\n$rotulo.Location = New-Object System.Drawing.Point(12, 10)\n$rotulo.Size = New-Object System.Drawing.Size(860, 36)\n$rotulo.Text = 'Escolha o bot e clique em Iniciar.'\n$form.Controls.Add($rotulo)\n\n$lista = New-Object System.Windows.Forms.ListView\n$lista.Location = New-Object System.Drawing.Point(12, 50)\n$lista.Size = New-Object System.Drawing.Size(860, 330)\n$lista.View = 'Details'\n$lista.FullRowSelect = $true\n$lista.MultiSelect = $false\n$lista.HideSelection = $false\n[void]$lista.Columns.Add('Bot', 150)\n[void]$lista.Columns.Add('Situação', 90)\n[void]$lista.Columns.Add('Versão de', 115)\n[void]$lista.Columns.Add('Última atividade', 115)\n[void]$lista.Columns.Add('Token', 55)\n[void]$lista.Columns.Add('Pasta', 320)\n$form.Controls.Add($lista)\n\nfunction NovoBotao([string]$texto, [int]$x, [int]$largura) {\n  $b = New-Object System.Windows.Forms.Button\n  $b.Text = $texto\n  $b.Location = New-Object System.Drawing.Point($x, 392)\n  $b.Size = New-Object System.Drawing.Size($largura, 34)\n  $form.Controls.Add($b)\n  return $b\n}\n$btIniciar = NovoBotao 'Iniciar' 12 120\n$btAbrir = NovoBotao 'Abrir pasta' 140 110\n$btApagar = NovoBotao 'Apagar (Lixeira)' 258 140\n$btProcurar = NovoBotao 'Procurar de novo' 406 140\n$btFechar = NovoBotao 'Fechar' 772 100\n$form.AcceptButton = $btIniciar\n\n$script:bots = @()\n\nfunction Preencher {\n  $lista.Items.Clear()\n  foreach ($b in $script:bots) {\n    $it = New-Object System.Windows.Forms.ListViewItem($b.Nome)\n    [void]$it.SubItems.Add($b.Situacao)\n    [void]$it.SubItems.Add($b.Versao.ToString($fmt))\n    if ($b.Atividade) { [void]$it.SubItems.Add($b.Atividade.ToString($fmt)) } else { [void]$it.SubItems.Add('sem dados') }\n    if ($b.Token) { [void]$it.SubItems.Add('ok') } else { [void]$it.SubItems.Add('falta') }\n    [void]$it.SubItems.Add($b.Pasta)\n    if ($b.Situacao -eq 'mais novo') { $it.ForeColor = [System.Drawing.Color]::DarkGreen }\n    if ($b.Situacao -like '*antigo') { $it.ForeColor = [System.Drawing.Color]::Gray }\n    $it.Tag = $b\n    [void]$lista.Items.Add($it)\n  }\n  if ($lista.Items.Count -gt 0) {\n    $escolher = 0\n    for ($k = 0; $k -lt $script:bots.Count; $k++) { if ($script:bots[$k].Situacao -eq 'mais novo') { $escolher = $k; break } }\n    $lista.Items[$escolher].Selected = $true\n  }\n  $copias = @($script:bots | Where-Object { $_.Situacao -like '*antigo' }).Count\n  if ($script:bots.Count -eq 0) {\n    $rotulo.Text = 'Não achei nenhum bot no seu PC. Extraia o .zip do bot numa pasta e clique em \"Procurar de novo\".'\n  } elseif ($copias -gt 0) {\n    $rotulo.Text = \"Achei $($script:bots.Count) bot(s). Há $copias cópia(s) antiga(s) de um mesmo bot (em cinza): depois de conferir que o mais novo está com os dados, você pode apagar a antiga.\"\n  } else {\n    $rotulo.Text = \"Achei $($script:bots.Count) bot(s). Escolha um e clique em Iniciar.\"\n  }\n}\n\nfunction Carregar([bool]$procurarDeNovo) {\n  $pastas = @()\n  if (-not $procurarDeNovo) { $pastas = LerCache }\n  if ($pastas.Count -eq 0) {\n    $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor\n    $rotulo.Text = 'Procurando bots no seu PC (na primeira vez pode levar alguns minutos)...'\n    [System.Windows.Forms.Application]::DoEvents()\n    $pastas = @(Procurar $rotulo)\n    $form.Cursor = [System.Windows.Forms.Cursors]::Default\n    SalvarCache $pastas\n  }\n  $script:bots = @($pastas | ForEach-Object { InfoBot $_ } | Sort-Object Nome, Versao)\n  MarcarSituacao $script:bots\n  Preencher\n}\n\nfunction Selecionado {\n  if ($lista.SelectedItems.Count -eq 0) { Aviso 'Escolha um bot na lista.'; return $null }\n  return $lista.SelectedItems[0].Tag\n}\n\n$btIniciar.Add_Click({\n  $b = Selecionado\n  if (-not $b) { return }\n  if ($b.Situacao -like '*antigo') {\n    if (-not (Pergunta \"Este é uma cópia ANTIGA do bot $($b.Nome). Tem uma versão mais nova na lista.`n`nIniciar esta mesmo assim?\" 'Warning')) { return }\n  }\n  try { Iniciar $b; Preencher } catch { Aviso \"Não consegui iniciar: $($_.Exception.Message)\" 'Error' }\n})\n$lista.Add_DoubleClick({ $btIniciar.PerformClick() })\n\n$btAbrir.Add_Click({\n  $b = Selecionado\n  if ($b) { Start-Process explorer.exe -ArgumentList \"`\"$($b.Pasta)`\"\" }\n})\n\n$btApagar.Add_Click({\n  $b = Selecionado\n  if (-not $b) { return }\n  $novo = $script:bots | Where-Object { $_.Nome -eq $b.Nome -and $_.Situacao -eq 'mais novo' } | Select-Object -First 1\n  $texto = \"Mandar para a Lixeira a pasta do bot $($b.Nome)?`n`n$($b.Pasta)`n`nVersão de $($b.Versao.ToString($fmt))\"\n  $icone = 'Question'\n  if ($novo -and $novo.Pasta -ne $b.Pasta -and $b.Atividade -and (-not $novo.Atividade -or $b.Atividade -gt $novo.Atividade)) {\n    $texto += \"`n`nATENÇÃO: esta cópia tem dados MAIS RECENTES que a versão nova. Transfira os dados antes (Transferir dados.bat) ou você pode perder XP, dinheiro e configurações.\"\n    $icone = 'Warning'\n  } elseif ($b.Situacao -eq 'mais novo' -or -not $novo) {\n    $texto += \"`n`nEsta é a versão mais nova (ou a única) deste bot.\"\n    $icone = 'Warning'\n  }\n  $texto += \"`n`nFeche o bot antes, se ele estiver ligado. Dá para recuperar pela Lixeira.\"\n  if (-not (Pergunta $texto $icone)) { return }\n  try {\n    [Microsoft.VisualBasic.FileIO.FileSystem]::DeleteDirectory($b.Pasta, 'OnlyErrorDialogs', 'SendToRecycleBin')\n    $restantes = @($script:bots | Where-Object { $_.Pasta -ne $b.Pasta } | ForEach-Object { $_.Pasta })\n    SalvarCache $restantes\n    Carregar $false\n  } catch {\n    Aviso \"Não consegui apagar (o bot está ligado ou algum arquivo está aberto?).`n`n$($_.Exception.Message)\" 'Error'\n  }\n})\n\n$btProcurar.Add_Click({ Carregar $true })\n$btFechar.Add_Click({ $form.Close() })\n$form.Add_Shown({ Carregar $false })\n\ntry {\n  [void]$form.ShowDialog()\n} catch {\n  Aviso \"Algo deu errado: $($_.Exception.Message)\" 'Error'\n  exit 1\n}\n",
  "extras/inicializador/Iniciar bot.bat": "@echo off\nrem Inicializador: dois cliques para escolher e ligar o seu bot (pode ficar em qualquer pasta).\ntitle Inicializador de bots\npowershell -NoProfile -ExecutionPolicy Bypass -STA -File \"%~dp0inicializador.ps1\"\nif errorlevel 1 pause\n",
  "extras/transferidor/Transferir dados.bat": "@echo off\nrem Transferidor de dados: de dois cliques neste arquivo (ele fica dentro da pasta do bot NOVO).\ntitle Transferir dados do bot\npowershell -NoProfile -ExecutionPolicy Bypass -STA -File \"%~dp0transferir-dados.ps1\"\nif errorlevel 1 pause\n",
  "extras/transferidor/transferir-dados.ps1": "﻿# Transferidor de dados do bot (usado pelo \"Transferir dados.bat\").\n# Copia a pasta \"data\" e o arquivo \".env\" de um bot antigo para este bot (a pasta onde este arquivo está).\n# Nada é apagado: os dados que este bot já tinha vão para uma pasta \"data-backup-...\".\n\n$ErrorActionPreference = 'Stop'\nAdd-Type -AssemblyName System.Windows.Forms\n[System.Windows.Forms.Application]::EnableVisualStyles()\n\n$titulo = 'Transferir dados do bot'\nfunction Aviso([string]$texto, [string]$icone = 'Information') {\n  [void][System.Windows.Forms.MessageBox]::Show($texto, $titulo, 'OK', $icone)\n}\nfunction UltimaMudanca($arquivos) {\n  if (-not $arquivos) { return $null }\n  return ($arquivos | Sort-Object LastWriteTime -Descending | Select-Object -First 1).LastWriteTime\n}\nfunction NomeDoBot([string]$pasta) {\n  try { return (Get-Content (Join-Path $pasta 'config.json') -Raw -Encoding UTF8 | ConvertFrom-Json).nome } catch { return '(sem nome)' }\n}\n\ntry {\n  $destino = $PSScriptRoot\n  if (-not (Test-Path (Join-Path $destino 'index.js')) -or -not (Test-Path (Join-Path $destino 'config.json'))) {\n    Aviso \"Este arquivo precisa ficar dentro da pasta do bot NOVO (junto do index.js).`n`nPasta atual:`n$destino\" 'Warning'\n    exit 1\n  }\n\n  # 1) escolher a pasta do bot antigo\n  $janela = New-Object System.Windows.Forms.FolderBrowserDialog\n  $janela.Description = 'Escolha a pasta do bot ANTIGO (a que tem os dados que você quer manter)'\n  $janela.ShowNewFolderButton = $false\n  if ($janela.ShowDialog() -ne [System.Windows.Forms.DialogResult]::OK) { exit 0 }\n  $origem = $janela.SelectedPath\n\n  # se escolheu a própria pasta \"data\", sobe um nível\n  if ((Split-Path $origem -Leaf) -ieq 'data' -and (Test-Path (Join-Path (Split-Path $origem -Parent) 'config.json'))) {\n    $origem = Split-Path $origem -Parent\n  }\n  if ((Resolve-Path $origem).Path.TrimEnd('\\') -ieq (Resolve-Path $destino).Path.TrimEnd('\\')) {\n    Aviso 'Você escolheu a pasta deste mesmo bot. Escolha a pasta do bot ANTIGO.' 'Warning'\n    exit 1\n  }\n\n  # 2) conferir se é mesmo um bot com dados\n  $dataOrigem = Join-Path $origem 'data'\n  $arqOrigem = @(Get-ChildItem $dataOrigem -Filter '*.json' -File -ErrorAction SilentlyContinue)\n  if (-not (Test-Path (Join-Path $origem 'config.json')) -or $arqOrigem.Count -eq 0) {\n    Aviso \"Essa pasta não parece ser um bot com dados (não achei config.json e a pasta data com arquivos).`n`n$origem\" 'Warning'\n    exit 1\n  }\n\n  $dataDestino = Join-Path $destino 'data'\n  $arqDestino = @(Get-ChildItem $dataDestino -Filter '*.json' -File -ErrorAction SilentlyContinue)\n  $ultimaOrigem = UltimaMudanca $arqOrigem\n  $ultimaDestino = UltimaMudanca $arqDestino\n  $temEnv = Test-Path (Join-Path $origem '.env')\n  $fmt = 'dd/MM/yyyy HH:mm'\n\n  # 3) resumo e confirmação\n  $linhas = @(\n    \"DE (bot antigo): $(NomeDoBot $origem)\",\n    $origem,\n    \"$($arqOrigem.Count) arquivo(s) de dados · última atividade em $($ultimaOrigem.ToString($fmt))\",\n    '',\n    \"PARA (este bot): $(NomeDoBot $destino)\",\n    $destino,\n    ''\n  )\n  if ($temEnv) { $linhas += 'O token (.env) também será copiado.' } else { $linhas += 'Não achei o .env no bot antigo: configure o token depois.' }\n  if ($arqDestino.Count -gt 0) {\n    $linhas += \"Os $($arqDestino.Count) arquivo(s) de dados que este bot já tem vão para uma cópia de segurança.\"\n    if ($ultimaDestino -gt $ultimaOrigem) {\n      $linhas += ''\n      $linhas += \"ATENÇÃO: este bot tem dados MAIS NOVOS ($($ultimaDestino.ToString($fmt))) que o antigo ($($ultimaOrigem.ToString($fmt))). Confira se escolheu as pastas certas.\"\n    }\n  }\n  $linhas += ''\n  $linhas += 'Antes de continuar, DESLIGUE o bot antigo (feche o terminal dele).'\n  $linhas += ''\n  $linhas += 'Copiar agora?'\n  $icone = if ($ultimaDestino -and $ultimaDestino -gt $ultimaOrigem) { 'Warning' } else { 'Question' }\n  $resp = [System.Windows.Forms.MessageBox]::Show(($linhas -join \"`n\"), $titulo, 'YesNo', $icone)\n  if ($resp -ne [System.Windows.Forms.DialogResult]::Yes) { exit 0 }\n\n  # 4) cópia de segurança do que este bot já tinha\n  $carimbo = Get-Date -Format 'yyyy-MM-dd_HH-mm-ss'\n  $backup = $null\n  if (Test-Path $dataDestino) {\n    $backup = Join-Path $destino \"data-backup-$carimbo\"\n    Move-Item $dataDestino $backup\n  }\n\n  # 5) copia os dados e o token\n  Copy-Item $dataOrigem $dataDestino -Recurse -Force\n  if ($temEnv) {\n    $envDestino = Join-Path $destino '.env'\n    if (Test-Path $envDestino) { Copy-Item $envDestino (Join-Path $destino \".env.backup-$carimbo\") -Force }\n    Copy-Item (Join-Path $origem '.env') $envDestino -Force\n  }\n\n  # 6) instala as dependências, se ainda não instalou\n  $instalou = $true\n  if (-not (Test-Path (Join-Path $destino 'node_modules'))) {\n    if (Get-Command npm -ErrorAction SilentlyContinue) {\n      Write-Host 'Instalando as dependências do bot (npm install)... aguarde.'\n      Push-Location $destino\n      & npm install --no-audit --no-fund\n      $instalou = ($LASTEXITCODE -eq 0)\n      Pop-Location\n    } else { $instalou = $false }\n  }\n\n  $fim = @(\"Pronto! $($arqOrigem.Count) arquivo(s) de dados copiados.\")\n  if ($backup) { $fim += \"Os dados antigos deste bot estão guardados em: $(Split-Path $backup -Leaf)\" }\n  if (-not $instalou) { $fim += ''; $fim += 'Falta instalar: abra um terminal nesta pasta e rode  npm install  (precisa do Node.js).' }\n  $fim += ''\n  $fim += 'Agora é só ligar este bot (npm start). Pode apagar a pasta do bot antigo depois de conferir que está tudo certo.'\n  Aviso ($fim -join \"`n\")\n  exit 0\n} catch {\n  Aviso \"Algo deu errado e nada foi apagado.`n`n$($_.Exception.Message)\" 'Error'\n  exit 1\n}\n",
  "index.js": "import './src/core/env.js';\nimport {\n  ActivityType,\n  Client,\n  Events,\n  GatewayIntentBits,\n  InteractionContextType,\n  MessageFlags,\n  OAuth2Scopes,\n  PermissionFlagsBits,\n  PermissionsBitField,\n  REST,\n  Routes,\n  SlashCommandBuilder,\n} from 'discord.js';\nimport { CONFIG } from './src/core/util.js';\nimport { salvarTudo } from './src/core/db.js';\nimport nucleo, { registrarModulos } from './src/core/nucleo.js';\n\nconst token = process.env.DISCORD_TOKEN;\nif (!token) {\n  console.error('❌ Falta o token do bot. Copie o arquivo .env.example para .env e preencha DISCORD_TOKEN (veja o README).');\n  process.exit(1);\n}\n\n// ---------------- módulos ----------------\n// A lista vem do config.json. Cada módulo é um arquivo em src/modules.\nconst modulos = [nucleo];\nfor (const id of CONFIG.modulos ?? []) {\n  try {\n    const m = (await import(`./src/modules/${id}.js`)).default;\n    modulos.push(m);\n  } catch (e) {\n    console.error(`❌ Não consegui carregar o módulo \"${id}\": ${e.message}`);\n  }\n}\nregistrarModulos(modulos);\n\nconst intents = new Set([GatewayIntentBits.Guilds]);\nconst partials = new Set();\n// permissões que o bot pede no link de convite: as básicas + as de cada módulo\nconst permissoes = new PermissionsBitField([\n  PermissionFlagsBits.ViewChannel,\n  PermissionFlagsBits.SendMessages,\n  PermissionFlagsBits.SendMessagesInThreads,\n  PermissionFlagsBits.EmbedLinks,\n  PermissionFlagsBits.AttachFiles,\n  PermissionFlagsBits.ReadMessageHistory,\n  PermissionFlagsBits.UseExternalEmojis,\n  PermissionFlagsBits.AddReactions,\n]);\nfor (const m of modulos) {\n  for (const x of m.intents ?? []) intents.add(x);\n  for (const p of m.partials ?? []) partials.add(p);\n  for (const p of m.permissoes ?? []) permissoes.add(p);\n}\n\nconst client = new Client({ intents: [...intents], partials: [...partials] });\n\n// ---------------- comandos ----------------\nconst comandos = new Map();\nfor (const m of modulos) {\n  for (const c of m.comandos ?? []) comandos.set(c.data.name, { ...c, modulo: m });\n}\n\n// /config: os subcomandos gerais + um grupo para cada módulo que tem configuração\nconst config = new SlashCommandBuilder()\n  .setName('config')\n  .setDescription('Configura o bot neste servidor')\n  .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild);\nnucleo.montarConfigRaiz(config);\nfor (const m of modulos) {\n  if (m.config?.montar) config.addSubcommandGroup((g) => m.config.montar(g.setName(m.config.grupo)));\n}\ncomandos.set('config', {\n  data: config,\n  modulo: nucleo,\n  async executar(i) {\n    const grupo = i.options.getSubcommandGroup(false);\n    const sub = i.options.getSubcommand();\n    if (!grupo) return nucleo.executarConfigRaiz(i, sub);\n    const m = modulos.find((x) => x.config?.grupo === grupo);\n    return m?.config.executar(i, sub);\n  },\n});\n\n// todos os comandos funcionam só dentro de servidores\nfor (const c of comandos.values()) c.data.setContexts?.(InteractionContextType.Guild);\n\n// botões, menus e formulários: o customId começa com o prefixo do módulo (\"tk:abrir\", \"sr:entrar:123\"...)\nconst componentes = new Map();\nconst prefixosDM = new Set(); // botões que também funcionam na DM (ex.: avaliação de atendimento)\nfor (const m of modulos) {\n  for (const [prefixo, fn] of Object.entries(m.componentes ?? {})) componentes.set(prefixo, fn);\n  for (const prefixo of m.componentesDM ?? []) prefixosDM.add(prefixo);\n}\n\n// ---------------- eventos dos módulos ----------------\n// Cada evento chama os módulos em sequência. Quem tem \"prioridade\" menor roda antes\n// (o AutoMod roda primeiro: assim os outros já sabem se a mensagem foi apagada).\nconst eventos = new Map();\nfor (const m of [...modulos].sort((a, b) => (a.prioridade ?? 10) - (b.prioridade ?? 10))) {\n  for (const [nome, fn] of Object.entries(m.eventos ?? {})) {\n    if (!eventos.has(nome)) eventos.set(nome, []);\n    eventos.get(nome).push({ fn, modulo: m.id });\n  }\n}\nfor (const [nome, lista] of eventos) {\n  client.on(nome, async (...args) => {\n    for (const { fn, modulo } of lista) {\n      try {\n        await fn(...args);\n      } catch (e) {\n        console.error(`[${modulo}] erro no evento ${nome}:`, e);\n      }\n    }\n  });\n}\n\n// ---------------- interações ----------------\nasync function avisarErro(i) {\n  const payload = { content: '❌ Algo deu errado. Tente de novo em instantes.', flags: MessageFlags.Ephemeral };\n  if (i.deferred || i.replied) await i.followUp(payload).catch(() => {});\n  else await i.reply(payload).catch(() => {});\n}\n\nclient.on(Events.InteractionCreate, async (i) => {\n  if (!i.inGuild()) {\n    // fora de servidor, só os botões/formulários que os módulos liberaram para a DM\n    const componente = i.isButton() || i.isAnySelectMenu() || i.isModalSubmit();\n    if (!componente || !prefixosDM.has(i.customId.split(':')[0])) return;\n  }\n  try {\n    if (i.isAutocomplete()) {\n      const c = comandos.get(i.commandName);\n      if (c?.autocompletar) await c.autocompletar(i);\n      return;\n    }\n    if (i.isChatInputCommand()) {\n      const c = comandos.get(i.commandName);\n      if (c) await c.executar(i);\n      return;\n    }\n    if (i.isButton() || i.isAnySelectMenu() || i.isModalSubmit()) {\n      const partes = i.customId.split(':');\n      const fn = componentes.get(partes[0]);\n      if (fn) await fn(i, partes.slice(1));\n    }\n  } catch (e) {\n    console.error('[interação] erro:', e);\n    if (i.isRepliable()) await avisarErro(i);\n  }\n});\n\n// ---------------- ligar ----------------\nclient.once(Events.ClientReady, async (c) => {\n  console.log(`✅ ${CONFIG.nome || c.user.username} online como ${c.user.tag} · em ${c.guilds.cache.size} servidor(es)`);\n  console.log(`   Módulos: ${modulos.map((m) => m.nome).join(', ')}`);\n  const convite = c.generateInvite({ scopes: [OAuth2Scopes.Bot, OAuth2Scopes.ApplicationsCommands], permissions: permissoes });\n  console.log(`   Link para adicionar o bot a um servidor:\\n   ${convite}`);\n\n  const corpo = [...comandos.values()].map((x) => x.data.toJSON());\n  const rest = new REST({ version: '10' }).setToken(token);\n  try {\n    if (process.env.GUILD_ID) {\n      await rest.put(Routes.applicationGuildCommands(c.user.id, process.env.GUILD_ID), { body: corpo });\n      console.log(`   ${corpo.length} comandos registrados no servidor ${process.env.GUILD_ID}.`);\n    } else {\n      await rest.put(Routes.applicationCommands(c.user.id), { body: corpo });\n      console.log(`   ${corpo.length} comandos registrados em todos os servidores.`);\n    }\n  } catch (e) {\n    console.error('❌ Não consegui registrar os comandos:', e.message);\n  }\n\n  if (CONFIG.status) c.user.setPresence({ activities: [{ type: ActivityType.Custom, name: 'status', state: CONFIG.status }] });\n\n  for (const m of modulos) {\n    try {\n      await m.aoIniciar?.(c);\n    } catch (e) {\n      console.error(`[${m.id}] erro ao iniciar:`, e);\n    }\n  }\n});\n\n// salva os dados antes de desligar\nfor (const sinal of ['SIGINT', 'SIGTERM']) {\n  process.on(sinal, () => {\n    salvarTudo();\n    process.exit(0);\n  });\n}\nprocess.on('unhandledRejection', (e) => console.error('[erro]', e));\n\nclient.login(token).catch((e) => {\n  console.error('❌ Não consegui entrar no Discord:', e.message);\n  if (e.code === 'TokenInvalid' || /invalid token/i.test(e.message)) {\n    console.error('   O token está errado. Gere outro no Developer Portal → Bot → Reset Token e cole no .env.');\n  }\n  if (/disallowed intents/i.test(e.message)) {\n    console.error('   Ative as \"Privileged Gateway Intents\" pedidas no README, no Developer Portal → Bot.');\n  }\n  process.exit(1);\n});\n",
  "package.json": "{\n  \"name\": \"meu-bot\",\n  \"version\": \"1.0.0\",\n  \"private\": true,\n  \"type\": \"module\",\n  \"main\": \"index.js\",\n  \"scripts\": {\n    \"start\": \"node index.js\"\n  },\n  \"engines\": {\n    \"node\": \">=18.17\"\n  },\n  \"dependencies\": {\n    \"discord.js\": \"^14.16.3\",\n    \"dotenv\": \"^16.4.7\"\n  }\n}\n",
  "src/core/db.js": "import fs from 'node:fs';\nimport path from 'node:path';\nimport { fileURLToPath } from 'node:url';\n\n/**\n * Armazenamento simples em arquivos JSON (pasta \"data\", ao lado do index.js).\n * Não precisa instalar banco de dados: cada coleção vira um arquivo, ex.: data/niveis.json.\n * Para fazer backup, basta copiar a pasta \"data\".\n *\n *   const niveis = colecao('niveis');\n *   const membro = niveis.de(guildId, userId);   // cria o objeto se não existir\n *   membro.xp = (membro.xp ?? 0) + 10;\n *   niveis.salvar();                            // grava em até 1,5 s (junta várias mudanças)\n */\n\nconst PASTA = fileURLToPath(new URL('../../data', import.meta.url));\nfs.mkdirSync(PASTA, { recursive: true });\n\nconst cache = new Map();\nconst timers = new Map();\nconst arquivo = (nome) => path.join(PASTA, `${nome}.json`);\n\nfunction carregar(nome) {\n  if (cache.has(nome)) return cache.get(nome);\n  let dados = {};\n  try {\n    dados = JSON.parse(fs.readFileSync(arquivo(nome), 'utf8'));\n  } catch (e) {\n    if (e.code !== 'ENOENT') {\n      // arquivo corrompido: guarda uma cópia e começa do zero, sem derrubar o bot\n      const copia = arquivo(`${nome}.corrompido-${Date.now()}`);\n      try { fs.renameSync(arquivo(nome), copia); } catch { /* sem cópia */ }\n      console.error(`[dados] ${nome}.json estava corrompido. Cópia salva em ${copia}`);\n    }\n  }\n  cache.set(nome, dados);\n  return dados;\n}\n\nfunction gravar(nome) {\n  const tmp = `${arquivo(nome)}.tmp`;\n  fs.writeFileSync(tmp, JSON.stringify(cache.get(nome)));\n  fs.renameSync(tmp, arquivo(nome)); // troca de uma vez: o arquivo nunca fica pela metade\n}\n\nfunction agendar(nome) {\n  if (timers.has(nome)) return;\n  timers.set(nome, setTimeout(() => {\n    timers.delete(nome);\n    try { gravar(nome); } catch (e) { console.error(`[dados] Falha ao salvar ${nome}:`, e.message); }\n  }, 1500));\n}\n\nexport function colecao(nome) {\n  const raiz = carregar(nome);\n  return {\n    /** Objeto em raiz[a][b]..., criado se não existir. */\n    de(...chaves) {\n      let o = raiz;\n      for (const k of chaves) {\n        if (o[k] == null || typeof o[k] !== 'object') o[k] = {};\n        o = o[k];\n      }\n      return o;\n    },\n    /** Lê raiz[a][b]... sem criar nada. */\n    ler(...chaves) {\n      let o = raiz;\n      for (const k of chaves) {\n        if (o == null) return undefined;\n        o = o[k];\n      }\n      return o;\n    },\n    apagar(...chaves) {\n      const ultima = chaves.pop();\n      const pai = this.ler(...chaves);\n      if (pai && ultima in pai) delete pai[ultima];\n      agendar(nome);\n    },\n    raiz,\n    salvar() { agendar(nome); },\n  };\n}\n\n/** Grava tudo na hora (usado ao desligar o bot). */\nexport function salvarTudo() {\n  for (const nome of cache.keys()) {\n    clearTimeout(timers.get(nome));\n    timers.delete(nome);\n    try { gravar(nome); } catch (e) { console.error(`[dados] Falha ao salvar ${nome}:`, e.message); }\n  }\n}\n",
  "src/core/env.js": "import { fileURLToPath } from 'node:url';\nimport dotenv from 'dotenv';\n\n// Lê o arquivo .env da pasta do bot (funciona mesmo se o bot for iniciado de outra pasta).\ndotenv.config({ path: fileURLToPath(new URL('../../.env', import.meta.url)), quiet: true });\n",
  "src/core/nucleo.js": "import { SlashCommandBuilder, version as djsVersion } from 'discord.js';\nimport { CONFIG, ajustes, salvarAjustes, embed, responder, responderCampos, duracaoTexto, fmt } from './util.js';\n\n/**\n * Núcleo: vem em todo bot. /ajuda, /ping, /sobre e o começo do /config\n * (/config ver, /config cor, /config staff). Cada módulo instalado acrescenta\n * o seu grupo dentro do /config (ex.: /config logs canal).\n */\n\nlet MODULOS = [];\nexport const registrarModulos = (lista) => { MODULOS = lista; };\n\nconst ajuda = {\n  data: new SlashCommandBuilder().setName('ajuda').setDescription('Mostra todos os comandos do bot'),\n  async executar(i) {\n    const campos = [];\n    for (const m of MODULOS) {\n      const linhas = (m.comandos ?? []).map((c) => `\\`/${c.data.name}\\` · ${c.data.description}`);\n      if (m.config?.grupo) linhas.push(`\\`/config ${m.config.grupo}\\` · configurar este módulo`);\n      if (!linhas.length) continue;\n      // um campo aceita até 1024 caracteres: quebra em partes se precisar\n      let atual = '';\n      let parte = 0;\n      for (const l of linhas) {\n        if ((atual + l + '\\n').length > 1000) {\n          campos.push({ name: parte ? `${m.nome} (cont.)` : m.nome, value: atual });\n          atual = '';\n          parte++;\n        }\n        atual += `${l}\\n`;\n      }\n      if (atual) campos.push({ name: parte ? `${m.nome} (cont.)` : m.nome, value: atual });\n    }\n    await responderCampos(\n      i,\n      () =>\n        embed(i.guildId)\n          .setTitle(`📖 Comandos do ${CONFIG.nome || i.client.user.username}`)\n          .setThumbnail(i.client.user.displayAvatarURL())\n          .setFooter({ text: 'Administradores: use /config ver para ver tudo o que está configurado' }),\n      campos\n    );\n  },\n};\n\nconst ping = {\n  data: new SlashCommandBuilder().setName('ping').setDescription('Mostra a latência do bot'),\n  async executar(i) {\n    const inicio = Date.now();\n    await i.deferReply();\n    const api = Date.now() - inicio;\n    const ws = i.client.ws.ping;\n    await i.editReply({\n      embeds: [\n        embed(i.guildId)\n          .setTitle('🏓 Pong!')\n          .addFields(\n            { name: 'Conexão (gateway)', value: ws >= 0 ? `${ws} ms` : 'medindo…', inline: true },\n            { name: 'Resposta', value: `${api} ms`, inline: true },\n          ),\n      ],\n    });\n  },\n};\n\nconst sobre = {\n  data: new SlashCommandBuilder().setName('sobre').setDescription('Informações sobre o bot'),\n  async executar(i) {\n    const c = i.client;\n    const membros = c.guilds.cache.reduce((t, g) => t + (g.memberCount || 0), 0);\n    const nomes = MODULOS.filter((m) => m.id !== 'nucleo').map((m) => m.nome);\n    await i.reply({\n      embeds: [\n        embed(i.guildId)\n          .setTitle(CONFIG.nome || c.user.username)\n          .setThumbnail(c.user.displayAvatarURL())\n          .addFields(\n            { name: 'Servidores', value: fmt(c.guilds.cache.size), inline: true },\n            { name: 'Membros', value: fmt(membros), inline: true },\n            { name: 'Online há', value: duracaoTexto(c.uptime ?? 0), inline: true },\n            { name: 'Módulos', value: nomes.length ? nomes.join(', ') : 'nenhum' },\n          )\n          .setFooter({ text: `discord.js ${djsVersion} · Node ${process.versions.node}` }),\n      ],\n    });\n  },\n};\n\n/** Subcomandos \"soltos\" do /config (sem grupo). */\nfunction montarConfigRaiz(cmd) {\n  return cmd\n    .addSubcommand((s) => s.setName('ver').setDescription('Mostra tudo o que está configurado neste servidor'))\n    .addSubcommand((s) =>\n      s\n        .setName('cor')\n        .setDescription('Cor das mensagens do bot neste servidor')\n        .addStringOption((o) => o.setName('cor').setDescription('Em hexadecimal, ex.: #5865F2').setRequired(true).setMaxLength(7))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('staff')\n        .setDescription('Cargo da equipe (atende tickets, aprova sugestões...)')\n        .addRoleOption((o) => o.setName('cargo').setDescription('Deixe vazio para remover').setRequired(false))\n    );\n}\n\nasync function executarConfigRaiz(i, sub) {\n  const geral = ajustes(i.guildId, 'geral', { cor: null, staff: null });\n  if (sub === 'cor') {\n    const valor = i.options.getString('cor').trim();\n    if (!/^#?[0-9a-f]{6}$/i.test(valor)) return responder(i, 'Use uma cor em hexadecimal, como **#5865F2**.', 'erro');\n    geral.cor = valor.startsWith('#') ? valor : `#${valor}`;\n    salvarAjustes();\n    return responder(i, `Cor definida para **${geral.cor}**.`, 'sucesso');\n  }\n  if (sub === 'staff') {\n    const cargo = i.options.getRole('cargo');\n    geral.staff = cargo?.id ?? null;\n    salvarAjustes();\n    return responder(i, cargo ? `Cargo da equipe: ${cargo}.` : 'Cargo da equipe removido.', 'sucesso');\n  }\n  if (sub === 'ver') {\n    const campos = [\n      {\n        name: 'Geral',\n        value: [`Cor: **${geral.cor || CONFIG.cor || 'padrão'}**`, `Equipe: ${geral.staff ? `<@&${geral.staff}>` : 'não definida (só quem tem Gerenciar servidor)'}`].join('\\n'),\n      },\n    ];\n    for (const m of MODULOS) {\n      if (!m.config?.resumo) continue;\n      const linhas = await m.config.resumo(i.guild);\n      if (linhas?.length) campos.push({ name: m.nome, value: linhas.join('\\n') });\n    }\n    return responderCampos(i, () => embed(i.guildId).setTitle('⚙️ Configuração deste servidor'), campos, { efemero: true });\n  }\n}\n\nexport default {\n  id: 'nucleo',\n  nome: 'Geral',\n  comandos: [ajuda, ping, sobre],\n  montarConfigRaiz,\n  executarConfigRaiz,\n};\n",
  "src/core/util.js": "import fs from 'node:fs';\nimport { EventEmitter } from 'node:events';\nimport { EmbedBuilder, MessageFlags, PermissionFlagsBits } from 'discord.js';\nimport { colecao } from './db.js';\n\n/** config.json: nome do bot, cor padrão e módulos instalados. */\nexport const CONFIG = JSON.parse(fs.readFileSync(new URL('../../config.json', import.meta.url), 'utf8'));\n\n// ---------------- ajustes por servidor ----------------\nconst ajustesDb = colecao('ajustes');\n\n/**\n * Ajustes de um módulo neste servidor. Campos que faltarem recebem o padrão.\n * Altere o objeto devolvido e chame salvarAjustes().\n */\nexport function ajustes(guildId, modulo, padrao = {}) {\n  const g = ajustesDb.de(guildId, modulo);\n  for (const [k, v] of Object.entries(padrao)) {\n    if (!(k in g)) g[k] = structuredClone(v);\n  }\n  return g;\n}\nexport const salvarAjustes = () => ajustesDb.salvar();\n\n// ---------------- aparência ----------------\nexport function cor(guildId) {\n  const c = guildId ? ajustesDb.ler(guildId, 'geral', 'cor') : null;\n  return parseInt(String(c || CONFIG.cor || '#5865F2').replace('#', ''), 16);\n}\n\nexport const embed = (guildId) => new EmbedBuilder().setColor(cor(guildId));\n\nexport const CORES = { sucesso: 0x22c55e, erro: 0xef4444, aviso: 0xf59e0b };\n\n/** Resposta curta só para quem usou o comando. */\nexport async function responder(i, texto, tipo = 'info') {\n  const icone = { sucesso: '✅', erro: '❌', aviso: '⚠️', info: 'ℹ️' }[tipo] ?? '';\n  const e = new EmbedBuilder()\n    .setColor(CORES[tipo] ?? cor(i.guildId))\n    .setDescription(`${icone} ${texto}`.trim());\n  const payload = { embeds: [e], flags: MessageFlags.Ephemeral };\n  if (i.deferred || i.replied) return i.followUp(payload).catch(() => null);\n  return i.reply(payload).catch(() => null);\n}\n\n// ---------------- texto e números ----------------\nexport const fmt = (n) => Number(n || 0).toLocaleString('pt-BR');\n\nexport const cortar = (t, n) => {\n  const s = String(t ?? '');\n  return s.length > n ? `${s.slice(0, n - 1)}…` : s;\n};\n\n/** Troca {chave} pelos valores. Chaves desconhecidas ficam como estão. */\nexport const preencher = (modelo, vars) =>\n  String(modelo ?? '').replace(/\\{(\\w+)\\}/g, (m, k) => (k in vars ? String(vars[k]) : m));\n\nexport function barra(fracao, tamanho = 12) {\n  const f = Math.max(0, Math.min(1, fracao || 0));\n  const cheio = Math.round(f * tamanho);\n  return '▰'.repeat(cheio) + '▱'.repeat(tamanho - cheio);\n}\n\n/** \"10m\", \"1h30m\", \"2d\", \"45s\", \"1w\" → milissegundos (null se inválido). */\nexport function lerDuracao(texto) {\n  const s = String(texto || '').toLowerCase().replace(/\\s+/g, '');\n  if (!s) return null;\n  // as palavras mais longas vêm antes (\"min\" antes de \"m\"), senão \"10min\" não seria entendido\n  const re = /(\\d+)(segundos?|seg|minutos?|min|horas?|dias?|semanas?|sem|s|m|h|d|w)/g;\n  const UNIDADE = { s: 1e3, m: 6e4, h: 36e5, d: 864e5, w: 6048e5 };\n  const mult = (u) => UNIDADE[u.startsWith('seg') ? 's' : u.startsWith('min') ? 'm' : u.startsWith('hora') ? 'h' : u.startsWith('dia') ? 'd' : u.startsWith('sem') ? 'w' : u];\n  let total = 0, lido = '';\n  for (const m of s.matchAll(re)) {\n    total += Number(m[1]) * mult(m[2]);\n    lido += m[0];\n  }\n  return lido === s && total > 0 ? total : null;\n}\n\nexport function duracaoTexto(ms) {\n  const s = Math.round(ms / 1000);\n  const partes = [];\n  const d = Math.floor(s / 86400), h = Math.floor((s % 86400) / 3600), m = Math.floor((s % 3600) / 60), seg = s % 60;\n  if (d) partes.push(`${d}d`);\n  if (h) partes.push(`${h}h`);\n  if (m) partes.push(`${m}min`);\n  if (!d && !h && seg) partes.push(`${seg}s`);\n  return partes.join(' ') || '0s';\n}\n\nexport const ts = (ms, estilo = 'R') => `<t:${Math.floor(ms / 1000)}:${estilo}>`;\n\n// ---------------- permissões ----------------\n/** Tem \"Gerenciar servidor\" ou o cargo de staff definido em /config staff? */\nexport function ehStaff(member) {\n  if (!member) return false;\n  if (member.permissions?.has(PermissionFlagsBits.ManageGuild)) return true;\n  const staff = ajustesDb.ler(member.guild.id, 'geral', 'staff');\n  return Boolean(staff && member.roles?.cache?.has(staff));\n}\n\n/**\n * Confere se `autor` pode punir `alvo` (dono, hierarquia de cargos, o próprio bot).\n * Devolve uma mensagem de erro ou null.\n */\nexport function checarHierarquia(autor, alvo, bot) {\n  if (!alvo) return null;\n  if (alvo.id === autor.id) return 'Você não pode usar isso em você mesmo.';\n  if (alvo.id === alvo.guild.ownerId) return 'Não dá para punir o dono do servidor.';\n  if (alvo.id === bot.id) return 'Não posso fazer isso comigo mesmo.';\n  if (autor.id !== autor.guild.ownerId && alvo.roles.highest.position >= autor.roles.highest.position) {\n    return 'Esse membro tem um cargo igual ou maior que o seu.';\n  }\n  if (alvo.roles.highest.position >= bot.roles.highest.position) {\n    return 'Esse membro tem um cargo igual ou maior que o meu. Suba o meu cargo na lista de cargos.';\n  }\n  return null;\n}\n\nexport const sorteio = (min, max) => Math.floor(Math.random() * (max - min + 1)) + min;\n\n// ---------------- mensagens apagadas pelo AutoMod ----------------\n// O AutoMod marca o que apagou: assim os Níveis não dão XP por ela e os Logs não registram em dobro.\nconst removidas = new Map(); // id da mensagem -> expira em\nexport function marcarRemovida(id) {\n  const agora = Date.now();\n  removidas.set(id, agora + 60_000);\n  if (removidas.size > 300) for (const [k, t] of removidas) if (t < agora) removidas.delete(k);\n}\nexport const foiRemovida = (id) => (removidas.get(id) ?? 0) > Date.now();\n\n// ---------------- respostas longas ----------------\nconst tamanhoEmbed = (e) => {\n  const d = e.data;\n  return (\n    (d.title?.length ?? 0) +\n    (d.description?.length ?? 0) +\n    (d.footer?.text?.length ?? 0) +\n    (d.author?.name?.length ?? 0) +\n    (d.fields ?? []).reduce((t, f) => t + f.name.length + f.value.length, 0)\n  );\n};\n\n/**\n * Responde com uma lista de campos que pode passar do limite do Discord\n * (6000 caracteres e 25 campos por mensagem): divide em várias mensagens.\n * `base()` deve devolver um EmbedBuilder novo (título, cor, rodapé...).\n */\nexport async function responderCampos(i, base, campos, { efemero = false } = {}) {\n  const partes = [];\n  let atual = base();\n  let n = 0;\n  for (const c of campos) {\n    const campo = { name: cortar(c.name, 256), value: cortar(c.value || '—', 1024), inline: c.inline ?? false };\n    if (n >= 25 || tamanhoEmbed(atual) + campo.name.length + campo.value.length > 5800) {\n      partes.push(atual);\n      atual = base().setTitle(null).setThumbnail(null).setAuthor(null);\n      n = 0;\n    }\n    atual.addFields(campo);\n    n++;\n  }\n  partes.push(atual);\n  const flags = efemero ? MessageFlags.Ephemeral : undefined;\n  await i.reply({ embeds: [partes[0]], flags, allowedMentions: { parse: [] } });\n  for (const e of partes.slice(1)) await i.followUp({ embeds: [e], flags, allowedMentions: { parse: [] } });\n}\n\n// ---------------- avisos entre módulos ----------------\n/**\n * Um módulo avisa, outro escuta (sem um depender do outro).\n * Ex.: o Tickets avisa \"ticketFechado\" e a Avaliação de atendimento pergunta a nota.\n *   sinais.emit('ticketFechado', { guild, dono, atendente, numero })\n *   sinais.on('ticketFechado', (dados) => { ... })\n */\nexport const sinais = new EventEmitter();\nsinais.setMaxListeners(50);\n",
  "src/modules/afk.js": "import { GatewayIntentBits, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { embed, responder, cortar, duracaoTexto, foiRemovida } from '../core/util.js';\n\n/**\n * AFK: /afk motivo. Quem marcar você recebe o aviso.\n * Quando você volta a falar, o AFK sai sozinho e o bot mostra quem te chamou.\n */\n\nconst afks = colecao('afk'); // guild -> user -> { motivo, desde, apelido, chamados: [] }\nconst avisados = new Map(); // anti-spam: \"canal:user\" -> quando avisou\nconst PREFIXO = '[AFK] ';\n\nasync function aoMensagem(msg) {\n  if (!msg.inGuild() || msg.author.bot || foiRemovida(msg.id)) return;\n\n  // 1) quem estava AFK voltou\n  const meu = afks.ler(msg.guildId, msg.author.id);\n  if (meu && Date.now() - meu.desde > 5000) {\n    afks.apagar(msg.guildId, msg.author.id);\n    if (msg.member?.manageable && msg.member.nickname?.startsWith(PREFIXO)) {\n      await msg.member.setNickname(meu.apelido ?? null, 'Voltou do AFK').catch(() => {});\n    }\n    const chamados = (meu.chamados ?? []).slice(-5);\n    const texto = `👋 Bem-vindo(a) de volta, ${msg.author}! Você ficou AFK por **${duracaoTexto(Date.now() - meu.desde)}**.${\n      chamados.length ? `\\nTe chamaram ${meu.chamados.length} vez(es):\\n${chamados.map((c) => `• <@${c.por}> em ${c.link}`).join('\\n')}` : ''\n    }`;\n    const aviso = await msg.reply({ embeds: [embed(msg.guildId).setDescription(texto)], allowedMentions: { users: [] } }).catch(() => null);\n    if (aviso) setTimeout(() => aviso.delete().catch(() => {}), 15_000);\n  }\n\n  // 2) alguém marcou (ou respondeu) quem está AFK\n  const alvos = new Set(msg.mentions.users.keys());\n  if (msg.mentions.repliedUser) alvos.add(msg.mentions.repliedUser.id);\n  alvos.delete(msg.author.id);\n  for (const id of alvos) {\n    const a = afks.ler(msg.guildId, id);\n    if (!a) continue;\n    (a.chamados ??= []).push({ por: msg.author.id, link: msg.url, em: Date.now() });\n    if (a.chamados.length > 20) a.chamados.shift();\n    afks.salvar();\n    const k = `${msg.channelId}:${id}`;\n    if (Date.now() - (avisados.get(k) ?? 0) < 30_000) continue; // um aviso a cada 30 s por canal\n    avisados.set(k, Date.now());\n    await msg\n      .reply({ content: `💤 <@${id}> está AFK${a.motivo ? `: ${a.motivo}` : ''} · <t:${Math.floor(a.desde / 1000)}:R>`, allowedMentions: { parse: [] } })\n      .catch(() => {});\n  }\n}\n\nconst afk = {\n  data: new SlashCommandBuilder()\n    .setName('afk')\n    .setDescription('Avisa que você está ausente')\n    .addStringOption((o) => o.setName('motivo').setDescription('Ex.: almoçando, dormindo...').setMaxLength(100)),\n  async executar(i) {\n    const motivo = (i.options.getString('motivo') ?? '').replace(/@/g, '@​');\n    const membro = i.member;\n    const apelidoAtual = membro.nickname;\n    afks.de(i.guildId)[i.user.id] = { motivo: cortar(motivo, 100), desde: Date.now(), apelido: apelidoAtual ?? null, chamados: [] };\n    afks.salvar();\n    if (membro.manageable && !(apelidoAtual ?? '').startsWith(PREFIXO)) {\n      await membro.setNickname(`${PREFIXO}${membro.displayName}`.slice(0, 32), 'AFK').catch(() => {});\n    }\n    return responder(i, `Você está AFK${motivo ? `: ${motivo}` : ''}. Quando mandar uma mensagem, o AFK sai sozinho.`, 'sucesso');\n  },\n};\n\nexport default {\n  id: 'afk',\n  nome: 'AFK',\n  intents: [GatewayIntentBits.GuildMessages],\n  permissoes: [PermissionFlagsBits.ManageNicknames],\n  comandos: [afk],\n  eventos: { messageCreate: aoMensagem },\n};\n",
  "src/modules/aniversarios.js": "import { ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { CONFIG, ajustes, salvarAjustes, embed, responder, preencher } from '../core/util.js';\n\n/**\n * Aniversários: cada membro cadastra o dia com /aniversario definir.\n * No dia, o bot dá parabéns no canal escolhido e (opcional) um cargo que dura 24 h.\n * O fuso é o do Brasil (America/Sao_Paulo); dá para trocar com \"fuso\" no config.json.\n */\n\nconst datas = colecao('aniversarios'); // guild -> user -> { dia, mes }\nconst PADRAO = { canal: null, cargo: null, mensagem: '🎂 Hoje é aniversário de {usuario}! Parabéns! 🎉', anunciados: {}, cargosAtivos: {} };\nconst cfg = (guildId) => ajustes(guildId, 'aniversarios', PADRAO);\nconst FUSO = CONFIG.fuso || 'America/Sao_Paulo';\nconst MESES = ['janeiro', 'fevereiro', 'março', 'abril', 'maio', 'junho', 'julho', 'agosto', 'setembro', 'outubro', 'novembro', 'dezembro'];\nconst DIAS_NO_MES = [31, 29, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31];\n\n/** Dia, mês e ano de hoje no fuso configurado. */\nfunction hoje() {\n  const p = Object.fromEntries(\n    new Intl.DateTimeFormat('en-US', { timeZone: FUSO, year: 'numeric', month: 'numeric', day: 'numeric' }).formatToParts(new Date()).map((x) => [x.type, x.value])\n  );\n  return { dia: Number(p.day), mes: Number(p.month), ano: Number(p.year) };\n}\nconst bissexto = (a) => (a % 4 === 0 && a % 100 !== 0) || a % 400 === 0;\n/** Quem nasceu em 29/02 comemora em 28/02 nos anos que não são bissextos. */\nconst fazHoje = (d, h) => (d.dia === h.dia && d.mes === h.mes) || (d.dia === 29 && d.mes === 2 && !bissexto(h.ano) && h.dia === 28 && h.mes === 2);\nconst dataTexto = (d) => `${d.dia} de ${MESES[d.mes - 1]}`;\n\nfunction diasAte(d, h) {\n  const base = Date.UTC(h.ano, h.mes - 1, h.dia);\n  let alvo = Date.UTC(h.ano, d.mes - 1, Math.min(d.dia, d.mes === 2 && !bissexto(h.ano) ? 28 : d.dia));\n  if (alvo < base) alvo = Date.UTC(h.ano + 1, d.mes - 1, Math.min(d.dia, d.mes === 2 && !bissexto(h.ano + 1) ? 28 : d.dia));\n  return Math.round((alvo - base) / 86400e3);\n}\n\nconst aniversario = {\n  data: new SlashCommandBuilder()\n    .setName('aniversario')\n    .setDescription('Aniversários do servidor')\n    .addSubcommand((s) =>\n      s\n        .setName('definir')\n        .setDescription('Cadastra o dia do seu aniversário')\n        .addIntegerOption((o) => o.setName('dia').setDescription('Dia').setRequired(true).setMinValue(1).setMaxValue(31))\n        .addIntegerOption((o) =>\n          o\n            .setName('mes')\n            .setDescription('Mês')\n            .setRequired(true)\n            .addChoices(...MESES.map((m, n) => ({ name: m, value: n + 1 })))\n        )\n    )\n    .addSubcommand((s) => s.setName('remover').setDescription('Apaga o seu aniversário'))\n    .addSubcommand((s) =>\n      s\n        .setName('ver')\n        .setDescription('Mostra o aniversário de alguém')\n        .addUserOption((o) => o.setName('usuario').setDescription('De quem (padrão: você)'))\n    )\n    .addSubcommand((s) => s.setName('proximos').setDescription('Os próximos aniversários do servidor'))\n    .addSubcommand((s) =>\n      s\n        .setName('configurar')\n        .setDescription('(Equipe) Canal dos parabéns, cargo do dia e mensagem')\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde dar os parabéns').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Cargo que o aniversariante ganha por 24 h'))\n        .addStringOption((o) => o.setName('mensagem').setDescription('Mensagem. Variáveis: {usuario} {nome} {servidor}').setMaxLength(500))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    const h = hoje();\n\n    if (sub === 'definir') {\n      const dia = i.options.getInteger('dia');\n      const mes = i.options.getInteger('mes');\n      if (dia > DIAS_NO_MES[mes - 1]) return responder(i, `${MESES[mes - 1]} não tem dia ${dia}.`, 'erro');\n      datas.de(i.guildId)[i.user.id] = { dia, mes };\n      datas.salvar();\n      return responder(i, `Aniversário salvo: **${dataTexto({ dia, mes })}**. 🎂`, 'sucesso');\n    }\n    if (sub === 'remover') {\n      datas.apagar(i.guildId, i.user.id);\n      return responder(i, 'Seu aniversário foi apagado.', 'sucesso');\n    }\n    if (sub === 'ver') {\n      const u = i.options.getUser('usuario') ?? i.user;\n      const d = datas.ler(i.guildId, u.id);\n      if (!d) return responder(i, u.id === i.user.id ? 'Você ainda não cadastrou. Use `/aniversario definir`.' : `${u} ainda não cadastrou o aniversário.`, 'aviso');\n      const falta = diasAte(d, h);\n      return responder(i, `🎂 ${u}: **${dataTexto(d)}** · ${falta === 0 ? '**é hoje!** 🎉' : `faltam ${falta} dia(s)`}`, 'info');\n    }\n    if (sub === 'proximos') {\n      const todos = Object.entries(datas.ler(i.guildId) ?? {})\n        .map(([id, d]) => ({ id, d, falta: diasAte(d, h) }))\n        .sort((a, b) => a.falta - b.falta)\n        .slice(0, 15);\n      if (!todos.length) return responder(i, 'Ninguém cadastrou o aniversário ainda. Use `/aniversario definir`.', 'aviso');\n      const linhas = todos.map((x) => `${x.falta === 0 ? '🎉' : '🎂'} <@${x.id}> · ${dataTexto(x.d)} · ${x.falta === 0 ? '**hoje!**' : `em ${x.falta} dia(s)`}`);\n      return i.reply({ embeds: [embed(i.guildId).setTitle('🎂 Próximos aniversários').setDescription(linhas.join('\\n'))], allowedMentions: { parse: [] } });\n    }\n\n    // configurar (só equipe)\n    if (!i.member.permissions.has(PermissionFlagsBits.ManageGuild)) return responder(i, 'Só quem tem **Gerenciar servidor** pode configurar.', 'erro');\n    const c = cfg(i.guildId);\n    const canal = i.options.getChannel('canal');\n    const cargo = i.options.getRole('cargo');\n    const msg = i.options.getString('mensagem');\n    if (cargo) {\n      if (cargo.managed || cargo.id === i.guildId || cargo.permissions.has(PermissionFlagsBits.Administrator)) return responder(i, 'Escolha um cargo comum (sem administrador).', 'erro');\n      if (!cargo.editable) return responder(i, `Meu cargo precisa ficar acima de ${cargo}.`, 'erro');\n      c.cargo = cargo.id;\n    }\n    if (canal) c.canal = canal.id;\n    if (msg) c.mensagem = msg;\n    if (!canal && !cargo && !msg) return responder(i, 'Escolha pelo menos uma opção (canal, cargo ou mensagem).', 'aviso');\n    salvarAjustes();\n    return responder(i, `Aniversários: parabéns em ${c.canal ? `<#${c.canal}>` : '— (escolha um canal)'}${c.cargo ? ` · cargo do dia <@&${c.cargo}>` : ''}.`, 'sucesso');\n  },\n};\n\n/** Dá os parabéns de hoje e tira o cargo de quem já passou das 24 h. Roda a cada 10 minutos. */\nasync function verificar(client) {\n  const h = hoje();\n  const chaveHoje = `${h.ano}-${h.mes}-${h.dia}`;\n  for (const guild of client.guilds.cache.values()) {\n    const c = cfg(guild.id);\n    let mudou = false;\n\n    // tira os cargos vencidos\n    for (const [userId, ate] of Object.entries(c.cargosAtivos)) {\n      if (ate > Date.now()) continue;\n      delete c.cargosAtivos[userId];\n      mudou = true;\n      const membro = await guild.members.fetch(userId).catch(() => null);\n      if (membro && c.cargo) await membro.roles.remove(c.cargo, 'Fim do dia de aniversário').catch(() => {});\n    }\n\n    if (c.canal || c.cargo) {\n      const canal = c.canal && guild.channels.cache.get(c.canal);\n      for (const [userId, d] of Object.entries(datas.ler(guild.id) ?? {})) {\n        if (!fazHoje(d, h) || c.anunciados[userId] === chaveHoje) continue;\n        const membro = await guild.members.fetch(userId).catch(() => null);\n        c.anunciados[userId] = chaveHoje;\n        mudou = true;\n        if (!membro) continue; // saiu do servidor\n        if (canal?.isTextBased()) {\n          const texto = preencher(c.mensagem, { usuario: `${membro}`, nome: membro.displayName, servidor: guild.name });\n          await canal\n            .send({ embeds: [embed(guild.id).setDescription(texto).setThumbnail(membro.displayAvatarURL())], content: `${membro}`, allowedMentions: { users: [userId] } })\n            .catch(() => {});\n        }\n        if (c.cargo) {\n          const ok = await membro.roles.add(c.cargo, 'Aniversário').then(() => true, () => false);\n          if (ok) c.cargosAtivos[userId] = Date.now() + 24 * 3600e3;\n        }\n      }\n    }\n    if (mudou) salvarAjustes();\n  }\n}\n\nexport default {\n  id: 'aniversarios',\n  nome: 'Aniversários',\n  comandos: [aniversario],\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  aoIniciar(client) {\n    verificar(client).catch((e) => console.error('[aniversários]', e.message));\n    setInterval(() => verificar(client).catch((e) => console.error('[aniversários]', e.message)), 10 * 60_000);\n  },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      const n = Object.keys(datas.ler(guild.id) ?? {}).length;\n      return [\n        `Parabéns em: ${c.canal ? `<#${c.canal}>` : 'não definido (`/aniversario configurar`)'}`,\n        `Cargo do dia: ${c.cargo ? `<@&${c.cargo}>` : 'nenhum'}`,\n        `${n} aniversário(s) cadastrado(s)`,\n      ];\n    },\n  },\n};\n",
  "src/modules/antiraid.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, GatewayIntentBits, GuildVerificationLevel, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, ehStaff, duracaoTexto, marcarRemovida, CORES } from '../core/util.js';\n\n/**\n * Anti-raid: se entrar gente demais em pouco tempo, o bot ativa o \"modo raid\":\n * sobe o nível de verificação do servidor, pausa os convites (se der) e\n * expulsa ou castiga quem entrar enquanto durar. Avisa a equipe com um botão para encerrar.\n * Também pode barrar contas novas demais o tempo todo.\n */\n\nconst PADRAO = {\n  ativo: false,\n  limite: 10, // entradas...\n  segundos: 30, // ...nesse intervalo\n  acao: 'expulsar', // o que fazer com quem entra durante o raid: expulsar | castigo | nada\n  alerta: null, // canal\n  cargoAlerta: null,\n  idadeMinima: 0, // dias; 0 = não barra contas novas\n  emRaid: false,\n  inicio: null,\n  nivelAntes: null,\n  convitesPausados: false,\n};\nconst cfg = (guildId) => ajustes(guildId, 'antiraid', PADRAO);\nconst entradas = new Map(); // guildId -> [timestamps]\nconst DURACAO_RAID = 30 * 60_000;\n\nasync function alertar(guild, texto, botao = false) {\n  const c = cfg(guild.id);\n  const canal = c.alerta && guild.channels.cache.get(c.alerta);\n  if (!canal?.isTextBased()) return;\n  await canal\n    .send({\n      content: c.cargoAlerta ? `<@&${c.cargoAlerta}>` : undefined,\n      embeds: [embed(guild.id).setColor(CORES.erro).setDescription(texto).setTimestamp()],\n      components: botao ? [new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('ar:fim').setLabel('Encerrar modo raid').setEmoji('✅').setStyle(ButtonStyle.Success))] : [],\n      allowedMentions: { roles: c.cargoAlerta ? [c.cargoAlerta] : [] },\n    })\n    .catch(() => {});\n}\n\nasync function iniciarRaid(guild, quantos) {\n  const c = cfg(guild.id);\n  c.emRaid = true;\n  c.inicio = Date.now();\n  c.nivelAntes = guild.verificationLevel;\n  const feitos = [];\n  if (guild.verificationLevel < GuildVerificationLevel.VeryHigh) {\n    const ok = await guild.setVerificationLevel(GuildVerificationLevel.VeryHigh, 'Anti-raid').then(() => true, () => false);\n    if (ok) feitos.push('nível de verificação no **máximo** (precisa de telefone verificado)');\n  }\n  const pausou = await guild.disableInvites(true).then(() => true, () => false);\n  c.convitesPausados = pausou;\n  if (pausou) feitos.push('**convites pausados**');\n  salvarAjustes();\n  await alertar(\n    guild,\n    `🚨 **Modo raid ativado!** Entraram **${quantos}** pessoas em ${c.segundos}s.\\n${feitos.length ? `Fiz: ${feitos.join(' e ')}.` : 'Não consegui mudar o servidor (preciso de **Gerenciar servidor**).'}\\nQuem entrar agora: **${c.acao === 'nada' ? 'só registro' : c.acao}**. Encerra sozinho em ${duracaoTexto(DURACAO_RAID)} ou pelo botão.`,\n    true\n  );\n}\n\nasync function encerrarRaid(guild, por) {\n  const c = cfg(guild.id);\n  if (!c.emRaid) return false;\n  if (c.nivelAntes != null && guild.verificationLevel !== c.nivelAntes) await guild.setVerificationLevel(c.nivelAntes, 'Fim do modo raid').catch(() => {});\n  if (c.convitesPausados) await guild.disableInvites(false).catch(() => {});\n  Object.assign(c, { emRaid: false, inicio: null, nivelAntes: null, convitesPausados: false });\n  salvarAjustes();\n  await alertar(guild, `✅ Modo raid encerrado${por ? ` por <@${por}>` : ' automaticamente'}. O servidor voltou ao normal.`);\n  return true;\n}\n\n/** Avisa os outros módulos (ex.: Boas-vindas) que esta pessoa foi barrada. */\nconst barrar = (member) => marcarRemovida(`membro:${member.guild.id}:${member.id}`);\n\nasync function punir(member, motivo) {\n  barrar(member);\n  const c = cfg(member.guild.id);\n  await member.send(`Você não pôde entrar em **${member.guild.name}** agora (${motivo}). Tente de novo mais tarde.`).catch(() => {});\n  if (c.acao === 'castigo' && member.moderatable) return member.timeout(60 * 60_000, `Anti-raid: ${motivo}`).catch(() => {});\n  if (member.kickable) return member.kick(`Anti-raid: ${motivo}`).catch(() => {});\n}\n\nasync function aoEntrar(member) {\n  const guild = member.guild;\n  const c = cfg(guild.id);\n  if (!c.ativo || member.user.bot) return;\n\n  // contas novas demais\n  const dias = (Date.now() - member.user.createdTimestamp) / 86400e3;\n  if (c.idadeMinima && dias < c.idadeMinima) {\n    if (member.kickable) {\n      barrar(member);\n      await member.send(`Sua conta é nova demais para entrar em **${guild.name}** (mínimo: ${c.idadeMinima} dia(s)).`).catch(() => {});\n      await member.kick(`Anti-raid: conta com ${Math.floor(dias)} dia(s)`).catch(() => {});\n      await alertar(guild, `👶 Expulsei ${member.user.tag} (\\`${member.id}\\`): conta com ${Math.floor(dias)} dia(s).`);\n    }\n    return;\n  }\n\n  // modo raid ligado: aplica a ação em quem entra\n  if (c.emRaid) {\n    if (Date.now() - c.inicio > DURACAO_RAID) await encerrarRaid(guild, null);\n    else if (c.acao !== 'nada') return punir(member, 'modo raid');\n  }\n\n  // conta as entradas recentes\n  const agora = Date.now();\n  const lista = (entradas.get(guild.id) ?? []).filter((t) => agora - t < c.segundos * 1000);\n  lista.push(agora);\n  entradas.set(guild.id, lista);\n  if (!c.emRaid && lista.length >= c.limite) {\n    entradas.set(guild.id, []);\n    await iniciarRaid(guild, lista.length);\n    if (c.acao !== 'nada') await punir(member, 'modo raid'); // quem disparou também faz parte do raid\n  }\n}\n\nconst componentes = {\n  async ar(i, [acao]) {\n    if (acao !== 'fim') return;\n    if (!ehStaff(i.member)) return responder(i, 'Só a equipe pode encerrar o modo raid.', 'erro');\n    const ok = await encerrarRaid(i.guild, i.user.id);\n    await i.message.edit({ components: [] }).catch(() => {});\n    return responder(i, ok ? 'Modo raid encerrado.' : 'O modo raid já tinha acabado.', ok ? 'sucesso' : 'aviso');\n  },\n};\n\nconst antiraid = {\n  data: new SlashCommandBuilder()\n    .setName('antiraid')\n    .setDescription('Proteção contra raids (muita gente entrando de uma vez)')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('configurar')\n        .setDescription('Liga e ajusta o anti-raid')\n        .addChannelOption((o) => o.setName('alerta').setDescription('Canal onde a equipe é avisada').setRequired(true).addChannelTypes(ChannelType.GuildText))\n        .addIntegerOption((o) => o.setName('limite').setDescription('Quantas entradas disparam o modo raid (padrão 10)').setMinValue(3).setMaxValue(100))\n        .addIntegerOption((o) => o.setName('segundos').setDescription('Em quantos segundos (padrão 30)').setMinValue(5).setMaxValue(600))\n        .addStringOption((o) =>\n          o\n            .setName('acao')\n            .setDescription('O que fazer com quem entra durante o raid (padrão: expulsar)')\n            .addChoices({ name: 'Expulsar', value: 'expulsar' }, { name: 'Castigo de 1 hora', value: 'castigo' }, { name: 'Nada (só travar o servidor)', value: 'nada' })\n        )\n        .addRoleOption((o) => o.setName('cargo-alerta').setDescription('Cargo marcado no aviso (opcional)'))\n        .addIntegerOption((o) => o.setName('idade-minima').setDescription('Expulsa contas com menos dias que isso, sempre (0 = não)').setMinValue(0).setMaxValue(60))\n    )\n    .addSubcommand((s) => s.setName('desligar').setDescription('Desliga o anti-raid'))\n    .addSubcommand((s) => s.setName('encerrar').setDescription('Encerra o modo raid agora'))\n    .addSubcommand((s) => s.setName('ativar-raid').setDescription('Liga o modo raid manualmente (trava o servidor)')),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const sub = i.options.getSubcommand();\n    if (sub === 'desligar') {\n      if (c.emRaid) await encerrarRaid(i.guild, i.user.id);\n      c.ativo = false;\n      salvarAjustes();\n      return responder(i, 'Anti-raid desligado.', 'sucesso');\n    }\n    if (sub === 'encerrar') return responder(i, (await encerrarRaid(i.guild, i.user.id)) ? 'Modo raid encerrado.' : 'O servidor não está em modo raid.', 'sucesso');\n    if (sub === 'ativar-raid') {\n      if (!c.ativo) return responder(i, 'Configure primeiro com `/antiraid configurar`.', 'erro');\n      if (c.emRaid) return responder(i, 'O modo raid já está ligado.', 'aviso');\n      await i.deferReply({ flags: 64 });\n      await iniciarRaid(i.guild, 0);\n      return i.editReply('🚨 Modo raid ligado. Encerre com `/antiraid encerrar` ou pelo botão no canal de alerta.');\n    }\n    c.ativo = true;\n    c.alerta = i.options.getChannel('alerta').id;\n    for (const [opcao, campo] of [['limite', 'limite'], ['segundos', 'segundos'], ['idade-minima', 'idadeMinima']]) {\n      const v = i.options.getInteger(opcao);\n      if (v !== null) c[campo] = v;\n    }\n    const acao = i.options.getString('acao');\n    if (acao) c.acao = acao;\n    const cargo = i.options.getRole('cargo-alerta');\n    if (cargo) c.cargoAlerta = cargo.id;\n    salvarAjustes();\n    const me = i.guild.members.me.permissions;\n    const faltam = [\n      [PermissionFlagsBits.ManageGuild, 'Gerenciar servidor'],\n      [PermissionFlagsBits.KickMembers, 'Expulsar membros'],\n      [PermissionFlagsBits.ModerateMembers, 'Castigar membros'],\n    ]\n      .filter(([p]) => !me.has(p))\n      .map(([, n]) => n);\n    return responder(\n      i,\n      `Anti-raid ligado: **${c.limite}** entradas em **${c.segundos}s** ativam o modo raid (ação: ${c.acao}). Avisos em <#${c.alerta}>.${c.idadeMinima ? ` Contas com menos de ${c.idadeMinima} dia(s) são expulsas.` : ''}${faltam.length ? `\\n⚠️ Me falta: ${faltam.join(', ')}.` : ''}`,\n      faltam.length ? 'aviso' : 'sucesso'\n    );\n  },\n};\n\nexport default {\n  id: 'antiraid',\n  nome: 'Anti-raid',\n  prioridade: 1, // antes das boas-vindas: quem é expulso nem recebe a mensagem\n  intents: [GatewayIntentBits.GuildMembers],\n  permissoes: [PermissionFlagsBits.ManageGuild, PermissionFlagsBits.KickMembers, PermissionFlagsBits.ModerateMembers],\n  comandos: [antiraid],\n  componentes,\n  eventos: { guildMemberAdd: aoEntrar },\n  aoIniciar(client) {\n    // encerra modos raid esquecidos (ex.: bot ficou desligado)\n    setInterval(() => {\n      for (const guild of client.guilds.cache.values()) {\n        const c = cfg(guild.id);\n        if (c.emRaid && Date.now() - c.inicio > DURACAO_RAID) encerrarRaid(guild, null).catch(() => {});\n      }\n    }, 60_000);\n  },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      if (!c.ativo) return ['Desligado (`/antiraid configurar`)'];\n      return [`${c.limite} entradas em ${c.segundos}s · ação: ${c.acao} · alerta em <#${c.alerta}>${c.emRaid ? ' · 🚨 **EM MODO RAID**' : ''}`];\n    },\n  },\n};\n",
  "src/modules/anuncios.js": "import { ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { CONFIG, embed, responder, cortar, lerDuracao, duracaoTexto, ts } from '../core/util.js';\n\n/**\n * Anúncios agendados: mensagens que saem numa data marcada ou que repetem\n * de tempos em tempos (ex.: lembrar as regras toda segunda às 9h).\n */\n\nconst anuncios = colecao('anuncios'); // guild -> { lista: [...] }\nconst LIMITE = 20;\nconst MIN_INTERVALO = 10 * 60_000;\nconst FUSO = CONFIG.fuso || 'America/Sao_Paulo';\nconst lista = (guildId) => (anuncios.de(guildId).lista ??= []);\n\n/** Diferença (ms) entre o fuso escolhido e o UTC num instante. */\nfunction offsetFuso(data) {\n  const p = Object.fromEntries(\n    new Intl.DateTimeFormat('en-US', { timeZone: FUSO, hourCycle: 'h23', year: 'numeric', month: 'numeric', day: 'numeric', hour: 'numeric', minute: 'numeric', second: 'numeric' })\n      .formatToParts(data)\n      .map((x) => [x.type, x.value])\n  );\n  return Date.UTC(p.year, p.month - 1, p.day, p.hour, p.minute, p.second) - data.getTime();\n}\n\n/**\n * \"25/12 09:00\", \"25/12/2026 9h\", \"09:30\" ou \"9h\" (hoje, ou amanhã se já passou)\n * e \"em 2h\" / \"em 30min\" / \"em 1d\" (daqui a). null se não entender.\n */\nexport function lerQuando(texto) {\n  if (!texto) return Date.now();\n  const t = texto.trim().toLowerCase();\n  if (t.startsWith('em ')) {\n    const rel = lerDuracao(t.slice(3).trim());\n    return rel ? Date.now() + rel : null;\n  }\n  const m = /^(?:(\\d{1,2})\\/(\\d{1,2})(?:\\/(\\d{2,4}))?\\s*)?(?:às\\s*|as\\s*)?(\\d{1,2})(?:[:h](\\d{2})?)?h?$/.exec(t);\n  if (!m) return null;\n  const agora = new Date();\n  const local = new Date(agora.getTime() + offsetFuso(agora)); // \"relógio\" do fuso, em UTC\n  let [dia, mes, ano] = [m[1] ? Number(m[1]) : local.getUTCDate(), m[2] ? Number(m[2]) : local.getUTCMonth() + 1, m[3] ? Number(m[3]) : local.getUTCFullYear()];\n  if (ano < 100) ano += 2000;\n  const hora = Number(m[4]);\n  const minuto = Number(m[5] ?? 0);\n  if (mes < 1 || mes > 12 || dia < 1 || dia > 31 || hora > 23 || minuto > 59) return null;\n  let quando = Date.UTC(ano, mes - 1, dia, hora, minuto);\n  if (new Date(quando).getUTCDate() !== dia) return null; // ex.: 31/02\n  quando -= offsetFuso(new Date(quando));\n  if (!m[1] && quando < Date.now()) quando += 86400e3; // só a hora e já passou: amanhã\n  if (m[1] && quando < Date.now() - 60_000) {\n    // data sem ano que passou faz tempo (ex.: 1/1): é a do ano que vem\n    if (!m[3] && quando < Date.now() - 86400e3) {\n      quando = Date.UTC(ano + 1, mes - 1, dia, hora, minuto);\n      return quando - offsetFuso(new Date(quando));\n    }\n    return -1; // passou há pouco (provável engano)\n  }\n  return quando;\n}\n\nfunction mensagem(guildId, a) {\n  const e = embed(guildId).setDescription(a.texto);\n  if (a.titulo) e.setTitle(a.titulo);\n  if (a.imagem) e.setImage(a.imagem);\n  return { content: a.cargo ? (a.cargo === guildId ? '@everyone' : `<@&${a.cargo}>`) : undefined, embeds: [e], allowedMentions: { parse: a.cargo === guildId ? ['everyone'] : [], roles: a.cargo && a.cargo !== guildId ? [a.cargo] : [] } };\n}\n\nasync function enviar(client, guildId, a) {\n  const canal = await client.channels.fetch(a.canal).catch(() => null);\n  if (!canal?.isTextBased()) return false;\n  return canal.send(mensagem(guildId, a)).then(() => true, () => false);\n}\n\nasync function verificar(client) {\n  const agora = Date.now();\n  for (const [guildId, g] of Object.entries(anuncios.raiz)) {\n    if (!client.guilds.cache.has(guildId) || !g.lista?.length) continue;\n    let mudou = false;\n    for (const a of [...g.lista]) {\n      if (a.proximo > agora) continue;\n      await enviar(client, guildId, a);\n      mudou = true;\n      if (a.intervalo) {\n        // pula os horários perdidos enquanto o bot estava desligado\n        while (a.proximo <= agora) a.proximo += a.intervalo;\n      } else g.lista = g.lista.filter((x) => x.id !== a.id);\n    }\n    if (mudou) anuncios.salvar();\n  }\n}\n\nconst anuncio = {\n  data: new SlashCommandBuilder()\n    .setName('anuncio')\n    .setDescription('Anúncios agendados e repetidos')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('criar')\n        .setDescription('Agenda um anúncio')\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde enviar').setRequired(true).addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n        .addStringOption((o) => o.setName('mensagem').setDescription('Texto do anúncio (use \\\\n para pular linha)').setRequired(true).setMaxLength(1900))\n        .addStringOption((o) => o.setName('quando').setDescription('Ex.: \"25/12 09:00\", \"18:30\", \"9h\" ou \"em 2h\". Vazio = agora'))\n        .addStringOption((o) => o.setName('repetir').setDescription('Repetir a cada... ex.: \"1d\", \"12h\", \"7d\" (vazio = uma vez só)'))\n        .addStringOption((o) => o.setName('titulo').setDescription('Título (opcional)').setMaxLength(200))\n        .addRoleOption((o) => o.setName('mencionar').setDescription('Cargo para marcar (opcional)'))\n        .addStringOption((o) => o.setName('imagem').setDescription('Link de uma imagem (opcional)'))\n    )\n    .addSubcommand((s) => s.setName('lista').setDescription('Mostra os anúncios agendados'))\n    .addSubcommand((s) =>\n      s\n        .setName('apagar')\n        .setDescription('Cancela um anúncio')\n        .addStringOption((o) => o.setName('anuncio').setDescription('Qual').setRequired(true).setAutocomplete(true))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('testar')\n        .setDescription('Envia um anúncio agora (sem mudar o agendamento)')\n        .addStringOption((o) => o.setName('anuncio').setDescription('Qual').setRequired(true).setAutocomplete(true))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    const l = lista(i.guildId);\n    if (sub === 'lista') {\n      if (!l.length) return responder(i, 'Nenhum anúncio agendado. Use `/anuncio criar`.', 'aviso');\n      const linhas = l.map((a) => `\\`${a.id}\\` · <#${a.canal}> · ${ts(a.proximo, 'f')}${a.intervalo ? ` · a cada ${duracaoTexto(a.intervalo)}` : ''}\\n> ${cortar(a.titulo || a.texto.replace(/\\n/g, ' '), 80)}`);\n      return i.reply({ embeds: [embed(i.guildId).setTitle('📣 Anúncios agendados').setDescription(cortar(linhas.join('\\n'), 4000))], flags: 64 });\n    }\n    if (sub === 'apagar' || sub === 'testar') {\n      const a = l.find((x) => x.id === i.options.getString('anuncio'));\n      if (!a) return responder(i, 'Anúncio não encontrado. Escolha na lista enquanto digita.', 'erro');\n      if (sub === 'testar') return responder(i, (await enviar(i.client, i.guildId, a)) ? `Enviado em <#${a.canal}>.` : 'Não consegui enviar. Confira as minhas permissões no canal.', 'sucesso');\n      anuncios.de(i.guildId).lista = l.filter((x) => x.id !== a.id);\n      anuncios.salvar();\n      return responder(i, 'Anúncio cancelado.', 'sucesso');\n    }\n    // criar\n    if (l.length >= LIMITE) return responder(i, `No máximo ${LIMITE} anúncios agendados.`, 'erro');\n    const quando = lerQuando(i.options.getString('quando'));\n    if (quando === -1) return responder(i, 'Essa data já passou. Confira o dia e o horário.', 'erro');\n    if (!quando) return responder(i, 'Não entendi a data. Use algo como **25/12 09:00**, **18:30**, **9h** ou **em 2h**.', 'erro');\n    const repetir = i.options.getString('repetir');\n    const intervalo = repetir ? lerDuracao(repetir) : null;\n    if (repetir && !intervalo) return responder(i, 'Não entendi o \"repetir\". Use algo como **12h**, **1d** ou **7d**.', 'erro');\n    if (intervalo && intervalo < MIN_INTERVALO) return responder(i, 'Para não virar spam, o intervalo mínimo é de 10 minutos.', 'erro');\n    const imagem = i.options.getString('imagem');\n    if (imagem && !/^https?:\\/\\/\\S+$/i.test(imagem)) return responder(i, 'O link da imagem precisa começar com https://', 'erro');\n    const a = {\n      id: Date.now().toString(36).slice(-6),\n      canal: i.options.getChannel('canal').id,\n      texto: i.options.getString('mensagem').replace(/\\\\n/g, '\\n'),\n      titulo: i.options.getString('titulo') ?? null,\n      cargo: i.options.getRole('mencionar')?.id ?? null,\n      imagem: imagem ?? null,\n      proximo: Math.max(quando, Date.now() + 5000),\n      intervalo,\n    };\n    l.push(a);\n    anuncios.salvar();\n    return responder(i, `Anúncio agendado para ${ts(a.proximo, 'f')} (${ts(a.proximo)})${intervalo ? ` e depois a cada **${duracaoTexto(intervalo)}**` : ''} em <#${a.canal}>.`, 'sucesso');\n  },\n  async autocompletar(i) {\n    const foco = (i.options.getFocused() || '').toLowerCase();\n    await i.respond(\n      (anuncios.ler(i.guildId, 'lista') ?? [])\n        .filter((a) => `${a.id} ${a.titulo ?? ''} ${a.texto}`.toLowerCase().includes(foco))\n        .slice(0, 25)\n        .map((a) => ({ name: cortar(`${a.id} · ${a.titulo || a.texto.replace(/\\n/g, ' ')}`, 100), value: a.id }))\n    );\n  },\n};\n\nexport default {\n  id: 'anuncios',\n  nome: 'Anúncios agendados',\n  permissoes: [PermissionFlagsBits.MentionEveryone],\n  comandos: [anuncio],\n  aoIniciar(client) {\n    verificar(client).catch((e) => console.error('[anúncios]', e.message));\n    setInterval(() => verificar(client).catch((e) => console.error('[anúncios]', e.message)), 30_000);\n  },\n  config: {\n    resumo(guild) {\n      const n = anuncios.ler(guild.id, 'lista')?.length ?? 0;\n      return [n ? `${n} anúncio(s) agendado(s) (\\`/anuncio lista\\`)` : 'Nenhum (`/anuncio criar`)'];\n    },\n  },\n};\n",
  "src/modules/automod.js": "import { ChannelType, GatewayIntentBits, PermissionFlagsBits } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, lerDuracao, duracaoTexto, cortar, marcarRemovida, CORES } from '../core/util.js';\n\n/**\n * AutoMod: apaga sozinho links, convites, palavras proibidas, flood, CAPS e menções em massa.\n * Quem tem \"Gerenciar mensagens\", os cargos imunes e os canais ignorados ficam de fora.\n */\n\nconst PADRAO = {\n  ativo: false,\n  links: false,\n  dominiosPermitidos: [],\n  convites: true,\n  palavras: [],\n  spam: 0, // mensagens em 5 s (0 = desligado)\n  maiusculas: false,\n  mencoes: 0, // menções numa mensagem (0 = desligado)\n  acao: 'apagar', // apagar | castigo\n  duracao: 300_000,\n  imunes: [],\n  ignorados: [],\n  canalLog: null,\n};\nconst cfg = (guildId) => ajustes(guildId, 'automod', PADRAO);\n\nconst RE_LINK = /\\bhttps?:\\/\\/([^\\s/$.?#]+\\.[^\\s/?#]+)[^\\s]*/gi;\nconst RE_CONVITE = /(discord\\.gg|discord(?:app)?\\.com\\/invite|dsc\\.gg)\\/[\\w-]+/i;\n\n// controle de flood: guildId:userId -> horários das últimas mensagens\nconst recentes = new Map();\nsetInterval(() => {\n  const limite = Date.now() - 10_000;\n  for (const [k, lista] of recentes) if (!lista.length || lista.at(-1) < limite) recentes.delete(k);\n}, 60_000).unref();\n\nconst normalizar = (s) => s.toLowerCase().normalize('NFD').replace(/[̀-ͯ]/g, '');\n\nfunction verificar(msg, c) {\n  const texto = msg.content || '';\n  if (c.convites && RE_CONVITE.test(texto)) return 'Convite de outro servidor';\n  if (c.links) {\n    for (const m of texto.matchAll(RE_LINK)) {\n      const dominio = m[1].toLowerCase().replace(/^www\\./, '');\n      const liberado = c.dominiosPermitidos.some((d) => dominio === d || dominio.endsWith(`.${d}`));\n      if (!liberado) return 'Link não permitido';\n    }\n  }\n  if (c.palavras.length) {\n    const t = normalizar(texto);\n    const achou = c.palavras.find((p) => new RegExp(`(^|[^\\\\p{L}\\\\p{N}])${normalizar(p).replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&')}($|[^\\\\p{L}\\\\p{N}])`, 'u').test(t));\n    if (achou) return 'Palavra proibida';\n  }\n  if (c.mencoes > 0) {\n    const n = msg.mentions.users.size + msg.mentions.roles.size;\n    if (n >= c.mencoes) return `Menções em massa (${n})`;\n  }\n  if (c.maiusculas) {\n    const letras = texto.replace(/[^a-zA-ZÀ-ÿ]/g, '');\n    if (letras.length >= 12 && letras.replace(/[^A-ZÀ-Þ]/g, '').length / letras.length > 0.7) return 'Excesso de letras maiúsculas';\n  }\n  if (c.spam > 0) {\n    const k = `${msg.guildId}:${msg.author.id}`;\n    const agora = Date.now();\n    const lista = (recentes.get(k) ?? []).filter((t) => agora - t < 5000);\n    lista.push(agora);\n    recentes.set(k, lista);\n    if (lista.length > c.spam) return 'Flood (mensagens rápidas demais)';\n  }\n  return null;\n}\n\nasync function registrar(msg, motivo, c) {\n  if (!c.canalLog) return;\n  const canal = msg.guild.channels.cache.get(c.canalLog);\n  if (!canal?.isTextBased()) return;\n  await canal\n    .send({\n      embeds: [\n        embed(msg.guildId)\n          .setColor(CORES.aviso)\n          .setTitle('🛡️ AutoMod')\n          .addFields(\n            { name: 'Membro', value: `${msg.author} (${msg.author.tag})`, inline: true },\n            { name: 'Canal', value: `${msg.channel}`, inline: true },\n            { name: 'Motivo', value: motivo },\n            { name: 'Mensagem', value: cortar(msg.content || '(sem texto)', 1000) },\n          )\n          .setTimestamp(),\n      ],\n    })\n    .catch(() => {});\n}\n\nasync function aoMensagem(msg) {\n  if (!msg.inGuild() || msg.author.bot || !msg.member) return;\n  const c = cfg(msg.guildId);\n  if (!c.ativo) return;\n  if (msg.member.permissions.has(PermissionFlagsBits.ManageMessages)) return;\n  if (c.ignorados.includes(msg.channelId) || c.ignorados.includes(msg.channel.parentId)) return;\n  if (c.imunes.some((r) => msg.member.roles.cache.has(r))) return;\n\n  const motivo = verificar(msg, c);\n  if (!motivo) return;\n\n  marcarRemovida(msg.id); // os outros módulos ignoram esta mensagem\n  const apagou = await msg.delete().then(() => true, () => false);\n  if (!apagou) {\n    // sem a permissão \"Gerenciar mensagens\" neste canal: só registra\n    return registrar(msg, `${motivo} (não consegui apagar: me dê a permissão Gerenciar mensagens)`, c);\n  }\n  let texto = `${msg.author}, sua mensagem foi apagada: **${motivo}**.`;\n  if (c.acao === 'castigo' && msg.member.moderatable) {\n    const ok = await msg.member.timeout(c.duracao, `AutoMod: ${motivo}`).then(() => true, () => false);\n    if (ok) texto += ` Castigo de ${duracaoTexto(c.duracao)}.`;\n  }\n  const aviso = await msg.channel.send({ content: texto, allowedMentions: { users: [msg.author.id] } }).catch(() => null);\n  if (aviso) setTimeout(() => aviso.delete().catch(() => {}), 8000);\n  await registrar(msg, motivo, c);\n}\n\n// ---------------- /config automod ----------------\nconst config = {\n  grupo: 'automod',\n  montar: (g) =>\n    g\n      .setDescription('AutoMod: filtros automáticos de mensagens')\n      .addSubcommand((s) => s.setName('ativar').setDescription('Liga ou desliga o AutoMod').addBooleanOption((o) => o.setName('ligado').setDescription('Ligado?').setRequired(true)))\n      .addSubcommand((s) => s.setName('links').setDescription('Bloquear links').addBooleanOption((o) => o.setName('bloquear').setDescription('Bloquear?').setRequired(true)))\n      .addSubcommand((s) =>\n        s.setName('permitir-site').setDescription('Libera (ou bloqueia de novo) links de um site').addStringOption((o) => o.setName('site').setDescription('Ex.: youtube.com').setRequired(true).setMaxLength(100))\n      )\n      .addSubcommand((s) => s.setName('convites').setDescription('Bloquear convites de outros servidores').addBooleanOption((o) => o.setName('bloquear').setDescription('Bloquear?').setRequired(true)))\n      .addSubcommand((s) =>\n        s.setName('palavra').setDescription('Adiciona ou remove uma palavra proibida').addStringOption((o) => o.setName('palavra').setDescription('A palavra').setRequired(true).setMaxLength(60))\n      )\n      .addSubcommand((s) =>\n        s.setName('flood').setDescription('Mensagens permitidas em 5 segundos').addIntegerOption((o) => o.setName('limite').setDescription('0 desliga').setRequired(true).setMinValue(0).setMaxValue(20))\n      )\n      .addSubcommand((s) => s.setName('maiusculas').setDescription('Apagar mensagens quase todas em CAPS').addBooleanOption((o) => o.setName('ligado').setDescription('Ligado?').setRequired(true)))\n      .addSubcommand((s) =>\n        s.setName('mencoes').setDescription('Máximo de menções numa mensagem').addIntegerOption((o) => o.setName('limite').setDescription('0 desliga').setRequired(true).setMinValue(0).setMaxValue(50))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('punicao')\n          .setDescription('O que fazer além de apagar')\n          .addStringOption((o) =>\n            o.setName('acao').setDescription('Ação').setRequired(true).addChoices({ name: 'Só apagar', value: 'apagar' }, { name: 'Apagar e dar castigo', value: 'castigo' })\n          )\n          .addStringOption((o) => o.setName('duracao').setDescription('Duração do castigo, ex.: 5m').setMaxLength(20))\n      )\n      .addSubcommand((s) => s.setName('imune').setDescription('Cargo que o AutoMod ignora (usar de novo remove)').addRoleOption((o) => o.setName('cargo').setDescription('Cargo').setRequired(true)))\n      .addSubcommand((s) =>\n        s\n          .setName('ignorar-canal')\n          .setDescription('Canal ou categoria que o AutoMod ignora (usar de novo remove)')\n          .addChannelOption((o) => o.setName('canal').setDescription('Canal').setRequired(true).addChannelTypes(ChannelType.GuildText, ChannelType.GuildCategory, ChannelType.GuildAnnouncement))\n      )\n      .addSubcommand((s) =>\n        s.setName('registro').setDescription('Canal onde o AutoMod registra o que apagou').addChannelOption((o) => o.setName('canal').setDescription('Vazio desliga').addChannelTypes(ChannelType.GuildText))\n      ),\n  async executar(i, sub) {\n    const c = cfg(i.guildId);\n    const alternar = (lista, valor) => {\n      const idx = lista.indexOf(valor);\n      if (idx >= 0) lista.splice(idx, 1);\n      else lista.push(valor);\n      return idx < 0;\n    };\n    let msg;\n    switch (sub) {\n      case 'ativar':\n        c.ativo = i.options.getBoolean('ligado');\n        msg = c.ativo ? 'AutoMod **ligado**. Ajuste os filtros com os outros /config automod.' : 'AutoMod **desligado**.';\n        break;\n      case 'links':\n        c.links = i.options.getBoolean('bloquear');\n        msg = c.links ? 'Links bloqueados (exceto os sites liberados).' : 'Links liberados.';\n        break;\n      case 'permitir-site': {\n        const site = i.options.getString('site').toLowerCase().replace(/^https?:\\/\\//, '').replace(/^www\\./, '').split('/')[0];\n        msg = alternar(c.dominiosPermitidos, site) ? `Links de **${site}** liberados.` : `Links de **${site}** bloqueados de novo.`;\n        break;\n      }\n      case 'convites':\n        c.convites = i.options.getBoolean('bloquear');\n        msg = c.convites ? 'Convites de outros servidores bloqueados.' : 'Convites liberados.';\n        break;\n      case 'palavra': {\n        const p = i.options.getString('palavra').trim().toLowerCase();\n        msg = alternar(c.palavras, p) ? `Palavra adicionada (${c.palavras.length} no total).` : `Palavra removida (${c.palavras.length} no total).`;\n        break;\n      }\n      case 'flood':\n        c.spam = i.options.getInteger('limite');\n        msg = c.spam ? `Flood: no máximo **${c.spam}** mensagens a cada 5 segundos.` : 'Filtro de flood desligado.';\n        break;\n      case 'maiusculas':\n        c.maiusculas = i.options.getBoolean('ligado');\n        msg = c.maiusculas ? 'Mensagens em CAPS serão apagadas.' : 'Filtro de CAPS desligado.';\n        break;\n      case 'mencoes':\n        c.mencoes = i.options.getInteger('limite');\n        msg = c.mencoes ? `Mensagens com **${c.mencoes}** ou mais menções serão apagadas.` : 'Filtro de menções desligado.';\n        break;\n      case 'punicao': {\n        c.acao = i.options.getString('acao');\n        const d = i.options.getString('duracao');\n        if (d) {\n          const ms = lerDuracao(d);\n          if (!ms || ms > 28 * 86_400_000) return responder(i, 'Duração inválida (ex.: 5m, 1h).', 'erro');\n          c.duracao = ms;\n        }\n        msg = c.acao === 'castigo' ? `Além de apagar, castigo de **${duracaoTexto(c.duracao)}**.` : 'O AutoMod só vai apagar as mensagens.';\n        break;\n      }\n      case 'imune': {\n        const r = i.options.getRole('cargo');\n        msg = alternar(c.imunes, r.id) ? `${r} agora é imune ao AutoMod.` : `${r} não é mais imune.`;\n        break;\n      }\n      case 'ignorar-canal': {\n        const ch = i.options.getChannel('canal');\n        msg = alternar(c.ignorados, ch.id) ? `O AutoMod vai ignorar ${ch}.` : `O AutoMod volta a vigiar ${ch}.`;\n        break;\n      }\n      case 'registro': {\n        const ch = i.options.getChannel('canal');\n        c.canalLog = ch?.id ?? null;\n        msg = ch ? `O AutoMod vai registrar em ${ch}.` : 'Registro do AutoMod desligado.';\n        break;\n      }\n    }\n    salvarAjustes();\n    return responder(i, msg, 'sucesso');\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    if (!c.ativo) return ['Desligado (use /config automod ativar)'];\n    const f = [];\n    if (c.convites) f.push('convites');\n    if (c.links) f.push(`links${c.dominiosPermitidos.length ? ` (liberados: ${c.dominiosPermitidos.join(', ')})` : ''}`);\n    if (c.palavras.length) f.push(`${c.palavras.length} palavra(s)`);\n    if (c.spam) f.push(`flood > ${c.spam}/5s`);\n    if (c.maiusculas) f.push('CAPS');\n    if (c.mencoes) f.push(`${c.mencoes}+ menções`);\n    return [\n      `Filtros: ${f.length ? f.join(', ') : 'nenhum'}`,\n      `Punição: ${c.acao === 'castigo' ? `apagar + castigo de ${duracaoTexto(c.duracao)}` : 'apagar'}`,\n      `Registro: ${c.canalLog ? `<#${c.canalLog}>` : 'desligado'}`,\n    ];\n  },\n};\n\nexport default {\n  id: 'automod',\n  nome: 'AutoMod',\n  prioridade: 0, // roda antes dos outros módulos nas mensagens novas\n  intents: [GatewayIntentBits.GuildMessages, GatewayIntentBits.MessageContent],\n  permissoes: [PermissionFlagsBits.ManageMessages, PermissionFlagsBits.ModerateMembers],\n  eventos: { messageCreate: aoMensagem },\n  config,\n};\n",
  "src/modules/autorespostas.js": "import { GatewayIntentBits, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { embed, responder, preencher, cortar, foiRemovida } from '../core/util.js';\n\n/**\n * Respostas automáticas: quando alguém escreve um gatilho, o bot responde.\n * Também viram atalhos: /tag nome:regras mostra a resposta salva.\n * Variáveis na resposta: {usuario} {nome} {servidor} {canal}\n */\n\nconst respostas = colecao('autorespostas');\nconst LIMITE = 50;\nconst MODOS = { contem: 'contém a palavra', igual: 'é exatamente', comeca: 'começa com' };\nconst recentes = new Map(); // anti-spam: \"canal:gatilho\" -> quando respondeu\n\nconst normalizar = (t) =>\n  String(t ?? '')\n    .normalize('NFD')\n    .replace(/[̀-ͯ]/g, '')\n    .toLowerCase()\n    .trim();\nconst escapar = (t) => t.replace(/[.*+?^${}()|[\\]\\\\]/g, '\\\\$&');\nconst lista = (guildId) => respostas.de(guildId, 'itens').lista ?? (respostas.de(guildId, 'itens').lista = []);\n\nfunction bate(item, texto) {\n  const g = normalizar(item.gatilho);\n  if (item.modo === 'igual') return texto === g;\n  if (item.modo === 'comeca') return texto.startsWith(g);\n  return new RegExp(`(^|[^\\\\p{L}\\\\p{N}])${escapar(g)}($|[^\\\\p{L}\\\\p{N}])`, 'u').test(texto);\n}\n\nconst vars = (guild, user, canal) => ({ usuario: `${user}`, nome: user.displayName ?? user.username, servidor: guild.name, canal: `${canal}` });\n\nasync function aoMensagem(msg) {\n  if (!msg.inGuild() || msg.author.bot || !msg.content) return;\n  if (foiRemovida(msg.id)) return; // apagada pelo AutoMod\n  const itens = respostas.ler(msg.guildId, 'itens')?.lista;\n  if (!itens?.length) return;\n  const texto = normalizar(msg.content);\n  const item = itens.find((it) => bate(it, texto));\n  if (!item) return;\n  const k = `${msg.channelId}:${item.gatilho}`;\n  if (Date.now() - (recentes.get(k) ?? 0) < 10_000) return; // no máximo uma vez a cada 10 s por canal\n  recentes.set(k, Date.now());\n  await msg.reply({ content: preencher(item.resposta, vars(msg.guild, msg.author, msg.channel)), allowedMentions: { users: [msg.author.id], repliedUser: false } }).catch(() => {});\n}\n\nconst autoresposta = {\n  data: new SlashCommandBuilder()\n    .setName('autoresposta')\n    .setDescription('Gerencia as respostas automáticas')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('adicionar')\n        .setDescription('Cria (ou troca) uma resposta automática')\n        .addStringOption((o) => o.setName('gatilho').setDescription('Palavra ou frase que dispara a resposta').setRequired(true).setMaxLength(60))\n        .addStringOption((o) => o.setName('resposta').setDescription('O que o bot responde. Variáveis: {usuario} {nome} {servidor} {canal}').setRequired(true).setMaxLength(1800))\n        .addStringOption((o) =>\n          o\n            .setName('modo')\n            .setDescription('Quando responder (padrão: quando a mensagem contém a palavra)')\n            .addChoices({ name: 'contém a palavra', value: 'contem' }, { name: 'é exatamente', value: 'igual' }, { name: 'começa com', value: 'comeca' })\n        )\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('remover')\n        .setDescription('Apaga uma resposta automática')\n        .addStringOption((o) => o.setName('gatilho').setDescription('Qual apagar').setRequired(true).setAutocomplete(true))\n    )\n    .addSubcommand((s) => s.setName('lista').setDescription('Mostra todas as respostas automáticas')),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    const itens = lista(i.guildId);\n    if (sub === 'adicionar') {\n      const gatilho = i.options.getString('gatilho').trim();\n      if (normalizar(gatilho).length < 2) return responder(i, 'O gatilho precisa ter pelo menos 2 letras.', 'erro');\n      const existente = itens.find((x) => normalizar(x.gatilho) === normalizar(gatilho));\n      if (!existente && itens.length >= LIMITE) return responder(i, `Limite de ${LIMITE} respostas automáticas. Apague alguma antes.`, 'erro');\n      const item = { gatilho, resposta: i.options.getString('resposta'), modo: i.options.getString('modo') ?? 'contem' };\n      if (existente) Object.assign(existente, item);\n      else itens.push(item);\n      respostas.salvar();\n      return responder(i, `${existente ? 'Atualizada' : 'Criada'}: quando a mensagem **${MODOS[item.modo]}** \\`${gatilho}\\`, eu respondo. Também dá para usar \\`/tag ${gatilho}\\`.`, 'sucesso');\n    }\n    if (sub === 'remover') {\n      const g = normalizar(i.options.getString('gatilho'));\n      const antes = itens.length;\n      const restantes = itens.filter((x) => normalizar(x.gatilho) !== g);\n      if (restantes.length === antes) return responder(i, 'Não achei essa resposta automática.', 'erro');\n      respostas.de(i.guildId, 'itens').lista = restantes;\n      respostas.salvar();\n      return responder(i, 'Resposta automática apagada.', 'sucesso');\n    }\n    if (!itens.length) return responder(i, 'Nenhuma resposta automática ainda. Use `/autoresposta adicionar`.', 'aviso');\n    const linhas = itens.map((x) => `• \\`${x.gatilho}\\` (${MODOS[x.modo] ?? MODOS.contem}) → ${cortar(x.resposta.replace(/\\n/g, ' '), 60)}`);\n    return i.reply({ embeds: [embed(i.guildId).setTitle(`💬 Respostas automáticas (${itens.length})`).setDescription(cortar(linhas.join('\\n'), 4000))], flags: 64 });\n  },\n  async autocompletar(i) {\n    const foco = normalizar(i.options.getFocused());\n    const itens = respostas.ler(i.guildId, 'itens')?.lista ?? [];\n    await i.respond(itens.filter((x) => normalizar(x.gatilho).includes(foco)).slice(0, 25).map((x) => ({ name: x.gatilho, value: x.gatilho })));\n  },\n};\n\nconst tag = {\n  data: new SlashCommandBuilder()\n    .setName('tag')\n    .setDescription('Mostra uma resposta salva (atalho)')\n    .addStringOption((o) => o.setName('nome').setDescription('Qual resposta').setRequired(true).setAutocomplete(true))\n    .addUserOption((o) => o.setName('para').setDescription('Marcar alguém junto')),\n  async executar(i) {\n    const nome = normalizar(i.options.getString('nome'));\n    const item = (respostas.ler(i.guildId, 'itens')?.lista ?? []).find((x) => normalizar(x.gatilho) === nome);\n    if (!item) return responder(i, 'Não achei essa resposta. Veja as opções enquanto digita.', 'erro');\n    const para = i.options.getUser('para');\n    const texto = preencher(item.resposta, vars(i.guild, para ?? i.user, i.channel));\n    return i.reply({ content: para ? `${para} ${texto}` : texto, allowedMentions: { users: para ? [para.id] : [] } });\n  },\n  autocompletar: autoresposta.autocompletar,\n};\n\nexport default {\n  id: 'autorespostas',\n  nome: 'Respostas automáticas',\n  intents: [GatewayIntentBits.GuildMessages, GatewayIntentBits.MessageContent],\n  comandos: [autoresposta, tag],\n  eventos: { messageCreate: aoMensagem },\n  config: {\n    resumo(guild) {\n      const n = respostas.ler(guild.id, 'itens')?.lista?.length ?? 0;\n      return [n ? `${n} resposta(s) automática(s) (\\`/autoresposta lista\\`)` : 'Nenhuma ainda (`/autoresposta adicionar`)'];\n    },\n  },\n};\n",
  "src/modules/avaliacoes.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, EmbedBuilder, ModalBuilder, PermissionFlagsBits, SlashCommandBuilder, TextInputBuilder, TextInputStyle } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, cor, embed, responder, cortar, sinais, CORES } from '../core/util.js';\n\n/**\n * Avaliação de atendimento (complemento do módulo Tickets).\n * Quando um ticket fecha, quem abriu recebe na DM: \"Como foi o atendimento?\" (1 a 5 estrelas)\n * e pode deixar um comentário. As notas vão para um canal e viram ranking dos atendentes.\n */\n\nconst pendentes = colecao('avaliacoes_pendentes'); // id -> { guildId, numero, atendente, dono, criado }\nconst notas = colecao('avaliacoes'); // guild -> { lista: [...] }\nconst PADRAO = { ativo: true, canal: null };\nconst cfg = (guildId) => ajustes(guildId, 'avaliacoes', PADRAO);\nconst estrelas = (n) => '⭐'.repeat(n) + '☆'.repeat(5 - n);\nconst VALIDADE = 7 * 86400e3;\n\n// respostas na DM (lá não tem servidor, então não dá para usar o \"responder\" de sempre)\nconst respostaDM = (guildId, texto, tipo) => ({\n  embeds: [new EmbedBuilder().setColor(tipo === 'erro' ? CORES.erro : guildId ? cor(guildId) : 0x5865f2).setDescription(texto)],\n  components: [],\n});\n\nsinais.on('ticketFechado', async ({ guild, client, dono, atendente, numero }) => {\n  const c = cfg(guild.id);\n  if (!c.ativo || !dono || dono === atendente) return;\n  const id = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 7)}`;\n  pendentes.raiz[id] = { guildId: guild.id, numero, atendente: atendente ?? null, dono, criado: Date.now() };\n  pendentes.salvar();\n  const user = await client.users.fetch(dono).catch(() => null);\n  await user\n    ?.send({\n      embeds: [\n        embed(guild.id)\n          .setTitle('⭐ Como foi o seu atendimento?')\n          .setDescription(`Seu ticket **#${numero}** em **${guild.name}** foi fechado${atendente ? ` (atendente: <@${atendente}>)` : ''}.\\nDê uma nota de 1 a 5:`),\n      ],\n      components: [\n        new ActionRowBuilder().addComponents(\n          [1, 2, 3, 4, 5].map((n) => new ButtonBuilder().setCustomId(`av:nota:${id}:${n}`).setLabel(String(n)).setEmoji('⭐').setStyle(n >= 4 ? ButtonStyle.Success : n === 3 ? ButtonStyle.Secondary : ButtonStyle.Danger))\n        ),\n      ],\n    })\n    .catch(() => {});\n});\n\nasync function registrar(client, p, nota, comentario) {\n  const guild = client.guilds.cache.get(p.guildId);\n  const lista = (notas.de(p.guildId).lista ??= []);\n  lista.push({ numero: p.numero, atendente: p.atendente, dono: p.dono, nota, comentario: comentario || null, em: Date.now() });\n  if (lista.length > 5000) lista.splice(0, lista.length - 5000);\n  notas.salvar();\n  const canalId = cfg(p.guildId).canal;\n  const canal = guild && canalId && guild.channels.cache.get(canalId);\n  if (canal?.isTextBased()) {\n    const e = embed(p.guildId)\n      .setTitle(`${estrelas(nota)}  Ticket #${p.numero}`)\n      .addFields({ name: 'Atendente', value: p.atendente ? `<@${p.atendente}>` : '—', inline: true }, { name: 'Cliente', value: `<@${p.dono}>`, inline: true })\n      .setTimestamp();\n    if (comentario) e.setDescription(cortar(comentario, 1000));\n    await canal.send({ embeds: [e], allowedMentions: { parse: [] } }).catch(() => {});\n  }\n}\n\nconst componentes = {\n  async av(i, [acao, id, valor]) {\n    const p = pendentes.raiz[id];\n    if (!p || Date.now() - p.criado > VALIDADE) {\n      return i.update(respostaDM(p?.guildId, 'Esta avaliação expirou. Obrigado mesmo assim!', 'erro')).catch(() => {});\n    }\n    if (i.user.id !== p.dono) return;\n\n    if (acao === 'nota') {\n      if (p.nota) return i.update(respostaDM(p.guildId, `Você já avaliou este atendimento com ${estrelas(p.nota)}. Obrigado!`));\n      const nota = Math.min(5, Math.max(1, Number(valor) || 0));\n      p.nota = nota;\n      pendentes.salvar();\n      await registrar(i.client, p, nota, null);\n      return i.update({\n        embeds: [new EmbedBuilder().setColor(cor(p.guildId)).setDescription(`Obrigado! Você deu **${estrelas(nota)}** para o ticket #${p.numero}.\\nQuer deixar um comentário?`)],\n        components: [new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId(`av:comentar:${id}`).setLabel('Comentar').setEmoji('💬').setStyle(ButtonStyle.Primary))],\n      });\n    }\n    if (acao === 'comentar') {\n      return i.showModal(\n        new ModalBuilder()\n          .setCustomId(`av:texto:${id}`)\n          .setTitle(`Ticket #${p.numero}`)\n          .addComponents(\n            new ActionRowBuilder().addComponents(\n              new TextInputBuilder().setCustomId('texto').setLabel('O que achou do atendimento?').setStyle(TextInputStyle.Paragraph).setRequired(true).setMaxLength(800)\n            )\n          )\n      );\n    }\n    if (acao === 'texto' && i.isModalSubmit()) {\n      const texto = i.fields.getTextInputValue('texto').trim();\n      // troca a última nota (sem comentário) pela mesma nota com comentário\n      const lista = notas.ler(p.guildId, 'lista') ?? [];\n      const ultima = [...lista].reverse().find((x) => x.numero === p.numero && x.dono === p.dono && !x.comentario);\n      if (ultima) {\n        ultima.comentario = texto;\n        notas.salvar();\n        const guild = i.client.guilds.cache.get(p.guildId);\n        const canal = guild && cfg(p.guildId).canal && guild.channels.cache.get(cfg(p.guildId).canal);\n        if (canal?.isTextBased()) {\n          await canal\n            .send({ embeds: [embed(p.guildId).setTitle(`💬 Comentário · Ticket #${p.numero}`).setDescription(cortar(texto, 1000)).addFields({ name: 'Nota', value: estrelas(ultima.nota), inline: true })], allowedMentions: { parse: [] } })\n            .catch(() => {});\n        }\n      }\n      delete pendentes.raiz[id];\n      pendentes.salvar();\n      const fim = respostaDM(p.guildId, '💜 Obrigado pelo comentário!');\n      return i.update(fim).catch(() => i.reply(fim));\n    }\n  },\n};\n\nconst avaliacoes = {\n  data: new SlashCommandBuilder()\n    .setName('avaliacoes')\n    .setDescription('Avaliações dos atendimentos (tickets)')\n    .addSubcommand((s) => s.setName('ranking').setDescription('Ranking dos atendentes pela nota média'))\n    .addSubcommand((s) =>\n      s\n        .setName('atendente')\n        .setDescription('Notas de um atendente')\n        .addUserOption((o) => o.setName('usuario').setDescription('Atendente').setRequired(true))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('configurar')\n        .setDescription('(Equipe) Canal das avaliações e ligar/desligar')\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde mostrar as avaliações').addChannelTypes(ChannelType.GuildText))\n        .addBooleanOption((o) => o.setName('ativo').setDescription('Pedir avaliação ao fechar ticket'))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    const lista = notas.ler(i.guildId, 'lista') ?? [];\n    if (sub === 'configurar') {\n      if (!i.member.permissions.has(PermissionFlagsBits.ManageGuild)) return responder(i, 'Só quem tem **Gerenciar servidor** pode configurar.', 'erro');\n      const c = cfg(i.guildId);\n      const canal = i.options.getChannel('canal');\n      const ativo = i.options.getBoolean('ativo');\n      if (canal) c.canal = canal.id;\n      if (ativo !== null) c.ativo = ativo;\n      salvarAjustes();\n      return responder(i, `Avaliações ${c.ativo ? 'ligadas' : 'desligadas'}${c.canal ? ` · aparecem em <#${c.canal}>` : ''}.`, 'sucesso');\n    }\n    if (!lista.length) return responder(i, 'Ainda não há avaliações.', 'aviso');\n    if (sub === 'ranking') {\n      const por = {};\n      for (const x of lista) if (x.atendente) (por[x.atendente] ??= []).push(x.nota);\n      const linhas = Object.entries(por)\n        .map(([id, ns]) => ({ id, media: ns.reduce((a, b) => a + b, 0) / ns.length, n: ns.length }))\n        .sort((a, b) => b.media - a.media || b.n - a.n)\n        .slice(0, 15)\n        .map((x, k) => `**${k + 1}.** <@${x.id}> · ${x.media.toFixed(1).replace('.', ',')} ⭐ (${x.n} avaliação(ões))`);\n      const geral = lista.reduce((a, b) => a + b.nota, 0) / lista.length;\n      return i.reply({\n        embeds: [embed(i.guildId).setTitle('🏆 Ranking de atendimento').setDescription(linhas.join('\\n') || 'Sem atendentes avaliados.').setFooter({ text: `Média geral: ${geral.toFixed(1)} ⭐ em ${lista.length} avaliação(ões)` })],\n        allowedMentions: { parse: [] },\n      });\n    }\n    const u = i.options.getUser('usuario');\n    const deles = lista.filter((x) => x.atendente === u.id);\n    if (!deles.length) return responder(i, `${u} ainda não tem avaliações.`, 'aviso');\n    const media = deles.reduce((a, b) => a + b.nota, 0) / deles.length;\n    const ultimas = deles\n      .slice(-8)\n      .reverse()\n      .map((x) => `${estrelas(x.nota)} · #${x.numero}${x.comentario ? ` · \"${cortar(x.comentario, 80)}\"` : ''}`);\n    return i.reply({\n      embeds: [embed(i.guildId).setTitle(`⭐ ${u.username}`).setDescription(`Média **${media.toFixed(1).replace('.', ',')}** em ${deles.length} avaliação(ões)\\n\\n${ultimas.join('\\n')}`)],\n      flags: 64,\n    });\n  },\n};\n\nexport default {\n  id: 'avaliacoes',\n  nome: 'Avaliação de atendimento',\n  comandos: [avaliacoes],\n  componentes,\n  componentesDM: ['av'],\n  aoIniciar() {\n    // limpa pedidos de avaliação vencidos\n    const limpar = () => {\n      for (const [id, p] of Object.entries(pendentes.raiz)) if (Date.now() - p.criado > VALIDADE) delete pendentes.raiz[id];\n      pendentes.salvar();\n    };\n    limpar();\n    setInterval(limpar, 6 * 3600e3);\n  },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      const n = notas.ler(guild.id, 'lista')?.length ?? 0;\n      return [`${c.ativo ? 'Ligadas' : 'Desligadas'} · canal: ${c.canal ? `<#${c.canal}>` : 'nenhum'} · ${n} avaliação(ões)`];\n    },\n  },\n};\n",
  "src/modules/boasvindas.js": "import { ChannelType, GatewayIntentBits, Partials, PermissionFlagsBits } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, preencher, cortar, foiRemovida } from '../core/util.js';\n\n/**\n * Boas-vindas: mensagem quando alguém entra e sai, mensagem na DM e cargos automáticos.\n * Variáveis nas mensagens: {usuario} (menção), {nome}, {tag}, {servidor}, {membros}\n */\n\nconst PADRAO = {\n  entradaCanal: null,\n  entradaMensagem: 'Seja bem-vindo(a) ao **{servidor}**, {usuario}! Agora somos **{membros}** membros. 🎉',\n  saidaCanal: null,\n  saidaMensagem: '**{tag}** saiu do servidor. Agora somos **{membros}** membros.',\n  dmMensagem: null,\n  cargos: [],\n};\nconst cfg = (guildId) => ajustes(guildId, 'boasvindas', PADRAO);\n\nconst variaveis = (member) => ({\n  usuario: `<@${member.id}>`,\n  nome: member.displayName ?? member.user?.username ?? 'alguém',\n  tag: member.user?.tag ?? member.user?.username ?? member.id,\n  servidor: member.guild.name,\n  membros: member.guild.memberCount,\n});\n\nasync function enviarEntrada(member, canalId, mensagem) {\n  const canal = member.guild.channels.cache.get(canalId);\n  if (!canal?.isTextBased()) return false;\n  const e = embed(member.guild.id)\n    .setAuthor({ name: member.user.tag, iconURL: member.user.displayAvatarURL() })\n    .setDescription(cortar(preencher(mensagem, variaveis(member)), 4000))\n    .setThumbnail(member.user.displayAvatarURL({ size: 256 }))\n    .setTimestamp();\n  await canal.send({ content: `<@${member.id}>`, embeds: [e], allowedMentions: { users: [member.id] } });\n  return true;\n}\n\nasync function aoEntrar(member) {\n  if (foiRemovida(`membro:${member.guild.id}:${member.id}`)) return; // barrado pelo anti-raid\n  const c = cfg(member.guild.id);\n  if (c.entradaCanal) await enviarEntrada(member, c.entradaCanal, c.entradaMensagem).catch(() => {});\n  if (c.dmMensagem && !member.user.bot) {\n    await member.send({ embeds: [embed(member.guild.id).setTitle(member.guild.name).setDescription(preencher(c.dmMensagem, variaveis(member)))] }).catch(() => {});\n  }\n  const cargos = c.cargos.filter((id) => member.guild.roles.cache.get(id)?.editable);\n  if (cargos.length) await member.roles.add(cargos, 'Cargo automático').catch(() => {});\n}\n\nasync function aoSair(member) {\n  if (foiRemovida(`membro:${member.guild.id}:${member.id}`)) return; // expulso pelo anti-raid: sem \"saiu\"\n  const c = cfg(member.guild.id);\n  if (!c.saidaCanal) return;\n  const canal = member.guild.channels.cache.get(c.saidaCanal);\n  if (!canal?.isTextBased()) return;\n  const e = embed(member.guild.id)\n    .setDescription(cortar(preencher(c.saidaMensagem, variaveis(member)), 4000))\n    .setThumbnail(member.user?.displayAvatarURL?.() ?? null);\n  await canal.send({ embeds: [e], allowedMentions: { parse: [] } }).catch(() => {});\n}\n\n// ---------------- /config boasvindas ----------------\nconst opMensagem = (o) =>\n  o.setName('mensagem').setDescription('Variáveis: {usuario} {nome} {tag} {servidor} {membros}').setMaxLength(1500);\n\nconst config = {\n  grupo: 'boasvindas',\n  montar: (g) =>\n    g\n      .setDescription('Boas-vindas, saída e cargos automáticos')\n      .addSubcommand((s) =>\n        s\n          .setName('entrada')\n          .setDescription('Canal e mensagem quando alguém entra')\n          .addChannelOption((o) => o.setName('canal').setDescription('Vazio desliga').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n          .addStringOption(opMensagem)\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('saida')\n          .setDescription('Canal e mensagem quando alguém sai')\n          .addChannelOption((o) => o.setName('canal').setDescription('Vazio desliga').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n          .addStringOption(opMensagem)\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('dm')\n          .setDescription('Mensagem enviada na DM de quem entra')\n          .addStringOption((o) => o.setName('mensagem').setDescription('Vazio desliga. Variáveis: {usuario} {nome} {servidor}').setMaxLength(1500))\n      )\n      .addSubcommand((s) =>\n        s.setName('cargo').setDescription('Cargo dado automaticamente a quem entra (usar de novo remove)').addRoleOption((o) => o.setName('cargo').setDescription('Cargo').setRequired(true))\n      )\n      .addSubcommand((s) => s.setName('testar').setDescription('Simula a sua entrada para ver como fica')),\n  async executar(i, sub) {\n    const c = cfg(i.guildId);\n    if (sub === 'entrada' || sub === 'saida') {\n      const canal = i.options.getChannel('canal');\n      const mensagem = i.options.getString('mensagem');\n      c[`${sub}Canal`] = canal?.id ?? null;\n      if (mensagem) c[`${sub}Mensagem`] = mensagem;\n      salvarAjustes();\n      const nome = sub === 'entrada' ? 'entrada' : 'saída';\n      return responder(i, canal ? `Mensagem de ${nome} em ${canal}.` : `Mensagem de ${nome} desligada.`, 'sucesso');\n    }\n    if (sub === 'dm') {\n      c.dmMensagem = i.options.getString('mensagem') || null;\n      salvarAjustes();\n      return responder(i, c.dmMensagem ? 'Mensagem na DM definida.' : 'Mensagem na DM desligada.', 'sucesso');\n    }\n    if (sub === 'cargo') {\n      const r = i.options.getRole('cargo');\n      if (r.managed || r.id === i.guildId) return responder(i, 'Esse cargo não pode ser dado manualmente.', 'erro');\n      const idx = c.cargos.indexOf(r.id);\n      if (idx >= 0) {\n        c.cargos.splice(idx, 1);\n        salvarAjustes();\n        return responder(i, `${r} não será mais dado automaticamente.`, 'sucesso');\n      }\n      if (c.cargos.length >= 5) return responder(i, 'No máximo 5 cargos automáticos.', 'erro');\n      c.cargos.push(r.id);\n      salvarAjustes();\n      const aviso = r.editable ? '' : ' ⚠️ O meu cargo está abaixo dele: suba o meu cargo na lista para funcionar.';\n      return responder(i, `${r} será dado a quem entrar.${aviso}`, 'sucesso');\n    }\n    if (sub === 'testar') {\n      if (!c.entradaCanal) return responder(i, 'Defina antes o canal com /config boasvindas entrada.', 'aviso');\n      const ok = await enviarEntrada(i.member, c.entradaCanal, c.entradaMensagem).catch(() => false);\n      return responder(i, ok ? `Mensagem de teste enviada em <#${c.entradaCanal}>.` : 'Não consegui enviar no canal configurado: confira as minhas permissões.', ok ? 'sucesso' : 'erro');\n    }\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    return [\n      `Entrada: ${c.entradaCanal ? `<#${c.entradaCanal}>` : 'desligada'}`,\n      `Saída: ${c.saidaCanal ? `<#${c.saidaCanal}>` : 'desligada'}`,\n      `DM: ${c.dmMensagem ? 'ligada' : 'desligada'}`,\n      `Cargos automáticos: ${c.cargos.length ? c.cargos.map((r) => `<@&${r}>`).join(' ') : 'nenhum'}`,\n    ];\n  },\n};\n\nexport default {\n  id: 'boasvindas',\n  nome: 'Boas-vindas',\n  intents: [GatewayIntentBits.GuildMembers],\n  partials: [Partials.GuildMember, Partials.User],\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  eventos: { guildMemberAdd: aoEntrar, guildMemberRemove: aoSair },\n  config,\n};\n",
  "src/modules/callstemp.js": "import { ChannelType, GatewayIntentBits, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, responder, preencher } from '../core/util.js';\n\n/**\n * Calls temporárias: quem entra na call \"➕ Criar sala\" ganha uma call só dele,\n * que é apagada quando fica vazia. O dono controla a sala com /sala.\n */\n\nconst salas = colecao('salas_temporarias'); // guild -> canalId -> { dono, criada }\nconst PADRAO = { criador: null, categoria: null, nome: 'Sala de {nome}', limite: 0 };\nconst cfg = (guildId) => ajustes(guildId, 'callstemp', PADRAO);\nconst espera = new Map(); // anti-spam: userId -> quando criou a última\n\nconst salaDe = (guildId, canalId) => salas.ler(guildId, canalId);\n\nasync function criarSala(state) {\n  const c = cfg(state.guild.id);\n  const membro = state.member;\n  if (Date.now() - (espera.get(membro.id) ?? 0) < 10_000) {\n    await membro.voice.disconnect('Aguarde para criar outra sala').catch(() => {});\n    return;\n  }\n  espera.set(membro.id, Date.now());\n  const parent = (c.categoria && state.guild.channels.cache.get(c.categoria)?.id) || state.channel.parentId || undefined;\n  const nome = preencher(c.nome, { nome: membro.displayName, usuario: membro.user.username }).slice(0, 100);\n  let canal;\n  try {\n    // sem permissões próprias: a sala herda as da categoria (se a categoria é privada, a sala também é)\n    canal = await state.guild.channels.create({\n      name: nome,\n      type: ChannelType.GuildVoice,\n      parent,\n      userLimit: c.limite || undefined,\n      reason: `Sala temporária de ${membro.user.tag}`,\n    });\n  } catch (e) {\n    console.error('[calls temporárias] não consegui criar a sala:', e.message);\n    return;\n  }\n  // o dono sempre entra, mesmo se trancar a sala\n  await canal.permissionOverwrites.edit(membro.id, { ViewChannel: true, Connect: true, Speak: true }).catch(() => {});\n  salas.de(state.guild.id)[canal.id] = { dono: membro.id, criada: Date.now() };\n  salas.salvar();\n  const ok = await membro.voice.setChannel(canal, 'Sala temporária').then(() => true, () => false);\n  if (!ok) await apagarSeVazia(state.guild, canal.id); // a pessoa saiu antes de ser movida\n}\n\nasync function apagarSeVazia(guild, canalId) {\n  if (!salaDe(guild.id, canalId)) return;\n  const canal = guild.channels.cache.get(canalId);\n  if (canal && canal.members.size > 0) return;\n  salas.apagar(guild.id, canalId);\n  if (canal) await canal.delete('Sala temporária vazia').catch(() => {});\n}\n\nasync function aoMudarVoz(antes, depois) {\n  const guild = depois.guild ?? antes.guild;\n  const c = cfg(guild.id);\n  if (depois.channelId && depois.channelId === c.criador && depois.member && !depois.member.user.bot) await criarSala(depois);\n  if (antes.channelId && antes.channelId !== depois.channelId) await apagarSeVazia(guild, antes.channelId);\n}\n\n// ---------------- /sala (para o dono) ----------------\nconst sala = {\n  data: new SlashCommandBuilder()\n    .setName('sala')\n    .setDescription('Controla a sua sala temporária (entre nela antes)')\n    .addSubcommand((s) => s.setName('nome').setDescription('Muda o nome da sala').addStringOption((o) => o.setName('nome').setDescription('Novo nome').setRequired(true).setMaxLength(90)))\n    .addSubcommand((s) => s.setName('limite').setDescription('Máximo de pessoas (0 = sem limite)').addIntegerOption((o) => o.setName('pessoas').setDescription('0 a 99').setRequired(true).setMinValue(0).setMaxValue(99)))\n    .addSubcommand((s) => s.setName('trancar').setDescription('Ninguém novo entra (só quem você permitir)'))\n    .addSubcommand((s) => s.setName('destrancar').setDescription('Libera a entrada de novo'))\n    .addSubcommand((s) => s.setName('permitir').setDescription('Deixa alguém entrar mesmo trancada').addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true)))\n    .addSubcommand((s) => s.setName('expulsar').setDescription('Tira alguém e impede de voltar').addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true)))\n    .addSubcommand((s) => s.setName('reivindicar').setDescription('Vira dono da sala se o dono saiu')),\n  async executar(i) {\n    const canal = i.member.voice?.channel;\n    const s = canal && salaDe(i.guildId, canal.id);\n    if (!s) return responder(i, 'Entre na sua sala temporária para usar este comando.', 'erro');\n    const sub = i.options.getSubcommand();\n\n    if (sub === 'reivindicar') {\n      if (s.dono === i.user.id) return responder(i, 'Você já é o dono desta sala.', 'aviso');\n      if (canal.members.has(s.dono)) return responder(i, `O dono (<@${s.dono}>) ainda está na sala.`, 'erro');\n      s.dono = i.user.id;\n      salas.salvar();\n      await canal.permissionOverwrites.edit(i.user.id, { ViewChannel: true, Connect: true, Speak: true }).catch(() => {});\n      return responder(i, 'Agora a sala é sua. Use /sala para controlar.', 'sucesso');\n    }\n    if (s.dono !== i.user.id) return responder(i, `Só o dono da sala (<@${s.dono}>) pode fazer isso.`, 'erro');\n\n    const tentar = async (fn, ok) => {\n      const deu = await fn().then(() => true, () => false);\n      return responder(i, deu ? ok : 'Não consegui. Confira as minhas permissões (Gerenciar canais e Gerenciar cargos).', deu ? 'sucesso' : 'erro');\n    };\n    if (sub === 'nome') {\n      const nome = i.options.getString('nome');\n      // o Discord só deixa renomear 2 vezes a cada 10 minutos: responde antes de esperar\n      await i.deferReply({ flags: 64 });\n      const ok = await canal.setName(nome).then(() => true, () => false);\n      return i.editReply(ok ? `✅ Sala renomeada para **${nome}**.` : '❌ Não consegui renomear agora (o Discord limita a 2 vezes a cada 10 minutos).');\n    }\n    if (sub === 'limite') {\n      const n = i.options.getInteger('pessoas');\n      return tentar(() => canal.setUserLimit(n), n ? `Limite: **${n}** pessoa(s).` : 'Sala sem limite.');\n    }\n    if (sub === 'trancar') return tentar(() => canal.permissionOverwrites.edit(i.guild.roles.everyone, { Connect: false }), '🔒 Sala trancada.');\n    if (sub === 'destrancar') return tentar(() => canal.permissionOverwrites.edit(i.guild.roles.everyone, { Connect: null }), '🔓 Sala liberada.');\n    const u = i.options.getUser('usuario');\n    if (u.id === i.user.id) return responder(i, 'Escolha outra pessoa.', 'erro');\n    if (sub === 'permitir') return tentar(() => canal.permissionOverwrites.edit(u.id, { ViewChannel: true, Connect: true }), `${u} pode entrar na sala.`);\n    // expulsar\n    return tentar(async () => {\n      await canal.permissionOverwrites.edit(u.id, { Connect: false });\n      const m = canal.members.get(u.id);\n      if (m) await m.voice.disconnect('Expulso da sala temporária');\n    }, `${u} foi tirado(a) da sala e não pode voltar.`);\n  },\n};\n\n// ---------------- /salas (equipe) ----------------\nconst salasCmd = {\n  data: new SlashCommandBuilder()\n    .setName('salas')\n    .setDescription('Configura as calls temporárias')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('configurar')\n        .setDescription('Escolhe a call \"Criar sala\" (ou cria uma)')\n        .addChannelOption((o) => o.setName('canal').setDescription('Call que cria as salas (vazio = eu crio uma)').addChannelTypes(ChannelType.GuildVoice))\n        .addChannelOption((o) => o.setName('categoria').setDescription('Onde as salas aparecem (padrão: a mesma da call)').addChannelTypes(ChannelType.GuildCategory))\n        .addStringOption((o) => o.setName('nome').setDescription('Nome das salas. Variáveis: {nome} {usuario}').setMaxLength(80))\n        .addIntegerOption((o) => o.setName('limite').setDescription('Limite padrão de pessoas (0 = sem limite)').setMinValue(0).setMaxValue(99))\n    )\n    .addSubcommand((s) => s.setName('desligar').setDescription('Para de criar salas (as abertas continuam até esvaziar)')),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    if (i.options.getSubcommand() === 'desligar') {\n      c.criador = null;\n      salvarAjustes();\n      return responder(i, 'Calls temporárias desligadas.', 'sucesso');\n    }\n    let canal = i.options.getChannel('canal');\n    const categoria = i.options.getChannel('categoria');\n    if (!canal) {\n      canal = await i.guild.channels\n        .create({ name: '➕ Criar sala', type: ChannelType.GuildVoice, parent: categoria?.id, reason: 'Calls temporárias' })\n        .catch(() => null);\n      if (!canal) return responder(i, 'Não consegui criar a call. Preciso da permissão **Gerenciar canais**.', 'erro');\n    }\n    c.criador = canal.id;\n    if (categoria) c.categoria = categoria.id;\n    const nome = i.options.getString('nome');\n    if (nome) c.nome = nome;\n    const limite = i.options.getInteger('limite');\n    if (limite !== null) c.limite = limite;\n    salvarAjustes();\n    return responder(i, `Pronto! Quem entrar em ${canal} ganha uma sala própria (nome: \"${c.nome}\"). O dono controla com \\`/sala\\`.`, 'sucesso');\n  },\n};\n\nexport default {\n  id: 'callstemp',\n  nome: 'Calls temporárias',\n  intents: [GatewayIntentBits.GuildVoiceStates],\n  permissoes: [PermissionFlagsBits.ManageChannels, PermissionFlagsBits.ManageRoles, PermissionFlagsBits.MoveMembers, PermissionFlagsBits.Connect],\n  comandos: [salasCmd, sala],\n  eventos: { voiceStateUpdate: aoMudarVoz },\n  async aoIniciar(client) {\n    // salas que ficaram vazias enquanto o bot estava desligado\n    for (const [guildId, lista] of Object.entries(salas.raiz)) {\n      const guild = client.guilds.cache.get(guildId);\n      if (!guild) continue;\n      for (const canalId of Object.keys(lista)) await apagarSeVazia(guild, canalId);\n    }\n  },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      const n = Object.keys(salas.ler(guild.id) ?? {}).length;\n      return [c.criador ? `Criar sala: <#${c.criador}> · nome \"${c.nome}\" · ${n} sala(s) aberta(s)` : 'Desligado (`/salas configurar`)'];\n    },\n  },\n};\n",
  "src/modules/cargos.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { embed, responder, cortar } from '../core/util.js';\n\n/**\n * Cargos por botão: painéis onde cada membro pega ou tira cargos sozinho\n * (cores, notificações, jogos, pronomes...). Até 25 cargos por painel.\n */\n\nconst paineis = colecao('paineis_cargos');\n\nfunction componentes(p) {\n  const rows = [];\n  p.cargos.forEach((c, n) => {\n    if (n % 5 === 0) rows.push(new ActionRowBuilder());\n    const b = new ButtonBuilder().setCustomId(`cr:${c.id}`).setLabel(cortar(c.rotulo, 80)).setStyle(ButtonStyle.Secondary);\n    if (c.emoji) b.setEmoji(c.emoji);\n    rows.at(-1).addComponents(b);\n  });\n  return rows;\n}\n\nconst idDaMensagem = (t) => String(t).split('/').pop().replace(/\\D/g, '');\n\nasync function buscarPainel(i, ref) {\n  const id = idDaMensagem(ref);\n  const p = paineis.ler(i.guildId, id);\n  if (!p) return [null, null];\n  const canal = await i.guild.channels.fetch(p.canal).catch(() => null);\n  const msg = await canal?.messages.fetch(id).catch(() => null);\n  return [p, msg];\n}\n\nconst cargos = {\n  data: new SlashCommandBuilder()\n    .setName('cargos')\n    .setDescription('Painéis de cargos por botão')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageRoles)\n    .addSubcommand((s) =>\n      s\n        .setName('painel')\n        .setDescription('Cria um painel novo (depois adicione cargos nele)')\n        .addStringOption((o) => o.setName('titulo').setDescription('Título').setRequired(true).setMaxLength(100))\n        .addStringOption((o) => o.setName('descricao').setDescription('Texto do painel').setMaxLength(1500))\n        .addChannelOption((o) => o.setName('canal').setDescription('Padrão: este canal').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('adicionar')\n        .setDescription('Coloca um cargo num painel')\n        .addStringOption((o) => o.setName('painel').setDescription('ID ou link da mensagem do painel').setRequired(true).setMaxLength(120))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Cargo').setRequired(true))\n        .addStringOption((o) => o.setName('rotulo').setDescription('Texto do botão (padrão: nome do cargo)').setMaxLength(80))\n        .addStringOption((o) => o.setName('emoji').setDescription('Emoji do botão').setMaxLength(60))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('remover')\n        .setDescription('Tira um cargo de um painel')\n        .addStringOption((o) => o.setName('painel').setDescription('ID ou link da mensagem do painel').setRequired(true).setMaxLength(120))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Cargo').setRequired(true))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    if (sub === 'painel') {\n      const canal = i.options.getChannel('canal') ?? i.channel;\n      const e = embed(i.guildId)\n        .setTitle(i.options.getString('titulo'))\n        .setDescription(i.options.getString('descricao') || 'Clique nos botões para pegar ou tirar cargos.');\n      const msg = await canal.send({ embeds: [e] }).catch(() => null);\n      if (!msg) return responder(i, `Não consegui enviar mensagens em ${canal}. Confira as minhas permissões.`, 'erro');\n      paineis.de(i.guildId)[msg.id] = { canal: canal.id, cargos: [] };\n      paineis.salvar();\n      return responder(i, `Painel criado em ${canal}. Agora use **/cargos adicionar painel:${msg.id}** para colocar os cargos.`, 'sucesso');\n    }\n\n    const [p, msg] = await buscarPainel(i, i.options.getString('painel'));\n    if (!p || !msg) return responder(i, 'Painel não encontrado. Use o ID ou o link da mensagem do painel.', 'erro');\n    const r = i.options.getRole('cargo');\n\n    if (sub === 'adicionar') {\n      if (r.managed || r.id === i.guildId) return responder(i, 'Esse cargo não pode ser dado por botão.', 'erro');\n      if (!r.editable) return responder(i, `Não consigo dar ${r}: suba o meu cargo acima dele na lista de cargos.`, 'erro');\n      if (r.permissions.has(PermissionFlagsBits.Administrator) || r.permissions.has(PermissionFlagsBits.ManageGuild)) {\n        return responder(i, 'Por segurança, cargos com permissões de administração não podem ir para painéis.', 'erro');\n      }\n      if (p.cargos.some((c) => c.id === r.id)) return responder(i, 'Esse cargo já está no painel.', 'aviso');\n      if (p.cargos.length >= 25) return responder(i, 'Um painel aceita no máximo 25 cargos.', 'erro');\n      const emoji = i.options.getString('emoji')?.trim() || null;\n      p.cargos.push({ id: r.id, rotulo: i.options.getString('rotulo') || r.name, emoji });\n      try {\n        await msg.edit({ components: componentes(p) });\n      } catch {\n        p.cargos.pop();\n        return responder(i, 'Não consegui atualizar o painel. Confira se o emoji é válido.', 'erro');\n      }\n      paineis.salvar();\n      return responder(i, `${r} adicionado ao painel.`, 'sucesso');\n    }\n    if (sub === 'remover') {\n      const antes = p.cargos.length;\n      p.cargos = p.cargos.filter((c) => c.id !== r.id);\n      if (p.cargos.length === antes) return responder(i, 'Esse cargo não está no painel.', 'aviso');\n      await msg.edit({ components: componentes(p) }).catch(() => {});\n      paineis.salvar();\n      return responder(i, `${r} removido do painel.`, 'sucesso');\n    }\n  },\n};\n\nconst botoes = {\n  async cr(i, [cargoId]) {\n    // o cargo precisa estar mesmo neste painel\n    const p = paineis.ler(i.guildId, i.message?.id);\n    if (!p?.cargos.some((c) => c.id === cargoId)) return responder(i, 'Este botão não está mais ativo.', 'erro');\n    const r = i.guild.roles.cache.get(cargoId);\n    if (!r) return responder(i, 'Esse cargo não existe mais. Avise a equipe.', 'erro');\n    if (!r.editable) return responder(i, 'Não consigo dar esse cargo agora (o meu cargo está abaixo dele). Avise a equipe.', 'erro');\n    const tem = i.member.roles.cache.has(r.id);\n    const ok = await (tem ? i.member.roles.remove(r, 'Painel de cargos') : i.member.roles.add(r, 'Painel de cargos')).then(() => true, () => false);\n    if (!ok) return responder(i, 'Não consegui mudar o seu cargo agora. Avise a equipe.', 'erro');\n    return responder(i, tem ? `Cargo ${r} removido.` : `Você recebeu ${r}!`, 'sucesso');\n  },\n};\n\nexport default {\n  id: 'cargos',\n  nome: 'Cargos por botão',\n  comandos: [cargos],\n  componentes: botoes,\n  permissoes: [PermissionFlagsBits.ManageRoles],\n};\n",
  "src/modules/cargostemp.js": "import { ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, lerDuracao, duracaoTexto, ts, cortar } from '../core/util.js';\n\n/**\n * Cargos temporários: /cargotemp dar @pessoa @VIP 30d. O cargo sai sozinho no fim do prazo\n * (mesmo se o bot reiniciar). Dar de novo o mesmo cargo renova o prazo.\n */\n\nconst temps = colecao('cargos_temporarios'); // guild -> { lista: [{ user, cargo, ate, por, motivo }] }\nconst cfg = (guildId) => ajustes(guildId, 'cargostemp', { registro: null });\nconst lista = (guildId) => (temps.de(guildId).lista ??= []);\nconst MAX = 365 * 86400e3;\n\nasync function registrar(guild, texto) {\n  const id = cfg(guild.id).registro;\n  const canal = id && guild.channels.cache.get(id);\n  if (canal?.isTextBased()) await canal.send({ embeds: [embed(guild.id).setDescription(texto).setTimestamp()], allowedMentions: { parse: [] } }).catch(() => {});\n}\n\nasync function verificar(client) {\n  const agora = Date.now();\n  for (const [guildId, g] of Object.entries(temps.raiz)) {\n    const guild = client.guilds.cache.get(guildId);\n    if (!guild || !g.lista?.length) continue;\n    const vencidos = g.lista.filter((x) => x.ate <= agora);\n    if (!vencidos.length) continue;\n    g.lista = g.lista.filter((x) => x.ate > agora);\n    temps.salvar();\n    for (const x of vencidos) {\n      const membro = await guild.members.fetch(x.user).catch(() => null);\n      if (membro?.roles.cache.has(x.cargo)) {\n        const ok = await membro.roles.remove(x.cargo, 'Fim do cargo temporário').then(() => true, () => false);\n        await registrar(guild, `⏳ ${ok ? 'Tirei' : 'Não consegui tirar'} <@&${x.cargo}> de <@${x.user}> (fim do prazo).`);\n      }\n    }\n  }\n}\n\nconst cargotemp = {\n  data: new SlashCommandBuilder()\n    .setName('cargotemp')\n    .setDescription('Cargos que saem sozinhos depois de um tempo')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageRoles)\n    .addSubcommand((s) =>\n      s\n        .setName('dar')\n        .setDescription('Dá um cargo por um tempo')\n        .addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Qual cargo').setRequired(true))\n        .addStringOption((o) => o.setName('duracao').setDescription('Ex.: 7d, 30d, 12h (máximo 365d)').setRequired(true))\n        .addStringOption((o) => o.setName('motivo').setDescription('Opcional').setMaxLength(200))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('tirar')\n        .setDescription('Tira o cargo agora')\n        .addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Qual cargo').setRequired(true))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('lista')\n        .setDescription('Cargos temporários ativos')\n        .addUserOption((o) => o.setName('usuario').setDescription('Só de uma pessoa (opcional)'))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('registro')\n        .setDescription('Canal que registra quando o cargo sai')\n        .addChannelOption((o) => o.setName('canal').setDescription('Canal').setRequired(true).addChannelTypes(ChannelType.GuildText))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    const l = lista(i.guildId);\n    if (sub === 'registro') {\n      cfg(i.guildId).registro = i.options.getChannel('canal').id;\n      salvarAjustes();\n      return responder(i, 'Canal de registro salvo.', 'sucesso');\n    }\n    if (sub === 'lista') {\n      const u = i.options.getUser('usuario');\n      const ativos = l.filter((x) => !u || x.user === u.id).sort((a, b) => a.ate - b.ate);\n      if (!ativos.length) return responder(i, 'Nenhum cargo temporário ativo.', 'aviso');\n      const linhas = ativos.slice(0, 40).map((x) => `<@${x.user}> · <@&${x.cargo}> · sai ${ts(x.ate)}`);\n      return i.reply({ embeds: [embed(i.guildId).setTitle('⏳ Cargos temporários').setDescription(cortar(linhas.join('\\n'), 4000))], flags: 64, allowedMentions: { parse: [] } });\n    }\n    const u = i.options.getUser('usuario');\n    const cargo = i.options.getRole('cargo');\n    const membro = await i.guild.members.fetch(u.id).catch(() => null);\n    if (!membro) return responder(i, 'Essa pessoa não está no servidor.', 'erro');\n    if (sub === 'tirar') {\n      temps.de(i.guildId).lista = l.filter((x) => !(x.user === u.id && x.cargo === cargo.id));\n      temps.salvar();\n      const ok = await membro.roles.remove(cargo, `Cargo temporário tirado por ${i.user.tag}`).then(() => true, () => false);\n      return responder(i, ok ? `Tirei ${cargo} de ${u}.` : 'Não consegui tirar o cargo (confira a minha posição na lista de cargos).', ok ? 'sucesso' : 'erro');\n    }\n    // dar\n    const ms = lerDuracao(i.options.getString('duracao'));\n    if (!ms || ms > MAX) return responder(i, 'Duração inválida. Use algo como **7d**, **30d** ou **12h** (máximo 365d).', 'erro');\n    if (cargo.managed || cargo.id === i.guildId) return responder(i, 'Esse cargo não pode ser dado.', 'erro');\n    if (!cargo.editable) return responder(i, `Meu cargo precisa ficar acima de ${cargo}.`, 'erro');\n    if (i.user.id !== i.guild.ownerId && cargo.position >= i.member.roles.highest.position) return responder(i, 'Você só pode dar cargos abaixo do seu.', 'erro');\n    const ok = await membro.roles.add(cargo, `Cargo temporário (${duracaoTexto(ms)}) por ${i.user.tag}`).then(() => true, () => false);\n    if (!ok) return responder(i, 'Não consegui dar o cargo.', 'erro');\n    const existente = l.find((x) => x.user === u.id && x.cargo === cargo.id);\n    const ate = Date.now() + ms;\n    const motivo = i.options.getString('motivo') ?? null;\n    if (existente) Object.assign(existente, { ate, por: i.user.id, motivo });\n    else l.push({ user: u.id, cargo: cargo.id, ate, por: i.user.id, motivo });\n    temps.salvar();\n    await registrar(i.guild, `⏳ ${i.user} deu <@&${cargo.id}> para ${u} até ${ts(ate, 'f')}${motivo ? ` · ${cortar(motivo, 200)}` : ''}`);\n    return responder(i, `${u} recebeu ${cargo} até ${ts(ate, 'f')} (${ts(ate)}).${existente ? ' (prazo renovado)' : ''}`, 'sucesso');\n  },\n};\n\nexport default {\n  id: 'cargostemp',\n  nome: 'Cargos temporários',\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  comandos: [cargotemp],\n  aoIniciar(client) {\n    verificar(client).catch((e) => console.error('[cargos temporários]', e.message));\n    setInterval(() => verificar(client).catch((e) => console.error('[cargos temporários]', e.message)), 60_000);\n  },\n  config: {\n    resumo(guild) {\n      const n = temps.ler(guild.id, 'lista')?.length ?? 0;\n      return [`${n} cargo(s) temporário(s) ativo(s)${cfg(guild.id).registro ? ` · registro em <#${cfg(guild.id).registro}>` : ''}`];\n    },\n  },\n};\n",
  "src/modules/contadores.js": "import { ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, fmt } from '../core/util.js';\n\n/**\n * Contadores: calls trancadas cujo nome mostra um número do servidor\n * (\"👥 Membros: 1.234\"). Atualizam sozinhos a cada 10 minutos\n * (o Discord só deixa renomear um canal 2 vezes a cada 10 minutos).\n */\n\nconst TIPOS = {\n  membros: { nome: 'Membros', modelo: '👥 Membros: {n}' },\n  online: { nome: 'Online agora', modelo: '🟢 Online: {n}' },\n  boosts: { nome: 'Boosts', modelo: '🚀 Boosts: {n}' },\n  canais: { nome: 'Canais', modelo: '💬 Canais: {n}' },\n  cargos: { nome: 'Cargos', modelo: '🎭 Cargos: {n}' },\n};\nconst LIMITE = 5;\nconst cfg = (guildId) => ajustes(guildId, 'contadores', { lista: [] });\n\n/** Números do servidor. Membros e online vêm da API (não precisa de intent especial). */\nasync function numeros(guild) {\n  const g = await guild.client.guilds.fetch({ guild: guild.id, withCounts: true, force: true }).catch(() => guild);\n  return {\n    membros: g.approximateMemberCount ?? guild.memberCount ?? 0,\n    online: g.approximatePresenceCount ?? 0,\n    boosts: g.premiumSubscriptionCount ?? guild.premiumSubscriptionCount ?? 0,\n    canais: guild.channels.cache.filter((c) => c.type !== ChannelType.GuildCategory && !c.isThread()).size,\n    cargos: guild.roles.cache.size - 1,\n  };\n}\nconst nomeDo = (item, n) => item.modelo.replace('{n}', fmt(n[item.tipo])).slice(0, 100);\n\nasync function atualizar(guild) {\n  const c = cfg(guild.id);\n  if (!c.lista.length) return;\n  const n = await numeros(guild);\n  let mudou = false;\n  for (const item of [...c.lista]) {\n    const canal = guild.channels.cache.get(item.canal);\n    if (!canal) {\n      c.lista = c.lista.filter((x) => x.canal !== item.canal); // apagaram o canal\n      mudou = true;\n      continue;\n    }\n    const nome = nomeDo(item, n);\n    if (canal.name !== nome) await canal.setName(nome, 'Contador').catch(() => {});\n  }\n  if (mudou) salvarAjustes();\n}\n\nconst contadores = {\n  data: new SlashCommandBuilder()\n    .setName('contadores')\n    .setDescription('Canais que mostram números do servidor')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('criar')\n        .setDescription('Cria um contador')\n        .addStringOption((o) =>\n          o\n            .setName('tipo')\n            .setDescription('O que contar')\n            .setRequired(true)\n            .addChoices(...Object.entries(TIPOS).map(([value, t]) => ({ name: t.nome, value })))\n        )\n        .addStringOption((o) => o.setName('nome').setDescription('Nome do canal; {n} vira o número (ex.: \"👥 Galera: {n}\")').setMaxLength(80))\n        .addChannelOption((o) => o.setName('categoria').setDescription('Categoria onde criar').addChannelTypes(ChannelType.GuildCategory))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('remover')\n        .setDescription('Apaga um contador')\n        .addChannelOption((o) => o.setName('canal').setDescription('O canal do contador').setRequired(true).addChannelTypes(ChannelType.GuildVoice))\n    )\n    .addSubcommand((s) => s.setName('lista').setDescription('Mostra os contadores')),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const sub = i.options.getSubcommand();\n    if (sub === 'lista') {\n      if (!c.lista.length) return responder(i, 'Nenhum contador. Use `/contadores criar`.', 'aviso');\n      return i.reply({ embeds: [embed(i.guildId).setTitle('📈 Contadores').setDescription(c.lista.map((x) => `<#${x.canal}> · ${TIPOS[x.tipo].nome}`).join('\\n'))], flags: 64 });\n    }\n    if (sub === 'remover') {\n      const canal = i.options.getChannel('canal');\n      if (!c.lista.some((x) => x.canal === canal.id)) return responder(i, 'Esse canal não é um contador.', 'erro');\n      c.lista = c.lista.filter((x) => x.canal !== canal.id);\n      salvarAjustes();\n      await canal.delete('Contador removido').catch(() => {});\n      return responder(i, 'Contador removido.', 'sucesso');\n    }\n    // criar\n    if (c.lista.length >= LIMITE) return responder(i, `No máximo ${LIMITE} contadores.`, 'erro');\n    const tipo = i.options.getString('tipo');\n    let modelo = i.options.getString('nome') || TIPOS[tipo].modelo;\n    if (!modelo.includes('{n}')) modelo += ': {n}';\n    await i.deferReply({ flags: 64 });\n    const n = await numeros(i.guild);\n    const canal = await i.guild.channels\n      .create({\n        name: nomeDo({ tipo, modelo }, n),\n        type: ChannelType.GuildVoice,\n        parent: i.options.getChannel('categoria')?.id,\n        position: 0,\n        permissionOverwrites: [\n          { id: i.guild.roles.everyone.id, deny: [PermissionFlagsBits.Connect] },\n          { id: i.guild.members.me.id, allow: [PermissionFlagsBits.ViewChannel, PermissionFlagsBits.Connect, PermissionFlagsBits.ManageChannels] },\n        ],\n        reason: 'Contador',\n      })\n      .catch((e) => {\n        console.error('[contadores]', e.message);\n        return null;\n      });\n    if (!canal) return i.editReply('❌ Não consegui criar o canal. Preciso das permissões **Gerenciar canais** e **Conectar**.');\n    c.lista.push({ canal: canal.id, tipo, modelo });\n    salvarAjustes();\n    return i.editReply(`✅ Contador criado: ${canal}. Ele se atualiza a cada 10 minutos.`);\n  },\n};\n\nexport default {\n  id: 'contadores',\n  nome: 'Contadores',\n  comandos: [contadores],\n  permissoes: [PermissionFlagsBits.ManageChannels, PermissionFlagsBits.Connect],\n  aoIniciar(client) {\n    const rodar = async () => {\n      for (const guild of client.guilds.cache.values()) await atualizar(guild).catch((e) => console.error('[contadores]', e.message));\n    };\n    rodar();\n    setInterval(rodar, 10 * 60_000);\n  },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      return [c.lista.length ? c.lista.map((x) => `<#${x.canal}> (${TIPOS[x.tipo].nome})`).join(' · ') : 'Nenhum (`/contadores criar`)'];\n    },\n  },\n};\n",
  "src/modules/contagem.js": "import { ChannelType, GatewayIntentBits, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, fmt, foiRemovida } from '../core/util.js';\n\n/**\n * Jogo de contar: num canal, todo mundo conta 1, 2, 3...\n * A mesma pessoa não pode contar duas vezes seguidas. Errou, volta para o 1.\n * Guarda o recorde do servidor.\n */\n\nconst PADRAO = { canal: null, atual: 0, ultimo: null, recorde: 0, recordeEm: null, recordeDaRodada: 0 }; // recordeDaRodada: o recorde quando a rodada começou\nconst cfg = (guildId) => ajustes(guildId, 'contagem', PADRAO);\n\nasync function aoMensagem(msg) {\n  if (!msg.inGuild() || msg.author.bot) return;\n  const c = cfg(msg.guildId);\n  if (msg.channelId !== c.canal || foiRemovida(msg.id)) return;\n  const texto = msg.content.trim().replace(/\\./g, '');\n  if (!/^\\d{1,9}$/.test(texto)) return; // conversa normal: ignora\n  const n = Number(texto);\n  const esperado = c.atual + 1;\n\n  const erro = n !== esperado ? `O próximo era **${fmt(esperado)}**.` : msg.author.id === c.ultimo ? 'Não vale contar duas vezes seguidas.' : null;\n  if (erro) {\n    const chegou = c.atual;\n    c.atual = 0;\n    c.ultimo = null;\n    c.recordeDaRodada = c.recorde;\n    salvarAjustes();\n    await msg.react('❌').catch(() => {});\n    await msg\n      .reply({\n        embeds: [embed(msg.guildId).setColor(0xef4444).setDescription(`💥 ${msg.author} errou! ${erro}\\nVocês chegaram a **${fmt(chegou)}**. Recomeçando do **1**. (Recorde: ${fmt(c.recorde)})`)],\n        allowedMentions: { users: [] },\n      })\n      .catch(() => {});\n    return;\n  }\n  c.atual = n;\n  c.ultimo = msg.author.id;\n  // 🏆 só no número que passa o recorde anterior (não em todos os números de uma rodada nova)\n  const bateuRecorde = c.recordeDaRodada > 0 && n === c.recordeDaRodada + 1;\n  if (n > c.recorde) {\n    c.recorde = n;\n    c.recordeEm = Date.now();\n  }\n  salvarAjustes();\n  await msg.react(bateuRecorde ? '🏆' : '✅').catch(() => {});\n  if (bateuRecorde) await msg.channel.send({ embeds: [embed(msg.guildId).setDescription(`🏆 **Novo recorde!** Vocês passaram de ${fmt(n - 1)}.`)] }).catch(() => {});\n}\n\nconst contagem = {\n  data: new SlashCommandBuilder()\n    .setName('contagem')\n    .setDescription('Jogo de contar')\n    .addSubcommand((s) => s.setName('status').setDescription('Número atual e recorde'))\n    .addSubcommand((s) =>\n      s\n        .setName('canal')\n        .setDescription('(Equipe) Escolhe o canal do jogo')\n        .addChannelOption((o) => o.setName('canal').setDescription('Canal da contagem').setRequired(true).addChannelTypes(ChannelType.GuildText))\n    )\n    .addSubcommand((s) => s.setName('zerar').setDescription('(Equipe) Volta a contagem para 0')),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const sub = i.options.getSubcommand();\n    if (sub === 'status') {\n      if (!c.canal) return responder(i, 'O jogo de contar não está ligado.', 'aviso');\n      return responder(\n        i,\n        `🔢 Em <#${c.canal}>: estamos no **${fmt(c.atual)}** (próximo: ${fmt(c.atual + 1)}).\\n🏆 Recorde: **${fmt(c.recorde)}**${c.recordeEm ? ` (<t:${Math.floor(c.recordeEm / 1000)}:R>)` : ''}`,\n        'info'\n      );\n    }\n    if (!i.member.permissions.has(PermissionFlagsBits.ManageGuild)) return responder(i, 'Só quem tem **Gerenciar servidor** pode fazer isso.', 'erro');\n    if (sub === 'zerar') {\n      c.atual = 0;\n      c.ultimo = null;\n      c.recordeDaRodada = c.recorde;\n      salvarAjustes();\n      return responder(i, 'Contagem zerada. O próximo número é 1.', 'sucesso');\n    }\n    const canal = i.options.getChannel('canal');\n    c.canal = canal.id;\n    c.atual = 0;\n    c.ultimo = null;\n    c.recordeDaRodada = c.recorde;\n    salvarAjustes();\n    await canal.send({ embeds: [embed(i.guildId).setTitle('🔢 Jogo de contar').setDescription('Contem a partir do **1**, um número por mensagem.\\nA mesma pessoa não pode contar duas vezes seguidas. Errou, volta para o 1!')] }).catch(() => {});\n    return responder(i, `Jogo de contar ligado em ${canal}.`, 'sucesso');\n  },\n};\n\nexport default {\n  id: 'contagem',\n  nome: 'Jogo de contar',\n  intents: [GatewayIntentBits.GuildMessages, GatewayIntentBits.MessageContent],\n  comandos: [contagem],\n  eventos: { messageCreate: aoMensagem },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      return [c.canal ? `<#${c.canal}> · atual ${fmt(c.atual)} · recorde ${fmt(c.recorde)}` : 'Desligado (`/contagem canal`)'];\n    },\n  },\n};\n",
  "src/modules/convites.js": "import { ChannelType, GatewayIntentBits, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, fmt, preencher } from '../core/util.js';\n\n/**\n * Rastreio de convites: descobre por qual convite cada pessoa entrou e quem convidou.\n * Conta entradas, saídas e contas falsas (muito novas), com ranking.\n * Precisa da \"Server Members Intent\" e da permissão Gerenciar servidor (para ler os convites).\n */\n\nconst dados = colecao('convites'); // guild -> { membros: {userId: {por, codigo, em, saiu}}, contas: {inviterId: {total, saiu, falsos}} }\nconst PADRAO = { canal: null, mensagem: '📥 {usuario} entrou · convidado(a) por {convidou} ({convites} convite(s))', diasFalso: 7 };\nconst cfg = (guildId) => ajustes(guildId, 'convites', PADRAO);\nconst usos = new Map(); // guildId -> Map(codigo -> { usos, dono })\nconst mapa = (lista) => new Map(lista.map((inv) => [inv.code, { usos: inv.uses ?? 0, dono: inv.inviterId ?? inv.inviter?.id ?? null }]));\n\nasync function carregarConvites(guild) {\n  if (!guild.members.me?.permissions.has(PermissionFlagsBits.ManageGuild)) return false;\n  const lista = await guild.invites.fetch().catch(() => null);\n  if (!lista) return false;\n  usos.set(guild.id, mapa(lista));\n  return true;\n}\n\nconst conta = (guildId, id) => {\n  const c = dados.de(guildId, 'contas', id);\n  c.total ??= 0;\n  c.saiu ??= 0;\n  c.falsos ??= 0;\n  return c;\n};\nconst validos = (c) => Math.max(0, (c?.total ?? 0) - (c?.saiu ?? 0) - (c?.falsos ?? 0));\n\nasync function aoEntrar(member) {\n  if (member.user.bot) return;\n  const guild = member.guild;\n  const antes = usos.get(guild.id) ?? new Map();\n  const agora = await guild.invites.fetch().catch(() => null);\n  let codigo = null;\n  let por = null;\n  if (agora) {\n    for (const inv of agora.values()) {\n      if ((inv.uses ?? 0) > (antes.get(inv.code)?.usos ?? 0)) {\n        codigo = inv.code;\n        por = inv.inviterId ?? inv.inviter?.id ?? null;\n        break;\n      }\n    }\n    // convite de uso único some depois de usado: o que sumiu da lista foi o usado\n    if (!codigo) {\n      const sumiu = [...antes.keys()].find((k) => !agora.has(k));\n      if (sumiu) {\n        codigo = sumiu;\n        por = antes.get(sumiu).dono;\n      }\n    }\n    usos.set(guild.id, mapa(agora));\n  }\n  if (!codigo && guild.vanityURLCode) codigo = 'personalizado';\n\n  const membros = dados.de(guild.id, 'membros');\n  const anterior = membros[member.id];\n  if (anterior?.saiu && anterior.por) conta(guild.id, anterior.por).saiu = Math.max(0, conta(guild.id, anterior.por).saiu - 1); // voltou\n  const falso = Date.now() - member.user.createdTimestamp < cfg(guild.id).diasFalso * 86400e3;\n  membros[member.id] = { por, codigo, em: Date.now(), saiu: false, falso };\n  if (por && por !== member.id && !(anterior && anterior.por === por)) {\n    const c = conta(guild.id, por);\n    c.total += 1;\n    if (falso) c.falsos += 1;\n  }\n  dados.salvar();\n\n  const canalId = cfg(guild.id).canal;\n  const canal = canalId && guild.channels.cache.get(canalId);\n  if (canal?.isTextBased()) {\n    const convidou = por ? `<@${por}>` : codigo === 'personalizado' ? 'link personalizado do servidor' : 'convite desconhecido';\n    const texto = preencher(cfg(guild.id).mensagem, { usuario: `${member}`, nome: member.displayName, convidou, convites: fmt(validos(dados.ler(guild.id, 'contas', por))), codigo: codigo ?? '?' });\n    await canal.send({ content: texto + (falso ? ' ⚠️ conta nova' : ''), allowedMentions: { parse: [] } }).catch(() => {});\n  }\n}\n\nasync function aoSair(member) {\n  const m = dados.ler(member.guild.id, 'membros', member.id);\n  if (!m || m.saiu) return;\n  m.saiu = true;\n  if (m.por) conta(member.guild.id, m.por).saiu += 1;\n  dados.salvar();\n}\n\nconst convites = {\n  data: new SlashCommandBuilder()\n    .setName('convites')\n    .setDescription('Quem convidou quem')\n    .addSubcommand((s) =>\n      s\n        .setName('ver')\n        .setDescription('Convites de alguém')\n        .addUserOption((o) => o.setName('usuario').setDescription('De quem (padrão: você)'))\n    )\n    .addSubcommand((s) => s.setName('ranking').setDescription('Quem mais convidou'))\n    .addSubcommand((s) =>\n      s\n        .setName('quem')\n        .setDescription('Quem convidou uma pessoa')\n        .addUserOption((o) => o.setName('usuario').setDescription('A pessoa').setRequired(true))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('configurar')\n        .setDescription('(Equipe) Canal que avisa quem entrou e por qual convite')\n        .addChannelOption((o) => o.setName('canal').setDescription('Canal dos avisos').addChannelTypes(ChannelType.GuildText))\n        .addStringOption((o) => o.setName('mensagem').setDescription('Variáveis: {usuario} {nome} {convidou} {convites} {codigo}').setMaxLength(300))\n        .addIntegerOption((o) => o.setName('dias-falso').setDescription('Conta com menos dias que isso conta como falsa (padrão 7)').setMinValue(0).setMaxValue(90))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    if (sub === 'configurar') {\n      if (!i.member.permissions.has(PermissionFlagsBits.ManageGuild)) return responder(i, 'Só quem tem **Gerenciar servidor** pode configurar.', 'erro');\n      const c = cfg(i.guildId);\n      const canal = i.options.getChannel('canal');\n      const msg = i.options.getString('mensagem');\n      const dias = i.options.getInteger('dias-falso');\n      if (canal) c.canal = canal.id;\n      if (msg) c.mensagem = msg;\n      if (dias !== null) c.diasFalso = dias;\n      salvarAjustes();\n      const ok = await carregarConvites(i.guild);\n      return responder(\n        i,\n        `Rastreio de convites configurado${c.canal ? `: avisos em <#${c.canal}>` : ''}.${ok ? '' : '\\n⚠️ Não consigo ler os convites: me dê a permissão **Gerenciar servidor**.'}`,\n        ok ? 'sucesso' : 'aviso'\n      );\n    }\n    if (sub === 'ranking') {\n      const contas = Object.entries(dados.ler(i.guildId, 'contas') ?? {})\n        .map(([id, c]) => ({ id, v: validos(c), c }))\n        .filter((x) => x.c.total > 0)\n        .sort((a, b) => b.v - a.v || b.c.total - a.c.total)\n        .slice(0, 15);\n      if (!contas.length) return responder(i, 'Ninguém convidou ninguém ainda (desde que o bot entrou).', 'aviso');\n      const linhas = contas.map((x, k) => `**${k + 1}.** <@${x.id}> · **${fmt(x.v)}** (${x.c.total} entraram, ${x.c.saiu} saíram, ${x.c.falsos} falsos)`);\n      return i.reply({ embeds: [embed(i.guildId).setTitle('📨 Ranking de convites').setDescription(linhas.join('\\n'))], allowedMentions: { parse: [] } });\n    }\n    if (sub === 'quem') {\n      const u = i.options.getUser('usuario');\n      const m = dados.ler(i.guildId, 'membros', u.id);\n      if (!m) return responder(i, `Não sei como ${u} entrou (foi antes do bot começar a rastrear).`, 'aviso');\n      const por = m.por ? `<@${m.por}>` : m.codigo === 'personalizado' ? 'o link personalizado do servidor' : 'um convite que não consegui identificar';\n      return responder(i, `${u} entrou por ${por}${m.codigo && m.codigo !== 'personalizado' ? ` (convite \\`${m.codigo}\\`)` : ''} · <t:${Math.floor(m.em / 1000)}:R>${m.saiu ? ' · já saiu' : ''}.`, 'info');\n    }\n    const u = i.options.getUser('usuario') ?? i.user;\n    const c = dados.ler(i.guildId, 'contas', u.id);\n    return i.reply({\n      embeds: [\n        embed(i.guildId)\n          .setAuthor({ name: u.username, iconURL: u.displayAvatarURL() })\n          .setDescription(`**${fmt(validos(c))}** convite(s) válido(s)`)\n          .addFields(\n            { name: 'Entraram', value: fmt(c?.total ?? 0), inline: true },\n            { name: 'Saíram', value: fmt(c?.saiu ?? 0), inline: true },\n            { name: 'Contas falsas', value: fmt(c?.falsos ?? 0), inline: true }\n          ),\n      ],\n    });\n  },\n};\n\nexport default {\n  id: 'convites',\n  nome: 'Rastreio de convites',\n  intents: [GatewayIntentBits.GuildMembers, GatewayIntentBits.GuildInvites],\n  permissoes: [PermissionFlagsBits.ManageGuild],\n  comandos: [convites],\n  eventos: {\n    guildMemberAdd: aoEntrar,\n    guildMemberRemove: aoSair,\n    inviteCreate: (inv) => inv.guild && usos.get(inv.guild.id)?.set(inv.code, { usos: inv.uses ?? 0, dono: inv.inviterId ?? inv.inviter?.id ?? null }),\n    // convite apagado: espera um pouco (se foi de uso único, a entrada da pessoa ainda precisa dele)\n    inviteDelete: (inv) => inv.guild && setTimeout(() => usos.get(inv.guild.id)?.delete(inv.code), 15_000),\n    guildCreate: (guild) => carregarConvites(guild),\n  },\n  async aoIniciar(client) {\n    for (const guild of client.guilds.cache.values()) await carregarConvites(guild);\n  },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      const n = Object.keys(dados.ler(guild.id, 'membros') ?? {}).length;\n      return [`Avisos: ${c.canal ? `<#${c.canal}>` : 'nenhum canal'} · ${n} entrada(s) rastreada(s)`];\n    },\n  },\n};\n",
  "src/modules/destaques.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, GatewayIntentBits, Partials, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, cortar } from '../core/util.js';\n\n/**\n * Destaques (starboard): mensagem que juntar N reações ⭐ vai para o canal de destaques.\n * O contador do destaque acompanha as reações.\n */\n\nconst postados = colecao('destaques'); // guild -> msgOriginal -> idDoDestaque\nconst PADRAO = { canal: null, emoji: '⭐', minimo: 3 };\nconst cfg = (guildId) => ajustes(guildId, 'destaques', PADRAO);\n\nconst mesmoEmoji = (reacao, emoji) => reacao.emoji.id === emoji || reacao.emoji.name === emoji || reacao.emoji.toString() === emoji;\n\nasync function aoReagir(reacao) {\n  if (reacao.partial) reacao = await reacao.fetch().catch(() => null);\n  if (!reacao) return;\n  const msg = reacao.message.partial ? await reacao.message.fetch().catch(() => null) : reacao.message;\n  if (!msg?.guild) return;\n  const c = cfg(msg.guild.id);\n  if (!c.canal || msg.channelId === c.canal || msg.author?.bot || !mesmoEmoji(reacao, c.emoji)) return;\n  const canal = msg.guild.channels.cache.get(c.canal);\n  if (!canal?.isTextBased()) return;\n\n  // não vale reagir na própria mensagem\n  const usuarios = await reacao.users.fetch().catch(() => null);\n  const total = usuarios ? usuarios.filter((u) => u.id !== msg.author.id && !u.bot).size : reacao.count;\n  const jaPostado = postados.ler(msg.guild.id, msg.id);\n  const cabecalho = `${c.emoji} **${total}** · ${msg.channel}`;\n\n  if (jaPostado) {\n    const destaque = await canal.messages.fetch(jaPostado).catch(() => null);\n    if (destaque) await destaque.edit({ content: cabecalho }).catch(() => {});\n    return;\n  }\n  if (total < c.minimo) return;\n\n  const e = embed(msg.guild.id)\n    .setAuthor({ name: msg.member?.displayName ?? msg.author.username, iconURL: msg.author.displayAvatarURL() })\n    .setDescription(cortar(msg.content || '', 4000) || null)\n    .setTimestamp(msg.createdAt);\n  const imagem = msg.attachments.find((a) => a.contentType?.startsWith('image/')) ?? null;\n  if (imagem) e.setImage(imagem.url);\n  else if (msg.embeds[0]?.image?.url) e.setImage(msg.embeds[0].image.url);\n  const outros = msg.attachments.filter((a) => a !== imagem).map((a) => `[${a.name}](${a.url})`);\n  if (outros.length) e.addFields({ name: 'Anexos', value: cortar(outros.join('\\n'), 1024) });\n\n  const enviado = await canal\n    .send({\n      content: cabecalho,\n      embeds: [e],\n      components: [new ActionRowBuilder().addComponents(new ButtonBuilder().setStyle(ButtonStyle.Link).setLabel('Ver mensagem').setURL(msg.url))],\n      allowedMentions: { parse: [] },\n    })\n    .catch(() => null);\n  if (enviado) {\n    postados.de(msg.guild.id)[msg.id] = enviado.id;\n    postados.salvar();\n  }\n}\n\nconst destaques = {\n  data: new SlashCommandBuilder()\n    .setName('destaques')\n    .setDescription('Canal de destaques (mensagens com muitas ⭐)')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('configurar')\n        .setDescription('Liga os destaques')\n        .addChannelOption((o) => o.setName('canal').setDescription('Canal dos destaques').setRequired(true).addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n        .addIntegerOption((o) => o.setName('minimo').setDescription('Quantas reações para ir ao destaque (padrão 3)').setMinValue(1).setMaxValue(100))\n        .addStringOption((o) => o.setName('emoji').setDescription('Emoji que conta (padrão ⭐)').setMaxLength(60))\n    )\n    .addSubcommand((s) => s.setName('desligar').setDescription('Desliga os destaques')),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    if (i.options.getSubcommand() === 'desligar') {\n      c.canal = null;\n      salvarAjustes();\n      return responder(i, 'Destaques desligados.', 'sucesso');\n    }\n    const canal = i.options.getChannel('canal');\n    c.canal = canal.id;\n    const minimo = i.options.getInteger('minimo');\n    if (minimo) c.minimo = minimo;\n    const emoji = i.options.getString('emoji')?.trim();\n    if (emoji) {\n      const custom = /<a?:\\w+:(\\d+)>/.exec(emoji);\n      c.emoji = custom ? custom[1] : emoji;\n    }\n    salvarAjustes();\n    const mostra = /^\\d+$/.test(c.emoji) ? (i.guild.emojis.cache.get(c.emoji)?.toString() ?? c.emoji) : c.emoji;\n    return responder(i, `Destaques ligados: mensagens com **${c.minimo}** ${mostra} vão para ${canal}.`, 'sucesso');\n  },\n};\n\nexport default {\n  id: 'destaques',\n  nome: 'Destaques',\n  intents: [GatewayIntentBits.GuildMessages, GatewayIntentBits.GuildMessageReactions, GatewayIntentBits.MessageContent],\n  partials: [Partials.Message, Partials.Reaction, Partials.User, Partials.Channel],\n  comandos: [destaques],\n  eventos: { messageReactionAdd: aoReagir, messageReactionRemove: aoReagir },\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      return [c.canal ? `<#${c.canal}> · ${c.minimo} reação(ões)` : 'Desligado (`/destaques configurar`)'];\n    },\n  },\n};\n",
  "src/modules/diversao.js": "import { SlashCommandBuilder } from 'discord.js';\nimport { embed, responder, sorteio, barra } from '../core/util.js';\n\n/** Diversão: cara ou coroa, dados, bola 8, escolher e ship. Nada depende de sites de fora. */\n\nconst caracoroa = {\n  data: new SlashCommandBuilder().setName('caracoroa').setDescription('Joga uma moeda'),\n  async executar(i) {\n    const lado = Math.random() < 0.5 ? 'Cara' : 'Coroa';\n    await i.reply({ embeds: [embed(i.guildId).setDescription(`🪙 A moeda girou, girou… e deu **${lado}**!`)] });\n  },\n};\n\nconst dado = {\n  data: new SlashCommandBuilder()\n    .setName('dado')\n    .setDescription('Rola dados')\n    .addIntegerOption((o) => o.setName('lados').setDescription('Lados de cada dado (padrão 6)').setMinValue(2).setMaxValue(1000))\n    .addIntegerOption((o) => o.setName('quantidade').setDescription('Quantos dados (padrão 1)').setMinValue(1).setMaxValue(20)),\n  async executar(i) {\n    const lados = i.options.getInteger('lados') ?? 6;\n    const qtd = i.options.getInteger('quantidade') ?? 1;\n    const r = Array.from({ length: qtd }, () => sorteio(1, lados));\n    const total = r.reduce((a, b) => a + b, 0);\n    await i.reply({\n      embeds: [embed(i.guildId).setTitle(`🎲 ${qtd}d${lados}`).setDescription(qtd > 1 ? `${r.map((n) => `\\`${n}\\``).join(' + ')} = **${total}**` : `Saiu **${total}**!`)],\n    });\n  },\n};\n\nconst RESPOSTAS = [\n  'Com certeza!', 'Sem dúvida.', 'Pode apostar.', 'Sim.', 'Tudo indica que sim.', 'Parece que sim.',\n  'Pergunta de novo mais tarde.', 'Melhor não te contar agora.', 'Não consigo prever agora.', 'Concentra e pergunta de novo.',\n  'Nem pensar.', 'Minha resposta é não.', 'Minhas fontes dizem que não.', 'Acho difícil.', 'Muito duvidoso.',\n];\nconst bola8 = {\n  data: new SlashCommandBuilder()\n    .setName('8ball')\n    .setDescription('Faça uma pergunta de sim ou não para a bola 8')\n    .addStringOption((o) => o.setName('pergunta').setDescription('A pergunta').setRequired(true).setMaxLength(200)),\n  async executar(i) {\n    await i.reply({\n      embeds: [embed(i.guildId).setTitle('🎱 Bola 8').addFields({ name: 'Pergunta', value: i.options.getString('pergunta') }, { name: 'Resposta', value: RESPOSTAS[sorteio(0, RESPOSTAS.length - 1)] })],\n    });\n  },\n};\n\nconst escolher = {\n  data: new SlashCommandBuilder()\n    .setName('escolher')\n    .setDescription('O bot escolhe por você')\n    .addStringOption((o) => o.setName('opcoes').setDescription('Opções separadas por | (ex.: pizza | hambúrguer | sushi)').setRequired(true).setMaxLength(500)),\n  async executar(i) {\n    const ops = i.options.getString('opcoes').split('|').map((s) => s.trim()).filter(Boolean);\n    if (ops.length < 2) return responder(i, 'Coloque pelo menos 2 opções separadas por **|**.', 'erro');\n    await i.reply({ embeds: [embed(i.guildId).setDescription(`🤔 Entre ${ops.map((o) => `**${o}**`).join(', ')}…\\nEu escolho: **${ops[sorteio(0, ops.length - 1)]}**!`)] });\n  },\n};\n\n// o resultado é sempre o mesmo para o mesmo par (não muda a cada vez)\nfunction porcentagem(a, b) {\n  const [x, y] = [a, b].sort();\n  let h = 0;\n  for (const ch of `${x}:${y}`) h = (h * 31 + ch.charCodeAt(0)) >>> 0;\n  return h % 101;\n}\nconst ship = {\n  data: new SlashCommandBuilder()\n    .setName('ship')\n    .setDescription('Calcula a compatibilidade entre duas pessoas')\n    .addUserOption((o) => o.setName('pessoa1').setDescription('Primeira pessoa').setRequired(true))\n    .addUserOption((o) => o.setName('pessoa2').setDescription('Segunda pessoa (padrão: você)')),\n  async executar(i) {\n    const a = i.options.getUser('pessoa1');\n    const b = i.options.getUser('pessoa2') ?? i.user;\n    const p = porcentagem(a.id, b.id);\n    const nome = a.username.slice(0, Math.ceil(a.username.length / 2)) + b.username.slice(Math.floor(b.username.length / 2));\n    const frase = p >= 90 ? 'Casal perfeito! 💞' : p >= 70 ? 'Tem muito futuro! 💖' : p >= 45 ? 'Pode dar certo… 💗' : p >= 20 ? 'Melhor como amigos. 🤝' : 'Nem tenta. 💔';\n    await i.reply({\n      embeds: [embed(i.guildId).setTitle(`💘 ${a.username} + ${b.username}`).setDescription(`**${nome}**\\n${barra(p / 100, 14)} **${p}%**\\n${frase}`)],\n    });\n  },\n};\n\nexport default {\n  id: 'diversao',\n  nome: 'Diversão',\n  comandos: [caracoroa, dado, bola8, escolher, ship],\n};\n",
  "src/modules/economia.js": "import { PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, fmt, ts, sorteio, lerDuracao, duracaoTexto, cortar } from '../core/util.js';\n\n/**\n * Economia: moeda do servidor com carteira e banco, recompensa diária, trabalho,\n * transferências, apostas, ranking e uma loja de cargos.\n */\n\nconst eco = colecao('economia');\nconst PADRAO = {\n  moeda: 'moedas',\n  emoji: '🪙',\n  diario: 500,\n  trabalhoMin: 100,\n  trabalhoMax: 300,\n  trabalhoIntervalo: 3_600_000,\n  apostaMax: 0, // 0 = sem limite\n  loja: [], // { id, nome, preco, cargo, descricao }\n};\nconst cfg = (guildId) => ajustes(guildId, 'economia', PADRAO);\nconst conta = (guildId, userId) => {\n  const d = eco.de(guildId, userId);\n  d.carteira ??= 0;\n  d.banco ??= 0;\n  return d;\n};\nconst dinheiro = (c, v) => `${c.emoji} **${fmt(v)}** ${c.moeda}`;\nconst DIA = 86_400_000;\n\nconst TRABALHOS = [\n  'ajudou a organizar um evento do servidor',\n  'consertou o computador de um vizinho',\n  'entregou pizzas a noite toda',\n  'programou um site para uma loja',\n  'deu aulas particulares',\n  'editou vídeos para um criador de conteúdo',\n  'cuidou de um jardim',\n  'trabalhou de garçom num casamento',\n  'vendeu artesanato na feira',\n  'fez uma faxina caprichada',\n];\n\n/** Lê \"500\", \"1.000\", \"tudo\" ou \"metade\". */\nfunction lerQuantia(texto, maximo) {\n  const t = String(texto).trim().toLowerCase();\n  if (['tudo', 'all', 'max'].includes(t)) return maximo;\n  if (t === 'metade') return Math.floor(maximo / 2);\n  const n = Number(t.replace(/\\./g, '').replace(',', '.'));\n  return Number.isFinite(n) && n >= 1 ? Math.floor(n) : null;\n}\n\nconst opQuantia = (o, desc = 'Valor (ou \"tudo\")') => o.setName('quantia').setDescription(desc).setRequired(true).setMaxLength(15);\n\n// ---------------- comandos ----------------\nconst saldo = {\n  data: new SlashCommandBuilder()\n    .setName('saldo')\n    .setDescription('Mostra o seu dinheiro')\n    .addUserOption((o) => o.setName('usuario').setDescription('Ver de outra pessoa')),\n  async executar(i) {\n    const user = i.options.getUser('usuario') ?? i.user;\n    const c = cfg(i.guildId);\n    const d = conta(i.guildId, user.id);\n    await i.reply({\n      embeds: [\n        embed(i.guildId)\n          .setAuthor({ name: user.tag, iconURL: user.displayAvatarURL() })\n          .addFields(\n            { name: 'Carteira', value: dinheiro(c, d.carteira), inline: true },\n            { name: 'Banco', value: dinheiro(c, d.banco), inline: true },\n            { name: 'Total', value: dinheiro(c, d.carteira + d.banco), inline: true },\n          ),\n      ],\n    });\n  },\n};\n\nconst diario = {\n  data: new SlashCommandBuilder().setName('diario').setDescription('Pega a sua recompensa diária'),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const d = conta(i.guildId, i.user.id);\n    const prox = (d.diario ?? 0) + DIA;\n    if (Date.now() < prox) return responder(i, `Você já pegou hoje. Volte ${ts(prox)}.`, 'aviso');\n    d.diario = Date.now();\n    d.carteira += c.diario;\n    eco.salvar();\n    return i.reply({ embeds: [embed(i.guildId).setDescription(`🎁 Você recebeu ${dinheiro(c, c.diario)}!\\nVolte ${ts(Date.now() + DIA)} para pegar de novo.`)] });\n  },\n};\n\nconst trabalhar = {\n  data: new SlashCommandBuilder().setName('trabalhar').setDescription('Trabalha para ganhar dinheiro'),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const d = conta(i.guildId, i.user.id);\n    const prox = (d.trabalho ?? 0) + c.trabalhoIntervalo;\n    if (Date.now() < prox) return responder(i, `Você está cansado(a). Pode trabalhar de novo ${ts(prox)}.`, 'aviso');\n    const ganho = sorteio(c.trabalhoMin, c.trabalhoMax);\n    d.trabalho = Date.now();\n    d.carteira += ganho;\n    eco.salvar();\n    const oque = TRABALHOS[sorteio(0, TRABALHOS.length - 1)];\n    return i.reply({ embeds: [embed(i.guildId).setDescription(`💼 Você ${oque} e ganhou ${dinheiro(c, ganho)}.`)] });\n  },\n};\n\nconst pagar = {\n  data: new SlashCommandBuilder()\n    .setName('pagar')\n    .setDescription('Transfere dinheiro da sua carteira para alguém')\n    .addUserOption((o) => o.setName('usuario').setDescription('Para quem').setRequired(true))\n    .addStringOption((o) => opQuantia(o, 'Valor')),\n  async executar(i) {\n    const alvo = i.options.getUser('usuario');\n    if (alvo.bot || alvo.id === i.user.id) return responder(i, 'Escolha outra pessoa (que não seja bot).', 'erro');\n    const c = cfg(i.guildId);\n    const d = conta(i.guildId, i.user.id);\n    const q = lerQuantia(i.options.getString('quantia'), d.carteira);\n    if (q === null) return responder(i, 'Valor inválido.', 'erro');\n    if (!q || q > d.carteira) return responder(i, `Você só tem ${dinheiro(c, d.carteira)} na carteira.`, 'erro');\n    d.carteira -= q;\n    conta(i.guildId, alvo.id).carteira += q;\n    eco.salvar();\n    return i.reply({ embeds: [embed(i.guildId).setDescription(`💸 ${i.user} enviou ${dinheiro(c, q)} para ${alvo}.`)] });\n  },\n};\n\nfunction movimentar(de, para, titulo) {\n  return {\n    data: new SlashCommandBuilder()\n      .setName(titulo === 'depositar' ? 'depositar' : 'sacar')\n      .setDescription(titulo === 'depositar' ? 'Guarda dinheiro da carteira no banco' : 'Tira dinheiro do banco para a carteira')\n      .addStringOption((o) => opQuantia(o)),\n    async executar(i) {\n      const c = cfg(i.guildId);\n      const d = conta(i.guildId, i.user.id);\n      const q = lerQuantia(i.options.getString('quantia'), d[de]);\n      if (q === null) return responder(i, 'Valor inválido.', 'erro');\n      if (!q || q > d[de]) return responder(i, `Você só tem ${dinheiro(c, d[de])} ${de === 'carteira' ? 'na carteira' : 'no banco'}.`, 'erro');\n      d[de] -= q;\n      d[para] += q;\n      eco.salvar();\n      return responder(i, `${titulo === 'depositar' ? '🏦 Depositou' : '👛 Sacou'} ${dinheiro(c, q)}.`, 'sucesso');\n    },\n  };\n}\n\nconst apostar = {\n  data: new SlashCommandBuilder()\n    .setName('apostar')\n    .setDescription('Aposta no cara ou coroa: dobra ou perde')\n    .addStringOption((o) => opQuantia(o, 'Quanto apostar (ou \"tudo\")'))\n    .addStringOption((o) =>\n      o.setName('lado').setDescription('Cara ou coroa').setRequired(true).addChoices({ name: 'Cara', value: 'cara' }, { name: 'Coroa', value: 'coroa' })\n    ),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const d = conta(i.guildId, i.user.id);\n    const q = lerQuantia(i.options.getString('quantia'), d.carteira);\n    if (q === null) return responder(i, 'Valor inválido.', 'erro');\n    if (!q || q > d.carteira) return responder(i, `Você só tem ${dinheiro(c, d.carteira)} na carteira.`, 'erro');\n    if (c.apostaMax > 0 && q > c.apostaMax) return responder(i, `A aposta máxima é ${dinheiro(c, c.apostaMax)}.`, 'erro');\n    const lado = i.options.getString('lado');\n    const caiu = Math.random() < 0.5 ? 'cara' : 'coroa';\n    const ganhou = caiu === lado;\n    d.carteira += ganhou ? q : -q;\n    eco.salvar();\n    return i.reply({\n      embeds: [\n        embed(i.guildId)\n          .setColor(ganhou ? 0x22c55e : 0xef4444)\n          .setTitle(`🪙 Deu ${caiu}!`)\n          .setDescription(ganhou ? `Você ganhou ${dinheiro(c, q)}!` : `Você perdeu ${dinheiro(c, q)}.`)\n          .setFooter({ text: `Carteira: ${fmt(d.carteira)} ${c.moeda}` }),\n      ],\n    });\n  },\n};\n\nconst ricos = {\n  data: new SlashCommandBuilder().setName('ricos').setDescription('Ranking dos mais ricos do servidor'),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const lista = Object.entries(eco.ler(i.guildId) ?? {})\n      .map(([id, d]) => [id, (d.carteira ?? 0) + (d.banco ?? 0)])\n      .filter(([, t]) => t > 0)\n      .sort((a, b) => b[1] - a[1])\n      .slice(0, 10);\n    if (!lista.length) return responder(i, 'Ninguém tem dinheiro ainda. Use /diario!', 'info');\n    const medalhas = ['🥇', '🥈', '🥉'];\n    await i.reply({\n      embeds: [embed(i.guildId).setTitle(`💰 Mais ricos de ${i.guild.name}`).setDescription(lista.map(([id, t], n) => `${medalhas[n] ?? `**${n + 1}.**`} <@${id}> · ${dinheiro(c, t)}`).join('\\n'))],\n      allowedMentions: { parse: [] },\n    });\n  },\n};\n\nconst loja = {\n  data: new SlashCommandBuilder().setName('loja').setDescription('Mostra os cargos à venda'),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    if (!c.loja.length) return responder(i, 'A loja está vazia. A equipe pode adicionar itens com /config economia loja-adicionar.', 'info');\n    const e = embed(i.guildId).setTitle(`🛒 Loja de ${i.guild.name}`).setFooter({ text: 'Para comprar: /comprar' });\n    for (const it of c.loja.slice(0, 25)) {\n      e.addFields({ name: `${it.nome} · ${c.emoji} ${fmt(it.preco)}`, value: `${it.descricao ? `${cortar(it.descricao, 200)}\\n` : ''}Cargo: <@&${it.cargo}>` });\n    }\n    await i.reply({ embeds: [e], allowedMentions: { parse: [] } });\n  },\n};\n\nconst comprar = {\n  data: new SlashCommandBuilder()\n    .setName('comprar')\n    .setDescription('Compra um cargo da loja')\n    .addStringOption((o) => o.setName('item').setDescription('Item da loja').setRequired(true).setAutocomplete(true)),\n  async autocompletar(i) {\n    const c = cfg(i.guildId);\n    const busca = i.options.getFocused().toLowerCase();\n    await i.respond(\n      c.loja\n        .filter((it) => it.nome.toLowerCase().includes(busca))\n        .slice(0, 25)\n        .map((it) => ({ name: cortar(`${it.nome} · ${fmt(it.preco)} ${c.moeda}`, 100), value: it.id }))\n    );\n  },\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const v = i.options.getString('item');\n    const it = c.loja.find((x) => x.id === v || x.nome.toLowerCase() === v.toLowerCase());\n    if (!it) return responder(i, 'Item não encontrado. Veja a /loja.', 'erro');\n    const cargo = i.guild.roles.cache.get(it.cargo);\n    if (!cargo) return responder(i, 'O cargo deste item não existe mais. Avise a equipe.', 'erro');\n    if (i.member.roles.cache.has(cargo.id)) return responder(i, 'Você já tem esse cargo.', 'aviso');\n    if (!cargo.editable) return responder(i, 'Não consigo dar esse cargo (o meu cargo está abaixo dele). Avise a equipe.', 'erro');\n    const d = conta(i.guildId, i.user.id);\n    if (d.carteira < it.preco) return responder(i, `Faltam ${dinheiro(c, it.preco - d.carteira)} na carteira.`, 'erro');\n    d.carteira -= it.preco;\n    const ok = await i.member.roles.add(cargo, 'Comprado na loja').then(() => true, () => false);\n    if (!ok) {\n      d.carteira += it.preco; // devolve\n      return responder(i, 'Não consegui te dar o cargo, então nada foi cobrado. Avise a equipe.', 'erro');\n    }\n    eco.salvar();\n    return i.reply({ embeds: [embed(i.guildId).setDescription(`🛍️ ${i.user} comprou **${it.nome}** por ${dinheiro(c, it.preco)} e ganhou ${cargo}!`)], allowedMentions: { users: [i.user.id] } });\n  },\n};\n\nconst ecoAdmin = {\n  data: new SlashCommandBuilder()\n    .setName('eco')\n    .setDescription('Gerencia o dinheiro dos membros')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('dar')\n        .setDescription('Dá dinheiro a um membro')\n        .addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))\n        .addIntegerOption((o) => o.setName('quantia').setDescription('Valor').setRequired(true).setMinValue(1).setMaxValue(1_000_000_000))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('tirar')\n        .setDescription('Tira dinheiro da carteira de um membro')\n        .addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))\n        .addIntegerOption((o) => o.setName('quantia').setDescription('Valor').setRequired(true).setMinValue(1).setMaxValue(1_000_000_000))\n    )\n    .addSubcommand((s) => s.setName('zerar').setDescription('Zera carteira e banco de um membro').addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const sub = i.options.getSubcommand();\n    const user = i.options.getUser('usuario');\n    if (user.bot) return responder(i, 'Bots não têm conta.', 'erro');\n    const d = conta(i.guildId, user.id);\n    const q = i.options.getInteger('quantia') ?? 0;\n    if (sub === 'dar') d.carteira += q;\n    if (sub === 'tirar') d.carteira = Math.max(0, d.carteira - q);\n    if (sub === 'zerar') d.carteira = d.banco = 0;\n    eco.salvar();\n    return responder(i, `**${user.tag}**: carteira ${dinheiro(c, d.carteira)} · banco ${dinheiro(c, d.banco)}.`, 'sucesso');\n  },\n};\n\n// ---------------- /config economia ----------------\nconst config = {\n  grupo: 'economia',\n  montar: (g) =>\n    g\n      .setDescription('Moeda, recompensas e loja de cargos')\n      .addSubcommand((s) =>\n        s\n          .setName('moeda')\n          .setDescription('Nome e emoji da moeda')\n          .addStringOption((o) => o.setName('nome').setDescription('Ex.: moedas, coins, reais').setRequired(true).setMaxLength(20))\n          .addStringOption((o) => o.setName('emoji').setDescription('Ex.: 🪙').setMaxLength(60))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('ganhos')\n          .setDescription('Valores do /diario e do /trabalhar')\n          .addIntegerOption((o) => o.setName('diario').setDescription('Valor do /diario').setMinValue(0).setMaxValue(1_000_000))\n          .addIntegerOption((o) => o.setName('trabalho_min').setDescription('Mínimo do /trabalhar').setMinValue(0).setMaxValue(1_000_000))\n          .addIntegerOption((o) => o.setName('trabalho_max').setDescription('Máximo do /trabalhar').setMinValue(0).setMaxValue(1_000_000))\n          .addStringOption((o) => o.setName('intervalo').setDescription('Tempo entre /trabalhar, ex.: 1h, 30m').setMaxLength(20))\n          .addIntegerOption((o) => o.setName('aposta_max').setDescription('Aposta máxima (0 = sem limite)').setMinValue(0).setMaxValue(1_000_000_000))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('loja-adicionar')\n          .setDescription('Coloca um cargo à venda')\n          .addStringOption((o) => o.setName('nome').setDescription('Nome do item').setRequired(true).setMaxLength(60))\n          .addIntegerOption((o) => o.setName('preco').setDescription('Preço').setRequired(true).setMinValue(1).setMaxValue(1_000_000_000))\n          .addRoleOption((o) => o.setName('cargo').setDescription('Cargo que a pessoa ganha').setRequired(true))\n          .addStringOption((o) => o.setName('descricao').setDescription('Descrição').setMaxLength(200))\n      )\n      .addSubcommand((s) =>\n        s.setName('loja-remover').setDescription('Tira um item da loja').addStringOption((o) => o.setName('nome').setDescription('Nome do item').setRequired(true).setMaxLength(60))\n      ),\n  async executar(i, sub) {\n    const c = cfg(i.guildId);\n    let msg;\n    if (sub === 'moeda') {\n      c.moeda = i.options.getString('nome');\n      c.emoji = i.options.getString('emoji') || c.emoji;\n      msg = `Moeda: ${c.emoji} **${c.moeda}**.`;\n    } else if (sub === 'ganhos') {\n      const v = (n) => i.options.getInteger(n);\n      if (v('diario') !== null) c.diario = v('diario');\n      if (v('trabalho_min') !== null) c.trabalhoMin = v('trabalho_min');\n      if (v('trabalho_max') !== null) c.trabalhoMax = v('trabalho_max');\n      if (c.trabalhoMin > c.trabalhoMax) [c.trabalhoMin, c.trabalhoMax] = [c.trabalhoMax, c.trabalhoMin];\n      const iv = i.options.getString('intervalo');\n      if (iv) {\n        const ms = lerDuracao(iv);\n        if (!ms) return responder(i, 'Intervalo inválido (ex.: 1h, 30m).', 'erro');\n        c.trabalhoIntervalo = ms;\n      }\n      if (v('aposta_max') !== null) c.apostaMax = v('aposta_max');\n      msg = `/diario: **${fmt(c.diario)}** · /trabalhar: **${fmt(c.trabalhoMin)}–${fmt(c.trabalhoMax)}** a cada ${duracaoTexto(c.trabalhoIntervalo)} · aposta máxima: ${c.apostaMax ? fmt(c.apostaMax) : 'sem limite'}.`;\n    } else if (sub === 'loja-adicionar') {\n      const r = i.options.getRole('cargo');\n      if (r.managed || r.id === i.guildId) return responder(i, 'Esse cargo não pode ser vendido.', 'erro');\n      if (c.loja.length >= 25) return responder(i, 'A loja aceita no máximo 25 itens.', 'erro');\n      const nome = i.options.getString('nome');\n      if (c.loja.some((x) => x.nome.toLowerCase() === nome.toLowerCase())) return responder(i, 'Já existe um item com esse nome.', 'erro');\n      c.loja.push({ id: Date.now().toString(36), nome, preco: i.options.getInteger('preco'), cargo: r.id, descricao: i.options.getString('descricao') || '' });\n      msg = `**${nome}** está à venda.${r.editable ? '' : ' ⚠️ Suba o meu cargo acima dele, senão não consigo entregar.'}`;\n    } else if (sub === 'loja-remover') {\n      const nome = i.options.getString('nome').toLowerCase();\n      const antes = c.loja.length;\n      c.loja = c.loja.filter((x) => x.nome.toLowerCase() !== nome);\n      if (c.loja.length === antes) return responder(i, 'Não achei um item com esse nome.', 'erro');\n      msg = 'Item removido da loja.';\n    }\n    salvarAjustes();\n    return responder(i, msg, 'sucesso');\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    return [\n      `Moeda: ${c.emoji} ${c.moeda}`,\n      `/diario: ${fmt(c.diario)} · /trabalhar: ${fmt(c.trabalhoMin)}–${fmt(c.trabalhoMax)} (a cada ${duracaoTexto(c.trabalhoIntervalo)})`,\n      `Loja: ${c.loja.length} item(ns)`,\n    ];\n  },\n};\n\nexport default {\n  id: 'economia',\n  nome: 'Economia',\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  comandos: [saldo, diario, trabalhar, pagar, movimentar('carteira', 'banco', 'depositar'), movimentar('banco', 'carteira', 'sacar'), apostar, ricos, loja, comprar, ecoAdmin],\n  config,\n};\n",
  "src/modules/embeds.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, EmbedBuilder, ModalBuilder, PermissionFlagsBits, SlashCommandBuilder, TextInputBuilder, TextInputStyle } from 'discord.js';\nimport { cor, responder } from '../core/util.js';\n\n/**\n * Criador de embeds: mensagens bonitas (título, texto, cor, imagem, rodapé e botões de link)\n * sem saber programar. /embed criar abre um formulário; /embed editar muda uma já enviada.\n */\n\n// o formulário não tem lugar para o canal e os botões: guardamos aqui entre o comando e o envio\nconst rascunhos = new Map(); // userId -> { canal, botoes, mensagem?, expira }\nconst URL_OK = /^https?:\\/\\/\\S+$/i;\n\nfunction formulario(id, atual = {}) {\n  const campo = (customId, label, estilo, max, valor, obrigatorio = false) => {\n    const t = new TextInputBuilder().setCustomId(customId).setLabel(label).setStyle(estilo).setMaxLength(max).setRequired(obrigatorio);\n    if (valor) t.setValue(String(valor).slice(0, max));\n    return new ActionRowBuilder().addComponents(t);\n  };\n  return new ModalBuilder()\n    .setCustomId(id)\n    .setTitle('Criador de embed')\n    .addComponents(\n      campo('titulo', 'Título', TextInputStyle.Short, 256, atual.title),\n      campo('texto', 'Texto (aceita **negrito**, listas, links...)', TextInputStyle.Paragraph, 4000, atual.description, true),\n      campo('cor', 'Cor (ex.: #5865F2)', TextInputStyle.Short, 7, atual.color != null ? `#${atual.color.toString(16).padStart(6, '0')}` : ''),\n      campo('imagem', 'Link da imagem grande (opcional)', TextInputStyle.Short, 500, atual.image?.url),\n      campo('rodape', 'Rodapé (opcional)', TextInputStyle.Short, 2048, atual.footer?.text)\n    );\n}\n\nfunction montar(i, guildId) {\n  const f = (k) => i.fields.getTextInputValue(k).trim();\n  const erros = [];\n  const e = new EmbedBuilder().setDescription(f('texto'));\n  if (f('titulo')) e.setTitle(f('titulo'));\n  const c = f('cor');\n  if (c) {\n    const m = /^#?([0-9a-f]{6})$/i.exec(c);\n    if (m) e.setColor(parseInt(m[1], 16));\n    else erros.push('cor inválida (use #RRGGBB)');\n  }\n  if (!c || erros.length) e.setColor(cor(guildId));\n  const img = f('imagem');\n  if (img) {\n    if (URL_OK.test(img)) e.setImage(img);\n    else erros.push('o link da imagem precisa começar com https://');\n  }\n  if (f('rodape')) e.setFooter({ text: f('rodape') });\n  return { e, erros };\n}\n\nconst linhaBotoes = (botoes) =>\n  botoes.length ? [new ActionRowBuilder().addComponents(botoes.map((b) => new ButtonBuilder().setStyle(ButtonStyle.Link).setLabel(b.texto).setURL(b.link)))] : [];\n\nconst componentes = {\n  async eb(i, [acao]) {\n    if (!i.isModalSubmit()) return;\n    const r = rascunhos.get(i.user.id);\n    rascunhos.delete(i.user.id);\n    if (!r || r.expira < Date.now()) return responder(i, 'O formulário expirou. Use o comando de novo.', 'erro');\n    const { e, erros } = montar(i, i.guildId);\n    const aviso = erros.length ? `\\n⚠️ Ignorei: ${erros.join('; ')}.` : '';\n    if (acao === 'criar') {\n      const canal = i.guild.channels.cache.get(r.canal);\n      const ok = canal ? await canal.send({ embeds: [e], components: linhaBotoes(r.botoes) }).then(() => true, () => false) : false;\n      return responder(i, ok ? `Embed enviado em ${canal}.${aviso}` : 'Não consegui enviar. Confira as minhas permissões no canal.', ok ? 'sucesso' : 'erro');\n    }\n    if (acao === 'editar') {\n      const canal = i.guild.channels.cache.get(r.canal);\n      const msg = await canal?.messages.fetch(r.mensagem).catch(() => null);\n      if (!msg) return responder(i, 'Não achei mais a mensagem.', 'erro');\n      const ok = await msg.edit({ embeds: [e] }).then(() => true, () => false);\n      return responder(i, ok ? `Embed atualizado.${aviso}` : 'Não consegui editar.', ok ? 'sucesso' : 'erro');\n    }\n  },\n};\n\nconst embedCmd = {\n  data: new SlashCommandBuilder()\n    .setName('embed')\n    .setDescription('Cria mensagens bonitas (embeds)')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageMessages)\n    .addSubcommand((s) => {\n      s.setName('criar')\n        .setDescription('Abre o formulário para criar um embed')\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde enviar (padrão: aqui)').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement));\n      for (const n of [1, 2, 3]) {\n        s.addStringOption((o) => o.setName(`botao${n}`).setDescription(`Botão de link ${n}: \"Texto | https://link\" (opcional)`).setMaxLength(300));\n      }\n      return s;\n    })\n    .addSubcommand((s) =>\n      s\n        .setName('editar')\n        .setDescription('Edita um embed que eu enviei')\n        .addStringOption((o) => o.setName('mensagem').setDescription('Link da mensagem (botão direito → Copiar link)').setRequired(true))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    if (sub === 'criar') {\n      const canal = i.options.getChannel('canal') ?? i.channel;\n      const botoes = [];\n      for (const n of [1, 2, 3]) {\n        const v = i.options.getString(`botao${n}`);\n        if (!v) continue;\n        const [texto, link] = v.split('|').map((x) => x.trim());\n        if (!texto || !URL_OK.test(link ?? '')) return responder(i, `O botão ${n} precisa ser assim: **Texto | https://link**`, 'erro');\n        botoes.push({ texto: texto.slice(0, 80), link });\n      }\n      rascunhos.set(i.user.id, { canal: canal.id, botoes, expira: Date.now() + 15 * 60_000 });\n      return i.showModal(formulario('eb:criar'));\n    }\n    // editar\n    const m = /(\\d{17,20})\\/(\\d{17,20})\\/?$/.exec(i.options.getString('mensagem').trim());\n    if (!m) return responder(i, 'Cole o **link** da mensagem (botão direito na mensagem → Copiar link da mensagem).', 'erro');\n    const canal = i.guild.channels.cache.get(m[1]);\n    const msg = await canal?.messages.fetch(m[2]).catch(() => null);\n    if (!msg) return responder(i, 'Não achei essa mensagem neste servidor.', 'erro');\n    if (msg.author.id !== i.client.user.id || !msg.embeds.length) return responder(i, 'Só dá para editar embeds enviados por mim.', 'erro');\n    rascunhos.set(i.user.id, { canal: canal.id, mensagem: msg.id, botoes: [], expira: Date.now() + 15 * 60_000 });\n    return i.showModal(formulario('eb:editar', msg.embeds[0].toJSON?.() ?? msg.embeds[0].data ?? msg.embeds[0]));\n  },\n};\n\nexport default {\n  id: 'embeds',\n  nome: 'Criador de embeds',\n  comandos: [embedCmd],\n  componentes,\n};\n",
  "src/modules/enquetes.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { embed, responder, lerDuracao, barra, ts, cortar, ehStaff } from '../core/util.js';\n\n/**\n * Enquetes: até 5 opções com botões, resultado ao vivo e encerramento automático.\n * Cada pessoa vota uma vez (pode trocar o voto) ou várias, se a enquete permitir.\n */\n\nconst enquetes = colecao('enquetes');\nconst LETRAS = ['🇦', '🇧', '🇨', '🇩', '🇪'];\n\nfunction resultado(e, total) {\n  if (!total) return 'Ninguém votou.';\n  const maior = Math.max(...e.votos.map((v) => v.length));\n  const lideres = e.opcoes.filter((_, n) => e.votos[n].length === maior).map((op) => `**${op}**`);\n  return lideres.length > 1 ? `Empate entre ${lideres.join(' e ')}` : `Vencedora: ${lideres[0]}`;\n}\n\nfunction montar(guildId, e, encerrada = false) {\n  const total = e.votos.reduce((t, v) => t + v.length, 0);\n  const linhas = e.opcoes.map((op, n) => {\n    const q = e.votos[n].length;\n    const f = total ? q / total : 0;\n    return `${LETRAS[n]} **${op}**\\n${barra(f, 14)} ${Math.round(f * 100)}% (${q})`;\n  });\n  const emb = embed(guildId)\n    .setTitle(`📊 ${e.pergunta}`)\n    .setDescription(linhas.join('\\n\\n'))\n    .setFooter({ text: `${total} voto(s)${e.multipla ? ' · pode votar em mais de uma' : ''}` });\n  if (encerrada) emb.addFields({ name: 'Encerrada', value: resultado(e, total) });\n  else if (e.fim) emb.addFields({ name: 'Termina', value: ts(e.fim) });\n  const row = new ActionRowBuilder().addComponents(\n    e.opcoes.map((op, n) =>\n      new ButtonBuilder().setCustomId(`eq:votar:${n}`).setEmoji(LETRAS[n]).setLabel(cortar(op, 70)).setStyle(ButtonStyle.Secondary).setDisabled(encerrada)\n    )\n  );\n  return { embeds: [emb], components: [row] };\n}\n\nasync function encerrar(client, guildId, msgId) {\n  const e = enquetes.ler(guildId, msgId);\n  if (!e || e.encerrada) return;\n  e.encerrada = true;\n  e.encerradaEm = Date.now();\n  enquetes.salvar();\n  const canal = await client.channels.fetch(e.canal).catch(() => null);\n  const msg = await canal?.messages.fetch(msgId).catch(() => null);\n  if (msg) await msg.edit(montar(guildId, e, true)).catch(() => {});\n}\n\nconst enquete = {\n  data: new SlashCommandBuilder()\n    .setName('enquete')\n    .setDescription('Cria uma enquete')\n    .addStringOption((o) => o.setName('pergunta').setDescription('A pergunta').setRequired(true).setMaxLength(200))\n    .addStringOption((o) => o.setName('opcoes').setDescription('De 2 a 5 opções separadas por | (ex.: Sim | Não | Talvez)').setRequired(true).setMaxLength(500))\n    .addStringOption((o) => o.setName('duracao').setDescription('Encerra sozinha depois de: 30m, 1h, 2d (vazio = não encerra)').setMaxLength(20))\n    .addBooleanOption((o) => o.setName('varias').setDescription('Permitir votar em mais de uma opção')),\n  async executar(i) {\n    const opcoes = i.options\n      .getString('opcoes')\n      .split('|')\n      .map((s) => s.trim())\n      .filter(Boolean)\n      .slice(0, 5);\n    if (opcoes.length < 2) return responder(i, 'Coloque pelo menos 2 opções separadas por **|**.', 'erro');\n    const d = i.options.getString('duracao');\n    const ms = d ? lerDuracao(d) : null;\n    if (d && (!ms || ms > 30 * 86_400_000)) return responder(i, 'Duração inválida (ex.: 30m, 1h, 2d; máximo 30d).', 'erro');\n\n    const e = {\n      pergunta: i.options.getString('pergunta'),\n      opcoes,\n      votos: opcoes.map(() => []),\n      multipla: i.options.getBoolean('varias') ?? false,\n      fim: ms ? Date.now() + ms : null,\n      canal: i.channelId,\n      autor: i.user.id,\n      encerrada: false,\n    };\n    await i.reply(montar(i.guildId, e));\n    const msg = await i.fetchReply();\n    enquetes.de(i.guildId)[msg.id] = e;\n    enquetes.salvar();\n  },\n};\n\nconst encerrarCmd = {\n  data: new SlashCommandBuilder()\n    .setName('encerrarenquete')\n    .setDescription('Encerra uma enquete agora')\n    .addStringOption((o) => o.setName('mensagem').setDescription('ID ou link da mensagem da enquete').setRequired(true).setMaxLength(120)),\n  async executar(i) {\n    const id = i.options.getString('mensagem').split('/').pop().replace(/\\D/g, '');\n    const e = enquetes.ler(i.guildId, id);\n    if (!e) return responder(i, 'Enquete não encontrada.', 'erro');\n    if (e.autor !== i.user.id && !ehStaff(i.member)) return responder(i, 'Só quem criou ou a equipe pode encerrar.', 'erro');\n    await encerrar(i.client, i.guildId, id);\n    return responder(i, 'Enquete encerrada.', 'sucesso');\n  },\n};\n\nconst componentes = {\n  async eq(i, [acao, num]) {\n    if (acao !== 'votar') return;\n    const e = enquetes.ler(i.guildId, i.message.id);\n    if (!e || e.encerrada) return responder(i, 'Esta enquete já foi encerrada.', 'aviso');\n    const n = Number(num);\n    const id = i.user.id;\n    const jaVotou = e.votos[n].includes(id);\n    if (!e.multipla) e.votos = e.votos.map((v) => v.filter((x) => x !== id));\n    else e.votos[n] = e.votos[n].filter((x) => x !== id);\n    if (!jaVotou) e.votos[n].push(id);\n    enquetes.salvar();\n    await i.update(montar(i.guildId, e));\n  },\n};\n\nexport default {\n  id: 'enquetes',\n  nome: 'Enquetes',\n  comandos: [enquete, encerrarCmd],\n  componentes,\n  // confere a cada 20 s se alguma enquete passou do horário\n  aoIniciar(client) {\n    const checar = async () => {\n      const agora = Date.now();\n      for (const [guildId, lista] of Object.entries(enquetes.raiz)) {\n        for (const [msgId, e] of Object.entries(lista)) {\n          if (!e.encerrada && e.fim && e.fim <= agora) await encerrar(client, guildId, msgId);\n          // limpa enquetes encerradas há mais de 30 dias\n          if (e.encerrada && agora - (e.encerradaEm ?? e.fim ?? agora) > 30 * 86_400_000) delete lista[msgId];\n        }\n      }\n    };\n    checar();\n    setInterval(checar, 20_000);\n  },\n};\n\n",
  "src/modules/formularios.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, EmbedBuilder, ModalBuilder, PermissionFlagsBits, SlashCommandBuilder, TextInputBuilder, TextInputStyle } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, ehStaff, cortar, CORES } from '../core/util.js';\n\n/**\n * Formulários: candidatura para a equipe, parceria, denúncia...\n * Cada formulário tem até 5 perguntas (limite do Discord), um painel com botão,\n * um canal onde as respostas chegam e botões para a equipe aprovar ou recusar.\n */\n\nconst respostas = colecao('formularios_respostas'); // guild -> msgId -> { form, user, status }\nconst cfg = (guildId) => ajustes(guildId, 'formularios', { lista: {} });\nconst LIMITE_FORMS = 10;\nconst slug = (t) =>\n  t\n    .normalize('NFD')\n    .replace(/[̀-ͯ]/g, '')\n    .toLowerCase()\n    .replace(/[^a-z0-9]+/g, '-')\n    .replace(/^-|-$/g, '')\n    .slice(0, 20);\n\nconst formDe = (guildId, id) => cfg(guildId).lista[id];\n\nasync function autocompletarForm(i) {\n  const foco = slug(i.options.getFocused() || '');\n  const forms = Object.entries(cfg(i.guildId).lista);\n  await i.respond(forms.filter(([id, f]) => id.includes(foco) || slug(f.titulo).includes(foco)).slice(0, 25).map(([id, f]) => ({ name: `${f.titulo} (${f.perguntas.length} pergunta(s))`.slice(0, 100), value: id })));\n}\n\nfunction botoesEquipe(desligar = false) {\n  return [\n    new ActionRowBuilder().addComponents(\n      new ButtonBuilder().setCustomId('fm:aprovar').setLabel('Aprovar').setEmoji('✅').setStyle(ButtonStyle.Success).setDisabled(desligar),\n      new ButtonBuilder().setCustomId('fm:recusar').setLabel('Recusar').setEmoji('❌').setStyle(ButtonStyle.Danger).setDisabled(desligar)\n    ),\n  ];\n}\n\nasync function decidir(i, msg, aprovado, motivo) {\n  const r = respostas.ler(i.guildId, msg.id);\n  if (!r) return responder(i, 'Esta resposta não está mais no sistema.', 'erro');\n  if (r.status !== 'pendente') return responder(i, `Já foi ${r.status}.`, 'aviso');\n  r.status = aprovado ? 'aprovada' : 'recusada';\n  r.por = i.user.id;\n  respostas.salvar();\n  const f = formDe(i.guildId, r.form);\n  let extra = '';\n  if (aprovado && f?.cargo) {\n    const membro = await i.guild.members.fetch(r.user).catch(() => null);\n    const cargo = i.guild.roles.cache.get(f.cargo);\n    if (membro && cargo?.editable) {\n      const ok = await membro.roles.add(cargo, `Formulário ${f.titulo} aprovado`).then(() => true, () => false);\n      extra = ok ? ` · recebeu ${cargo}` : ' · (não consegui dar o cargo)';\n    } else extra = membro ? ' · (não consegui dar o cargo)' : ' · (a pessoa saiu do servidor)';\n  }\n  const e = EmbedBuilder.from(msg.embeds[0])\n    .setColor(aprovado ? CORES.sucesso : CORES.erro)\n    .addFields({ name: aprovado ? '✅ Aprovada' : '❌ Recusada', value: `por ${i.user}${extra}${motivo ? `\\n**Motivo:** ${cortar(motivo, 900)}` : ''}` });\n  await msg.edit({ embeds: [e], components: botoesEquipe(true) }).catch(() => {});\n  const user = await i.client.users.fetch(r.user).catch(() => null);\n  await user\n    ?.send({\n      embeds: [\n        embed(i.guildId)\n          .setColor(aprovado ? CORES.sucesso : CORES.erro)\n          .setDescription(`Seu formulário **${f?.titulo ?? r.form}** em **${i.guild.name}** foi **${aprovado ? 'aprovado' : 'recusado'}**.${motivo ? `\\n**Motivo:** ${motivo}` : ''}`),\n      ],\n    })\n    .catch(() => {});\n  return responder(i, `Resposta ${r.status}${extra}.`, 'sucesso');\n}\n\nconst componentes = {\n  async fm(i, [acao, alvo]) {\n    // membro clicou no botão do painel\n    if (acao === 'abrir') {\n      const f = formDe(i.guildId, alvo);\n      if (!f || !f.perguntas.length) return responder(i, 'Este formulário não está mais disponível.', 'erro');\n      if (!f.canal) return responder(i, 'Este formulário ainda não tem canal de respostas. Avise a equipe.', 'erro');\n      const pendente = Object.values(respostas.ler(i.guildId) ?? {}).some((r) => r.form === alvo && r.user === i.user.id && r.status === 'pendente');\n      if (pendente) return responder(i, 'Você já enviou este formulário e ele ainda está sendo analisado.', 'aviso');\n      return i.showModal(\n        new ModalBuilder()\n          .setCustomId(`fm:enviar:${alvo}`)\n          .setTitle(cortar(f.titulo, 45))\n          .addComponents(\n            f.perguntas.map((p, n) =>\n              new ActionRowBuilder().addComponents(\n                new TextInputBuilder()\n                  .setCustomId(`p${n}`)\n                  .setLabel(p.texto)\n                  .setStyle(p.longa ? TextInputStyle.Paragraph : TextInputStyle.Short)\n                  .setRequired(p.obrigatoria)\n                  .setMaxLength(p.longa ? 1000 : 200)\n              )\n            )\n          )\n      );\n    }\n    // respostas enviadas\n    if (acao === 'enviar' && i.isModalSubmit()) {\n      const f = formDe(i.guildId, alvo);\n      const canal = f?.canal && i.guild.channels.cache.get(f.canal);\n      if (!canal?.isTextBased()) return responder(i, 'Não achei o canal de respostas. Avise a equipe.', 'erro');\n      const e = embed(i.guildId)\n        .setAuthor({ name: `${i.user.tag} (${i.user.id})`, iconURL: i.user.displayAvatarURL() })\n        .setTitle(`📝 ${f.titulo}`)\n        .addFields(f.perguntas.map((p, n) => ({ name: cortar(p.texto, 256), value: cortar(i.fields.getTextInputValue(`p${n}`) || '—', 1024) })))\n        .addFields({ name: 'Conta criada', value: `<t:${Math.floor(i.user.createdTimestamp / 1000)}:R>`, inline: true })\n        .setTimestamp();\n      const msg = await canal.send({ content: f.mencionar ? `<@&${f.mencionar}>` : undefined, embeds: [e], components: botoesEquipe(), allowedMentions: { roles: f.mencionar ? [f.mencionar] : [] } }).catch(() => null);\n      if (!msg) return responder(i, 'Não consegui enviar. Avise a equipe para conferir as minhas permissões.', 'erro');\n      respostas.de(i.guildId)[msg.id] = { form: alvo, user: i.user.id, status: 'pendente', em: Date.now() };\n      respostas.salvar();\n      return responder(i, 'Formulário enviado! Você recebe a resposta na DM.', 'sucesso');\n    }\n    // equipe\n    if (acao === 'aprovar' || acao === 'recusar') {\n      if (!ehStaff(i.member)) return responder(i, 'Só a equipe pode decidir.', 'erro');\n      if (acao === 'aprovar') return decidir(i, i.message, true, null);\n      return i.showModal(\n        new ModalBuilder()\n          .setCustomId(`fm:motivo:${i.message.id}`)\n          .setTitle('Recusar')\n          .addComponents(new ActionRowBuilder().addComponents(new TextInputBuilder().setCustomId('motivo').setLabel('Motivo (vai na DM da pessoa)').setStyle(TextInputStyle.Paragraph).setRequired(false).setMaxLength(500)))\n      );\n    }\n    if (acao === 'motivo' && i.isModalSubmit()) {\n      if (!ehStaff(i.member)) return responder(i, 'Só a equipe pode decidir.', 'erro');\n      const msg = await i.channel.messages.fetch(alvo).catch(() => null);\n      if (!msg) return responder(i, 'Não achei a mensagem.', 'erro');\n      return decidir(i, msg, false, i.fields.getTextInputValue('motivo').trim());\n    }\n  },\n};\n\nconst formulario = {\n  data: new SlashCommandBuilder()\n    .setName('formulario')\n    .setDescription('Formulários (candidatura, parceria, denúncia...)')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('criar')\n        .setDescription('Cria um formulário')\n        .addStringOption((o) => o.setName('titulo').setDescription('Ex.: Candidatura para a equipe').setRequired(true).setMaxLength(45))\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde as respostas chegam (só a equipe deve ver)').setRequired(true).addChannelTypes(ChannelType.GuildText))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Cargo dado quando aprovado (opcional)'))\n        .addRoleOption((o) => o.setName('mencionar').setDescription('Cargo avisado a cada resposta nova (opcional)'))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('pergunta')\n        .setDescription('Adiciona uma pergunta (máximo 5)')\n        .addStringOption((o) => o.setName('formulario').setDescription('Qual formulário').setRequired(true).setAutocomplete(true))\n        .addStringOption((o) => o.setName('texto').setDescription('A pergunta (até 45 letras)').setRequired(true).setMaxLength(45))\n        .addBooleanOption((o) => o.setName('longa').setDescription('Resposta longa (vários parágrafos)?'))\n        .addBooleanOption((o) => o.setName('obrigatoria').setDescription('Obrigatória? (padrão: sim)'))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('tirar-pergunta')\n        .setDescription('Remove uma pergunta')\n        .addStringOption((o) => o.setName('formulario').setDescription('Qual formulário').setRequired(true).setAutocomplete(true))\n        .addIntegerOption((o) => o.setName('numero').setDescription('Número da pergunta (veja em /formulario lista)').setRequired(true).setMinValue(1).setMaxValue(5))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('painel')\n        .setDescription('Envia o painel com o botão para responder')\n        .addStringOption((o) => o.setName('formulario').setDescription('Qual formulário').setRequired(true).setAutocomplete(true))\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde enviar (padrão: aqui)').addChannelTypes(ChannelType.GuildText))\n        .addStringOption((o) => o.setName('mensagem').setDescription('Texto do painel').setMaxLength(1500))\n    )\n    .addSubcommand((s) => s.setName('lista').setDescription('Mostra os formulários e as perguntas'))\n    .addSubcommand((s) =>\n      s\n        .setName('apagar')\n        .setDescription('Apaga um formulário')\n        .addStringOption((o) => o.setName('formulario').setDescription('Qual formulário').setRequired(true).setAutocomplete(true))\n    ),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const sub = i.options.getSubcommand();\n    if (sub === 'lista') {\n      const forms = Object.entries(c.lista);\n      if (!forms.length) return responder(i, 'Nenhum formulário. Use `/formulario criar`.', 'aviso');\n      const e = embed(i.guildId).setTitle('📝 Formulários');\n      for (const [id, f] of forms) {\n        e.addFields({\n          name: `${f.titulo} · \\`${id}\\``,\n          value: cortar(\n            [`Respostas em <#${f.canal}>${f.cargo ? ` · aprovado ganha <@&${f.cargo}>` : ''}`, ...f.perguntas.map((p, n) => `${n + 1}. ${p.texto}${p.longa ? ' (longa)' : ''}${p.obrigatoria ? '' : ' (opcional)'}`)].join('\\n') ||\n              'Sem perguntas',\n            1024\n          ),\n        });\n      }\n      return i.reply({ embeds: [e], flags: 64 });\n    }\n    if (sub === 'criar') {\n      if (Object.keys(c.lista).length >= LIMITE_FORMS) return responder(i, `No máximo ${LIMITE_FORMS} formulários.`, 'erro');\n      const titulo = i.options.getString('titulo').trim();\n      let id = slug(titulo) || 'form';\n      while (c.lista[id]) id = `${id.slice(0, 17)}-${Math.floor(Math.random() * 90 + 10)}`;\n      const cargo = i.options.getRole('cargo');\n      if (cargo && (cargo.permissions.has(PermissionFlagsBits.Administrator) || cargo.managed)) return responder(i, 'O cargo de aprovação não pode ser de administrador nem de bot.', 'erro');\n      if (cargo && !cargo.editable) return responder(i, `Meu cargo precisa ficar acima de ${cargo}.`, 'erro');\n      c.lista[id] = { titulo, canal: i.options.getChannel('canal').id, cargo: cargo?.id ?? null, mencionar: i.options.getRole('mencionar')?.id ?? null, perguntas: [] };\n      salvarAjustes();\n      return responder(i, `Formulário **${titulo}** criado. Agora adicione as perguntas com \\`/formulario pergunta\\` (até 5) e envie o painel com \\`/formulario painel\\`.`, 'sucesso');\n    }\n    const id = i.options.getString('formulario');\n    const f = c.lista[id];\n    if (!f) return responder(i, 'Formulário não encontrado. Escolha na lista enquanto digita.', 'erro');\n    if (sub === 'pergunta') {\n      if (f.perguntas.length >= 5) return responder(i, 'O Discord aceita no máximo 5 perguntas por formulário.', 'erro');\n      f.perguntas.push({ texto: i.options.getString('texto').trim(), longa: i.options.getBoolean('longa') ?? false, obrigatoria: i.options.getBoolean('obrigatoria') ?? true });\n      salvarAjustes();\n      return responder(i, `Pergunta ${f.perguntas.length}/5 adicionada em **${f.titulo}**.`, 'sucesso');\n    }\n    if (sub === 'tirar-pergunta') {\n      const n = i.options.getInteger('numero');\n      if (n > f.perguntas.length) return responder(i, `Este formulário tem ${f.perguntas.length} pergunta(s).`, 'erro');\n      f.perguntas.splice(n - 1, 1);\n      salvarAjustes();\n      return responder(i, `Pergunta ${n} removida.`, 'sucesso');\n    }\n    if (sub === 'apagar') {\n      delete c.lista[id];\n      salvarAjustes();\n      return responder(i, `Formulário **${f.titulo}** apagado. (Painéis já enviados param de funcionar.)`, 'sucesso');\n    }\n    // painel\n    if (!f.perguntas.length) return responder(i, 'Adicione pelo menos uma pergunta antes (`/formulario pergunta`).', 'erro');\n    const canal = i.options.getChannel('canal') ?? i.channel;\n    const msg = await canal\n      .send({\n        embeds: [embed(i.guildId).setTitle(`📝 ${f.titulo}`).setDescription(i.options.getString('mensagem') || 'Clique no botão abaixo para preencher.')],\n        components: [new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId(`fm:abrir:${id}`).setLabel('Preencher').setEmoji('📝').setStyle(ButtonStyle.Primary))],\n      })\n      .catch(() => null);\n    if (!msg) return responder(i, `Não consegui enviar em ${canal}. Confira as minhas permissões.`, 'erro');\n    return responder(i, `Painel enviado em ${canal}.`, 'sucesso');\n  },\n  autocompletar: autocompletarForm,\n};\n\nexport default {\n  id: 'formularios',\n  nome: 'Formulários',\n  comandos: [formulario],\n  componentes,\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  config: {\n    resumo(guild) {\n      const n = Object.keys(cfg(guild.id).lista).length;\n      const pend = Object.values(respostas.ler(guild.id) ?? {}).filter((r) => r.status === 'pendente').length;\n      return [n ? `${n} formulário(s) · ${pend} resposta(s) esperando a equipe` : 'Nenhum (`/formulario criar`)'];\n    },\n  },\n};\n",
  "src/modules/logs.js": "import { AuditLogEvent, ChannelType, GatewayIntentBits, Partials, PermissionFlagsBits } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, cortar, foiRemovida, CORES } from '../core/util.js';\n\n/**\n * Logs: registra num canal o que acontece no servidor.\n * Tipos: mensagens (apagadas/editadas), membros (entrou, saiu, apelido, cargos),\n * moderacao (banimentos), canais (criados/apagados) e voz (entrou, saiu, trocou).\n */\n\nconst TIPOS = {\n  mensagens: 'Mensagens apagadas e editadas',\n  membros: 'Entradas, saídas, apelidos e cargos',\n  moderacao: 'Banimentos',\n  canais: 'Canais criados e apagados',\n  voz: 'Entradas e saídas de canais de voz',\n};\nconst PADRAO = { canal: null, tipos: Object.keys(TIPOS) };\nconst cfg = (guildId) => ajustes(guildId, 'logs', PADRAO);\n\nasync function enviar(guild, tipo, montar) {\n  if (!guild) return;\n  const c = cfg(guild.id);\n  if (!c.canal || !c.tipos.includes(tipo)) return;\n  const canal = guild.channels.cache.get(c.canal);\n  if (!canal?.isTextBased()) return;\n  const e = embed(guild.id).setTimestamp();\n  montar(e);\n  await canal.send({ embeds: [e], allowedMentions: { parse: [] } }).catch(() => {});\n}\n\nconst quem = (u) => (u ? `${u} (${u.tag ?? u.username ?? u.id})` : 'desconhecido');\n\nconst eventos = {\n  async messageDelete(msg) {\n    if (!msg.guild || msg.author?.bot) return;\n    if (foiRemovida(msg.id)) return; // o AutoMod já registra o que ele apaga\n    if (msg.channelId === cfg(msg.guild.id).canal) return;\n    await enviar(msg.guild, 'mensagens', (e) => {\n      e.setColor(CORES.erro)\n        .setTitle('🗑️ Mensagem apagada')\n        .addFields(\n          { name: 'Autor', value: quem(msg.author), inline: true },\n          { name: 'Canal', value: `${msg.channel}`, inline: true },\n          { name: 'Conteúdo', value: cortar(msg.content || (msg.partial ? '(mensagem antiga, fora da memória do bot)' : '(sem texto)'), 1000) },\n        );\n      if (msg.attachments?.size) e.addFields({ name: 'Anexos', value: cortar([...msg.attachments.values()].map((a) => a.name).join(', '), 1000) });\n    });\n  },\n  async messageDeleteBulk(msgs, canal) {\n    if (!canal.guild || canal.id === cfg(canal.guild.id).canal) return;\n    const linhas = [...msgs.values()]\n      .filter((m) => !m.partial && m.author && !m.author.bot)\n      .sort((a, b) => a.createdTimestamp - b.createdTimestamp)\n      .map((m) => `${m.author.tag}: ${cortar(m.content || '(sem texto)', 120)}`);\n    await enviar(canal.guild, 'mensagens', (e) => {\n      e.setColor(CORES.erro)\n        .setTitle('🧹 Mensagens apagadas em massa')\n        .addFields({ name: 'Canal', value: `${canal}`, inline: true }, { name: 'Quantidade', value: String(msgs.size), inline: true });\n      if (linhas.length) e.addFields({ name: 'Algumas delas', value: cortar(linhas.join('\\n'), 1000) });\n    });\n  },\n  async messageUpdate(antes, depois) {\n    if (!depois.guild || depois.author?.bot) return;\n    if (antes.content === depois.content || antes.partial) return; // só mudanças de texto que o bot viu\n    await enviar(depois.guild, 'mensagens', (e) =>\n      e\n        .setColor(CORES.aviso)\n        .setTitle('✏️ Mensagem editada')\n        .setURL(depois.url)\n        .addFields(\n          { name: 'Autor', value: quem(depois.author), inline: true },\n          { name: 'Canal', value: `${depois.channel}`, inline: true },\n          { name: 'Antes', value: cortar(antes.content || '(vazio)', 1000) },\n          { name: 'Depois', value: cortar(depois.content || '(vazio)', 1000) },\n        )\n    );\n  },\n  async guildMemberAdd(m) {\n    const idade = Math.floor((Date.now() - m.user.createdTimestamp) / 86_400_000);\n    await enviar(m.guild, 'membros', (e) =>\n      e\n        .setColor(CORES.sucesso)\n        .setTitle('📥 Membro entrou')\n        .setThumbnail(m.user.displayAvatarURL())\n        .addFields(\n          { name: 'Membro', value: quem(m.user) },\n          { name: 'Conta criada', value: `<t:${Math.floor(m.user.createdTimestamp / 1000)}:R>${idade < 7 ? ' ⚠️ conta nova' : ''}`, inline: true },\n          { name: 'Membros agora', value: String(m.guild.memberCount), inline: true },\n        )\n    );\n  },\n  async guildMemberRemove(m) {\n    const cargos = m.roles?.cache?.filter((r) => r.id !== m.guild.id).map((r) => `${r}`) ?? [];\n    await enviar(m.guild, 'membros', (e) =>\n      e\n        .setColor(CORES.erro)\n        .setTitle('📤 Membro saiu')\n        .setThumbnail(m.user?.displayAvatarURL?.() ?? null)\n        .addFields(\n          { name: 'Membro', value: quem(m.user) },\n          { name: 'Cargos', value: cortar(cargos.join(' ') || 'nenhum', 1000) },\n        )\n    );\n  },\n  async guildMemberUpdate(antes, depois) {\n    if (antes.partial) return;\n    if (antes.nickname !== depois.nickname) {\n      await enviar(depois.guild, 'membros', (e) =>\n        e\n          .setTitle('🏷️ Apelido alterado')\n          .addFields(\n            { name: 'Membro', value: quem(depois.user) },\n            { name: 'Antes', value: antes.nickname || '(nenhum)', inline: true },\n            { name: 'Depois', value: depois.nickname || '(nenhum)', inline: true },\n          )\n      );\n    }\n    const ganhou = depois.roles.cache.filter((r) => !antes.roles.cache.has(r.id));\n    const perdeu = antes.roles.cache.filter((r) => !depois.roles.cache.has(r.id));\n    if (ganhou.size || perdeu.size) {\n      await enviar(depois.guild, 'membros', (e) => {\n        e.setTitle('🎭 Cargos alterados').addFields({ name: 'Membro', value: quem(depois.user) });\n        if (ganhou.size) e.addFields({ name: '➕ Recebeu', value: cortar(ganhou.map((r) => `${r}`).join(' '), 1000) });\n        if (perdeu.size) e.addFields({ name: '➖ Perdeu', value: cortar(perdeu.map((r) => `${r}`).join(' '), 1000) });\n      });\n    }\n  },\n  async guildBanAdd(ban) {\n    let motivo = ban.reason;\n    let autor = null;\n    const auditoria = await ban.guild.fetchAuditLogs({ type: AuditLogEvent.MemberBanAdd, limit: 3 }).catch(() => null);\n    const entrada = auditoria?.entries.find((x) => x.target?.id === ban.user.id);\n    if (entrada) {\n      autor = entrada.executor;\n      motivo ??= entrada.reason;\n    }\n    await enviar(ban.guild, 'moderacao', (e) =>\n      e\n        .setColor(CORES.erro)\n        .setTitle('🔨 Membro banido')\n        .setThumbnail(ban.user.displayAvatarURL())\n        .addFields(\n          { name: 'Membro', value: quem(ban.user), inline: true },\n          { name: 'Por', value: autor ? quem(autor) : 'desconhecido', inline: true },\n          { name: 'Motivo', value: cortar(motivo || 'Sem motivo', 1000) },\n        )\n    );\n  },\n  async guildBanRemove(ban) {\n    await enviar(ban.guild, 'moderacao', (e) => e.setColor(CORES.sucesso).setTitle('🔓 Banimento removido').addFields({ name: 'Membro', value: quem(ban.user) }));\n  },\n  async channelCreate(ch) {\n    if (!ch.guild) return;\n    await enviar(ch.guild, 'canais', (e) => e.setColor(CORES.sucesso).setTitle('📁 Canal criado').addFields({ name: 'Canal', value: `${ch} (${ch.name})` }));\n  },\n  async channelDelete(ch) {\n    if (!ch.guild) return;\n    await enviar(ch.guild, 'canais', (e) => e.setColor(CORES.erro).setTitle('📁 Canal apagado').addFields({ name: 'Canal', value: `#${ch.name}` }));\n  },\n  async voiceStateUpdate(antes, depois) {\n    const membro = depois.member ?? antes.member;\n    if (!membro || membro.user.bot || antes.channelId === depois.channelId) return;\n    let titulo, texto;\n    if (!antes.channelId) [titulo, texto] = ['🎤 Entrou na call', `${depois.channel}`];\n    else if (!depois.channelId) [titulo, texto] = ['🔇 Saiu da call', `${antes.channel}`];\n    else [titulo, texto] = ['🔄 Trocou de call', `${antes.channel} → ${depois.channel}`];\n    await enviar(depois.guild, 'voz', (e) => e.setTitle(titulo).addFields({ name: 'Membro', value: quem(membro.user), inline: true }, { name: 'Canal', value: texto, inline: true }));\n  },\n};\n\n// ---------------- /config logs ----------------\nconst config = {\n  grupo: 'logs',\n  montar: (g) =>\n    g\n      .setDescription('Registro do que acontece no servidor')\n      .addSubcommand((s) =>\n        s.setName('canal').setDescription('Canal dos registros').addChannelOption((o) => o.setName('canal').setDescription('Vazio desliga').addChannelTypes(ChannelType.GuildText))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('tipo')\n          .setDescription('Liga ou desliga um tipo de registro')\n          .addStringOption((o) =>\n            o.setName('tipo').setDescription('Tipo').setRequired(true).addChoices(...Object.entries(TIPOS).map(([value, name]) => ({ name, value })))\n          )\n          .addBooleanOption((o) => o.setName('ligado').setDescription('Registrar?').setRequired(true))\n      ),\n  async executar(i, sub) {\n    const c = cfg(i.guildId);\n    if (sub === 'canal') {\n      const canal = i.options.getChannel('canal');\n      c.canal = canal?.id ?? null;\n      salvarAjustes();\n      return responder(i, canal ? `Os registros vão para ${canal}.` : 'Registros desligados.', 'sucesso');\n    }\n    if (sub === 'tipo') {\n      const tipo = i.options.getString('tipo');\n      const ligado = i.options.getBoolean('ligado');\n      c.tipos = c.tipos.filter((t) => t !== tipo);\n      if (ligado) c.tipos.push(tipo);\n      salvarAjustes();\n      return responder(i, `${TIPOS[tipo]}: **${ligado ? 'registrando' : 'não registrando'}**.`, 'sucesso');\n    }\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    if (!c.canal) return ['Desligado (use /config logs canal)'];\n    return [`Canal: <#${c.canal}>`, `Registrando: ${c.tipos.map((t) => t).join(', ') || 'nada'}`];\n  },\n};\n\nexport default {\n  id: 'logs',\n  nome: 'Logs',\n  intents: [\n    GatewayIntentBits.GuildMembers,\n    GatewayIntentBits.GuildMessages,\n    GatewayIntentBits.MessageContent,\n    GatewayIntentBits.GuildModeration,\n    GatewayIntentBits.GuildVoiceStates,\n  ],\n  partials: [Partials.Message, Partials.Channel, Partials.GuildMember, Partials.User],\n  permissoes: [PermissionFlagsBits.ViewAuditLog],\n  eventos,\n  config,\n};\n",
  "src/modules/minecraft.js": "import net from 'node:net';\nimport dns from 'node:dns/promises';\nimport { AttachmentBuilder, ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, cortar, fmt, CORES } from '../core/util.js';\n\n/**\n * Status de servidor de Minecraft (Java): online/offline, jogadores, versão e mensagem do servidor.\n * Consulta o servidor direto pelo protocolo do Minecraft (sem site de terceiros).\n * /minecraft status ip:jogar.exemplo.com · /minecraft painel: mensagem que se atualiza sozinha.\n */\n\nconst cfg = (guildId) => ajustes(guildId, 'minecraft', { paineis: [] }); // [{ endereco, canal, msg }]\nconst LIMITE_PAINEIS = 3;\n\n// ---------------- protocolo (Server List Ping) ----------------\nfunction varint(n) {\n  const out = [];\n  do {\n    let b = n & 0x7f;\n    n >>>= 7;\n    if (n) b |= 0x80;\n    out.push(b);\n  } while (n);\n  return Buffer.from(out);\n}\nfunction lerVarint(buf, pos) {\n  let n = 0;\n  let shift = 0;\n  for (let k = 0; k < 5; k++) {\n    if (pos + k >= buf.length) return null;\n    const b = buf[pos + k];\n    n |= (b & 0x7f) << shift;\n    if (!(b & 0x80)) return { valor: n >>> 0, tamanho: k + 1 };\n    shift += 7;\n  }\n  throw new Error('resposta inválida');\n}\nconst pacote = (...partes) => {\n  const corpo = Buffer.concat(partes);\n  return Buffer.concat([varint(corpo.length), corpo]);\n};\n\n/** \"jogar.exemplo.com\", \"1.2.3.4:25570\" -> { host, porta }, seguindo o registro SRV se houver. */\nexport async function resolverEndereco(endereco) {\n  const [host, portaTxt] = endereco.trim().toLowerCase().split(':');\n  if (!host || !/^[a-z0-9.-]+$/.test(host)) return null;\n  if (portaTxt) {\n    const porta = Number(portaTxt);\n    return porta > 0 && porta < 65536 ? { host, porta } : null;\n  }\n  if (!/^\\d+\\.\\d+\\.\\d+\\.\\d+$/.test(host)) {\n    const srv = await dns.resolveSrv(`_minecraft._tcp.${host}`).catch(() => null);\n    if (srv?.length) return { host: srv[0].name, porta: srv[0].port };\n  }\n  return { host, porta: 25565 };\n}\n\n/** Pergunta o status ao servidor. Devolve o JSON do Minecraft + latência, ou lança erro. */\nexport function consultar(host, porta, tempo = 5000) {\n  return new Promise((resolve, reject) => {\n    const inicio = Date.now();\n    const sock = net.createConnection({ host, port: porta });\n    let buf = Buffer.alloc(0);\n    let latencia = null;\n    const fim = (erro, dados) => {\n      sock.destroy();\n      clearTimeout(timer);\n      erro ? reject(erro) : resolve(dados);\n    };\n    const timer = setTimeout(() => fim(new Error('sem resposta')), tempo);\n    sock.on('error', (e) => fim(e));\n    sock.on('connect', () => {\n      latencia = Date.now() - inicio;\n      const hostBuf = Buffer.from(host, 'utf8');\n      const portaBuf = Buffer.alloc(2);\n      portaBuf.writeUInt16BE(porta);\n      // handshake (protocolo -1 = \"qualquer versão\", próximo estado 1 = status) + pedido de status\n      sock.write(pacote(varint(0), varint(-1), varint(hostBuf.length), hostBuf, portaBuf, varint(1)));\n      sock.write(pacote(varint(0)));\n    });\n    sock.on('data', (d) => {\n      buf = Buffer.concat([buf, d]);\n      try {\n        const tam = lerVarint(buf, 0);\n        if (!tam || buf.length < tam.tamanho + tam.valor) return; // ainda chegando\n        let pos = tam.tamanho;\n        const id = lerVarint(buf, pos);\n        pos += id.tamanho;\n        const len = lerVarint(buf, pos);\n        pos += len.tamanho;\n        const json = JSON.parse(buf.subarray(pos, pos + len.valor).toString('utf8'));\n        fim(null, { ...json, latencia });\n      } catch (e) {\n        fim(e);\n      }\n    });\n  });\n}\n\n/** Texto do \"motd\" (pode vir como texto ou como componentes coloridos). */\nfunction textoMotd(d) {\n  const juntar = (c) => (typeof c === 'string' ? c : (c?.text ?? '') + (c?.extra ?? []).map(juntar).join(''));\n  return juntar(d)\n    .replace(/§[0-9a-fk-or]/gi, '')\n    .trim();\n}\n\nasync function statusEmbed(guildId, endereco) {\n  const alvo = await resolverEndereco(endereco);\n  if (!alvo) return { e: embed(guildId).setColor(CORES.erro).setDescription(`❌ Endereço inválido: \\`${endereco}\\``) };\n  try {\n    const s = await consultar(alvo.host, alvo.porta);\n    const nomes = (s.players?.sample ?? []).map((p) => p.name).filter((n) => n && !n.includes('§'));\n    const e = embed(guildId)\n      .setColor(CORES.sucesso)\n      .setTitle(`🟢 ${endereco}`)\n      .setDescription(cortar(textoMotd(s.description), 500) || null)\n      .addFields(\n        { name: 'Jogadores', value: `**${fmt(s.players?.online ?? 0)}** / ${fmt(s.players?.max ?? 0)}`, inline: true },\n        { name: 'Versão', value: cortar(String(s.version?.name ?? '?').replace(/§[0-9a-fk-or]/gi, ''), 100), inline: true },\n        { name: 'Ping', value: `${s.latencia} ms`, inline: true }\n      )\n      .setFooter({ text: 'Atualizado' })\n      .setTimestamp();\n    if (nomes.length) e.addFields({ name: 'Online agora', value: cortar(nomes.slice(0, 20).join(', '), 1024) });\n    let arquivo = null;\n    const icone = /^data:image\\/png;base64,(.+)$/.exec(s.favicon ?? '');\n    if (icone) {\n      arquivo = new AttachmentBuilder(Buffer.from(icone[1], 'base64'), { name: 'icone.png' });\n      e.setThumbnail('attachment://icone.png');\n    }\n    return { e, arquivo, online: true };\n  } catch {\n    return {\n      e: embed(guildId).setColor(CORES.erro).setTitle(`🔴 ${endereco}`).setDescription('Servidor **offline** ou não respondeu.').setFooter({ text: 'Atualizado' }).setTimestamp(),\n      online: false,\n    };\n  }\n}\n\nasync function atualizarPaineis(client) {\n  for (const guild of client.guilds.cache.values()) {\n    const c = cfg(guild.id);\n    if (!c.paineis.length) continue;\n    let mudou = false;\n    for (const p of [...c.paineis]) {\n      const canal = guild.channels.cache.get(p.canal);\n      const msg = await canal?.messages.fetch(p.msg).catch(() => null);\n      if (!msg) {\n        c.paineis = c.paineis.filter((x) => x !== p); // apagaram a mensagem\n        mudou = true;\n        continue;\n      }\n      const { e } = await statusEmbed(guild.id, p.endereco);\n      await msg.edit({ embeds: [e], attachments: [] }).catch(() => {});\n    }\n    if (mudou) salvarAjustes();\n  }\n}\n\nconst minecraft = {\n  data: new SlashCommandBuilder()\n    .setName('minecraft')\n    .setDescription('Status de servidor de Minecraft (Java)')\n    .addSubcommand((s) =>\n      s\n        .setName('status')\n        .setDescription('Mostra se o servidor está online e quantos jogam')\n        .addStringOption((o) => o.setName('ip').setDescription('Ex.: jogar.exemplo.com ou 1.2.3.4:25565').setRequired(true).setMaxLength(100))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('painel')\n        .setDescription('(Equipe) Mensagem com o status que se atualiza a cada 2 minutos')\n        .addStringOption((o) => o.setName('ip').setDescription('Endereço do servidor').setRequired(true).setMaxLength(100))\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde enviar (padrão: aqui)').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n    ),\n  async executar(i) {\n    const endereco = i.options.getString('ip').trim();\n    if (i.options.getSubcommand() === 'status') {\n      await i.deferReply();\n      const { e, arquivo } = await statusEmbed(i.guildId, endereco);\n      return i.editReply({ embeds: [e], files: arquivo ? [arquivo] : [] });\n    }\n    if (!i.member.permissions.has(PermissionFlagsBits.ManageGuild)) return responder(i, 'Só quem tem **Gerenciar servidor** pode criar painéis.', 'erro');\n    const c = cfg(i.guildId);\n    if (c.paineis.length >= LIMITE_PAINEIS) return responder(i, `No máximo ${LIMITE_PAINEIS} painéis. Apague a mensagem de um para liberar.`, 'erro');\n    const canal = i.options.getChannel('canal') ?? i.channel;\n    await i.deferReply({ flags: 64 });\n    const { e } = await statusEmbed(i.guildId, endereco);\n    const msg = await canal.send({ embeds: [e] }).catch(() => null);\n    if (!msg) return i.editReply('❌ Não consegui enviar nesse canal.');\n    c.paineis.push({ endereco, canal: canal.id, msg: msg.id });\n    salvarAjustes();\n    return i.editReply(`✅ Painel criado em ${canal}. Ele se atualiza a cada 2 minutos (para tirar, apague a mensagem).`);\n  },\n};\n\nexport default {\n  id: 'minecraft',\n  nome: 'Status Minecraft',\n  comandos: [minecraft],\n  aoIniciar(client) {\n    atualizarPaineis(client).catch(() => {});\n    setInterval(() => atualizarPaineis(client).catch(() => {}), 2 * 60_000);\n  },\n  config: {\n    resumo(guild) {\n      const p = cfg(guild.id).paineis;\n      return [p.length ? p.map((x) => `\\`${x.endereco}\\` em <#${x.canal}>`).join(' · ') : 'Nenhum painel (`/minecraft painel`)'];\n    },\n  },\n};\n",
  "src/modules/moderacao.js": "import { ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, checarHierarquia, lerDuracao, duracaoTexto, cortar, CORES } from '../core/util.js';\n\n/** Moderação: banir, expulsar, castigo, advertências, limpar mensagens, trancar canais. */\n\nconst advertencias = colecao('advertencias');\nconst PADRAO = { canalLog: null, avisarDm: true, limite: 0, acaoLimite: 'castigo', duracaoLimite: 3_600_000 };\nconst cfg = (guildId) => ajustes(guildId, 'moderacao', PADRAO);\nconst MAX_CASTIGO = 28 * 86_400_000;\n\n/**\n * Registra uma ação no canal de registro da moderação.\n * Com `alvo`, mostra Membro / Por / Motivo; sem alvo (ações em canais), só Por + `extra`.\n */\nasync function registrar(guild, { acao, cor = CORES.aviso, alvo, autor, motivo, extra = [] }) {\n  const canalId = cfg(guild.id).canalLog;\n  if (!canalId) return;\n  const canal = guild.channels.cache.get(canalId);\n  if (!canal?.isTextBased()) return;\n  const campos = [];\n  if (alvo) campos.push({ name: 'Membro', value: `${alvo} (${alvo.tag ?? alvo.user?.tag ?? alvo.id})`, inline: true });\n  campos.push({ name: 'Por', value: autor ? `${autor}` : 'automático', inline: true });\n  campos.push(...extra);\n  if (motivo !== undefined) campos.push({ name: 'Motivo', value: cortar(motivo || 'Sem motivo', 1000) });\n  const e = embed(guild.id).setColor(cor).setTitle(acao).addFields(campos).setTimestamp();\n  if (alvo?.displayAvatarURL) e.setThumbnail(alvo.displayAvatarURL());\n  await canal.send({ embeds: [e], allowedMentions: { parse: [] } }).catch(() => {});\n}\n\n/** Executa uma ação do Discord; se falhar, responde com uma mensagem clara. */\nasync function tentar(i, acao, erro) {\n  try {\n    await acao();\n    return true;\n  } catch (e) {\n    console.error('[moderação]', e.message);\n    await responder(i, erro, 'erro');\n    return false;\n  }\n}\n\nasync function avisarDm(user, guild, texto) {\n  if (!cfg(guild.id).avisarDm) return;\n  await user.send({ embeds: [embed(guild.id).setTitle(guild.name).setDescription(texto)] }).catch(() => {});\n}\n\nconst motivoDe = (i) => i.options.getString('motivo') || 'Sem motivo';\nconst SEM_PERMISSAO = (perm) => `Não consegui. Confira se eu tenho a permissão **${perm}** e se o meu cargo está acima do cargo dessa pessoa.`;\nconst opMotivo = (o, obrigatorio = false) => o.setName('motivo').setDescription('Motivo').setRequired(obrigatorio).setMaxLength(500);\n\n// ---------------- comandos ----------------\nconst banir = {\n  data: new SlashCommandBuilder()\n    .setName('banir')\n    .setDescription('Bane um membro do servidor')\n    .setDefaultMemberPermissions(PermissionFlagsBits.BanMembers)\n    .addUserOption((o) => o.setName('usuario').setDescription('Quem banir').setRequired(true))\n    .addStringOption((o) => opMotivo(o))\n    .addIntegerOption((o) =>\n      o.setName('apagar').setDescription('Apagar mensagens recentes dele').addChoices(\n        { name: 'Não apagar', value: 0 },\n        { name: 'Última hora', value: 3600 },\n        { name: 'Últimas 24 horas', value: 86400 },\n        { name: 'Últimos 7 dias', value: 604800 },\n      )\n    ),\n  async executar(i) {\n    const user = i.options.getUser('usuario');\n    const membro = i.options.getMember('usuario');\n    const motivo = motivoDe(i);\n    if (membro) {\n      const erro = checarHierarquia(i.member, membro, i.guild.members.me);\n      if (erro) return responder(i, erro, 'erro');\n      if (!membro.bannable) return responder(i, SEM_PERMISSAO('Banir membros'), 'erro');\n    } else if (!i.guild.members.me.permissions.has(PermissionFlagsBits.BanMembers)) {\n      return responder(i, SEM_PERMISSAO('Banir membros'), 'erro');\n    }\n    if (membro) await avisarDm(user, i.guild, `🔨 Você foi **banido(a)**.\\n**Motivo:** ${motivo}`);\n    const ok = await tentar(\n      i,\n      () => i.guild.members.ban(user, { reason: `${motivo} (por ${i.user.tag})`, deleteMessageSeconds: i.options.getInteger('apagar') ?? 0 }),\n      SEM_PERMISSAO('Banir membros')\n    );\n    if (!ok) return;\n    await registrar(i.guild, { acao: '🔨 Banimento', cor: CORES.erro, alvo: user, autor: i.user, motivo });\n    return responder(i, `**${user.tag}** foi banido(a). Motivo: ${motivo}`, 'sucesso');\n  },\n};\n\nconst desbanir = {\n  data: new SlashCommandBuilder()\n    .setName('desbanir')\n    .setDescription('Remove o banimento de alguém')\n    .setDefaultMemberPermissions(PermissionFlagsBits.BanMembers)\n    .addStringOption((o) => o.setName('id').setDescription('ID do usuário banido').setRequired(true).setMaxLength(22))\n    .addStringOption((o) => opMotivo(o)),\n  async executar(i) {\n    const id = i.options.getString('id').replace(/\\D/g, '');\n    const motivo = motivoDe(i);\n    if (!id) return responder(i, 'Informe o ID do usuário (só números).', 'erro');\n    const ban = await i.guild.bans.fetch(id).catch(() => null);\n    if (!ban) return responder(i, 'Esse ID não está na lista de banidos.', 'erro');\n    const ok = await tentar(i, () => i.guild.bans.remove(id, `${motivo} (por ${i.user.tag})`), SEM_PERMISSAO('Banir membros'));\n    if (!ok) return;\n    await registrar(i.guild, { acao: '🔓 Banimento removido', cor: CORES.sucesso, alvo: ban.user, autor: i.user, motivo });\n    return responder(i, `**${ban.user.tag}** foi desbanido(a).`, 'sucesso');\n  },\n};\n\nconst expulsar = {\n  data: new SlashCommandBuilder()\n    .setName('expulsar')\n    .setDescription('Expulsa um membro (ele pode voltar com convite)')\n    .setDefaultMemberPermissions(PermissionFlagsBits.KickMembers)\n    .addUserOption((o) => o.setName('usuario').setDescription('Quem expulsar').setRequired(true))\n    .addStringOption((o) => opMotivo(o)),\n  async executar(i) {\n    const membro = i.options.getMember('usuario');\n    if (!membro) return responder(i, 'Esse usuário não está no servidor.', 'erro');\n    const erro = checarHierarquia(i.member, membro, i.guild.members.me);\n    if (erro) return responder(i, erro, 'erro');\n    if (!membro.kickable) return responder(i, SEM_PERMISSAO('Expulsar membros'), 'erro');\n    const motivo = motivoDe(i);\n    await avisarDm(membro.user, i.guild, `👢 Você foi **expulso(a)**.\\n**Motivo:** ${motivo}`);\n    const ok = await tentar(i, () => membro.kick(`${motivo} (por ${i.user.tag})`), SEM_PERMISSAO('Expulsar membros'));\n    if (!ok) return;\n    await registrar(i.guild, { acao: '👢 Expulsão', cor: CORES.erro, alvo: membro.user, autor: i.user, motivo });\n    return responder(i, `**${membro.user.tag}** foi expulso(a).`, 'sucesso');\n  },\n};\n\nasync function aplicarCastigo(i, membro, ms, motivo, autor = i.user) {\n  await membro.timeout(ms, `${motivo} (por ${i.user.tag})`);\n  await avisarDm(membro.user, i.guild, `🔇 Você está de **castigo** por ${duracaoTexto(ms)}.\\n**Motivo:** ${motivo}`);\n  await registrar(i.guild, {\n    acao: '🔇 Castigo',\n    alvo: membro.user,\n    autor,\n    motivo,\n    extra: [{ name: 'Duração', value: duracaoTexto(ms), inline: true }],\n  });\n}\n\nconst castigo = {\n  data: new SlashCommandBuilder()\n    .setName('castigo')\n    .setDescription('Deixa um membro sem falar por um tempo')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers)\n    .addUserOption((o) => o.setName('usuario').setDescription('Quem colocar de castigo').setRequired(true))\n    .addStringOption((o) => o.setName('duracao').setDescription('Ex.: 10m, 1h, 2d (máximo 28d)').setRequired(true).setMaxLength(20))\n    .addStringOption((o) => opMotivo(o)),\n  async executar(i) {\n    const membro = i.options.getMember('usuario');\n    if (!membro) return responder(i, 'Esse usuário não está no servidor.', 'erro');\n    const erro = checarHierarquia(i.member, membro, i.guild.members.me);\n    if (erro) return responder(i, erro, 'erro');\n    if (!membro.moderatable) return responder(i, `${SEM_PERMISSAO('Castigar membros')} (Administradores não podem ficar de castigo.)`, 'erro');\n    const ms = lerDuracao(i.options.getString('duracao'));\n    if (!ms || ms > MAX_CASTIGO) return responder(i, 'Duração inválida. Use algo como **10m**, **1h** ou **2d** (no máximo 28d).', 'erro');\n    const motivo = motivoDe(i);\n    const ok = await tentar(i, () => aplicarCastigo(i, membro, ms, motivo), SEM_PERMISSAO('Castigar membros'));\n    if (!ok) return;\n    return responder(i, `**${membro.user.tag}** está de castigo por **${duracaoTexto(ms)}**.`, 'sucesso');\n  },\n};\n\nconst removerCastigo = {\n  data: new SlashCommandBuilder()\n    .setName('removercastigo')\n    .setDescription('Tira o castigo de um membro')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers)\n    .addUserOption((o) => o.setName('usuario').setDescription('Quem liberar').setRequired(true))\n    .addStringOption((o) => opMotivo(o)),\n  async executar(i) {\n    const membro = i.options.getMember('usuario');\n    if (!membro) return responder(i, 'Esse usuário não está no servidor.', 'erro');\n    if (!membro.isCommunicationDisabled()) return responder(i, 'Esse membro não está de castigo.', 'aviso');\n    const motivo = motivoDe(i);\n    const ok = await tentar(i, () => membro.timeout(null, `${motivo} (por ${i.user.tag})`), SEM_PERMISSAO('Castigar membros'));\n    if (!ok) return;\n    await registrar(i.guild, { acao: '🔊 Castigo removido', cor: CORES.sucesso, alvo: membro.user, autor: i.user, motivo });\n    return responder(i, `O castigo de **${membro.user.tag}** foi removido.`, 'sucesso');\n  },\n};\n\nconst advertir = {\n  data: new SlashCommandBuilder()\n    .setName('advertir')\n    .setDescription('Dá uma advertência a um membro')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers)\n    .addUserOption((o) => o.setName('usuario').setDescription('Quem advertir').setRequired(true))\n    .addStringOption((o) => opMotivo(o, true)),\n  async executar(i) {\n    const membro = i.options.getMember('usuario');\n    if (!membro) return responder(i, 'Esse usuário não está no servidor.', 'erro');\n    if (membro.user.bot) return responder(i, 'Não dá para advertir bots.', 'erro');\n    const erro = checarHierarquia(i.member, membro, i.guild.members.me);\n    if (erro) return responder(i, erro, 'erro');\n    const motivo = motivoDe(i);\n\n    const g = advertencias.de(i.guildId);\n    g[membro.id] ??= [];\n    g[membro.id].push({ motivo, por: i.user.id, em: Date.now() });\n    advertencias.salvar();\n    const total = g[membro.id].length;\n\n    await avisarDm(membro.user, i.guild, `⚠️ Você recebeu uma **advertência** (${total} no total).\\n**Motivo:** ${motivo}`);\n    await registrar(i.guild, { acao: '⚠️ Advertência', alvo: membro.user, autor: i.user, motivo, extra: [{ name: 'Total', value: String(total), inline: true }] });\n\n    // punição automática ao chegar no limite\n    const c = cfg(i.guildId);\n    let extra = '';\n    if (c.limite > 0 && total >= c.limite && total % c.limite === 0) {\n      const motivoAuto = `Chegou a ${total} advertências`;\n      try {\n        if (c.acaoLimite === 'banir') {\n          await avisarDm(membro.user, i.guild, `🔨 Você foi **banido(a)**.\\n**Motivo:** ${motivoAuto}`);\n          await i.guild.members.ban(membro, { reason: motivoAuto });\n          await registrar(i.guild, { acao: '🔨 Banimento automático', cor: CORES.erro, alvo: membro.user, autor: null, motivo: motivoAuto });\n          extra = '\\nPunição automática: **banimento**.';\n        } else if (c.acaoLimite === 'expulsar') {\n          await avisarDm(membro.user, i.guild, `👢 Você foi **expulso(a)**.\\n**Motivo:** ${motivoAuto}`);\n          await membro.kick(motivoAuto);\n          await registrar(i.guild, { acao: '👢 Expulsão automática', cor: CORES.erro, alvo: membro.user, autor: null, motivo: motivoAuto });\n          extra = '\\nPunição automática: **expulsão**.';\n        } else {\n          await aplicarCastigo(i, membro, c.duracaoLimite, motivoAuto, null);\n          extra = `\\nPunição automática: **castigo** de ${duracaoTexto(c.duracaoLimite)}.`;\n        }\n      } catch {\n        extra = '\\n(Não consegui aplicar a punição automática: confira as minhas permissões.)';\n      }\n    }\n    return responder(i, `**${membro.user.tag}** recebeu uma advertência (**${total}** no total).${extra}`, 'sucesso');\n  },\n};\n\nconst verAdvertencias = {\n  data: new SlashCommandBuilder()\n    .setName('advertencias')\n    .setDescription('Mostra as advertências de um membro')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers)\n    .addUserOption((o) => o.setName('usuario').setDescription('De quem').setRequired(true)),\n  async executar(i) {\n    const user = i.options.getUser('usuario');\n    const lista = advertencias.ler(i.guildId, user.id) ?? [];\n    if (!lista.length) return responder(i, `**${user.tag}** não tem advertências.`, 'info');\n    const linhas = lista.map((a, n) => `**${n + 1}.** ${cortar(a.motivo, 120)} · por <@${a.por}> · <t:${Math.floor(a.em / 1000)}:d>`);\n    return i.reply({\n      embeds: [embed(i.guildId).setTitle(`⚠️ Advertências de ${user.tag}`).setDescription(linhas.join('\\n').slice(0, 4000)).setThumbnail(user.displayAvatarURL())],\n      flags: 64,\n    });\n  },\n};\n\nconst removerAdvertencia = {\n  data: new SlashCommandBuilder()\n    .setName('removeradvertencia')\n    .setDescription('Remove advertências de um membro')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ModerateMembers)\n    .addUserOption((o) => o.setName('usuario').setDescription('De quem').setRequired(true))\n    .addIntegerOption((o) => o.setName('numero').setDescription('Número da advertência (0 = apagar todas)').setRequired(true).setMinValue(0)),\n  async executar(i) {\n    const user = i.options.getUser('usuario');\n    const n = i.options.getInteger('numero');\n    const lista = advertencias.ler(i.guildId, user.id) ?? [];\n    if (!lista.length) return responder(i, `**${user.tag}** não tem advertências.`, 'info');\n    if (n === 0) {\n      advertencias.apagar(i.guildId, user.id);\n      return responder(i, `Todas as advertências de **${user.tag}** foram apagadas.`, 'sucesso');\n    }\n    if (n > lista.length) return responder(i, `**${user.tag}** só tem ${lista.length} advertência(s).`, 'erro');\n    lista.splice(n - 1, 1);\n    advertencias.salvar();\n    return responder(i, `Advertência ${n} de **${user.tag}** removida. Restam ${lista.length}.`, 'sucesso');\n  },\n};\n\nconst limpar = {\n  data: new SlashCommandBuilder()\n    .setName('limpar')\n    .setDescription('Apaga mensagens recentes do canal')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageMessages)\n    .addIntegerOption((o) => o.setName('quantidade').setDescription('De 1 a 100').setRequired(true).setMinValue(1).setMaxValue(100))\n    .addUserOption((o) => o.setName('usuario').setDescription('Só as mensagens desta pessoa')),\n  async executar(i) {\n    if (!i.channel?.bulkDelete) return responder(i, 'Não dá para apagar mensagens aqui.', 'erro');\n    await i.deferReply({ flags: 64 });\n    const qtd = i.options.getInteger('quantidade');\n    const alvo = i.options.getUser('usuario');\n    let msgs = await i.channel.messages.fetch({ limit: 100 });\n    msgs = msgs.filter((m) => !m.pinned && (!alvo || m.author.id === alvo.id)); // mensagens fixadas ficam\n    msgs = [...msgs.values()].slice(0, qtd);\n    if (!msgs.length) return i.editReply('Não achei mensagens para apagar.');\n    const apagadas = await i.channel.bulkDelete(msgs, true).catch(() => null);\n    if (!apagadas) return i.editReply('❌ Não consegui apagar. Preciso da permissão **Gerenciar mensagens** neste canal.');\n    const n = apagadas.size;\n    await registrar(i.guild, {\n      acao: '🧹 Mensagens apagadas',\n      autor: i.user,\n      extra: [\n        { name: 'Canal', value: `${i.channel}`, inline: true },\n        { name: 'Quantidade', value: String(n), inline: true },\n        ...(alvo ? [{ name: 'Só de', value: `${alvo} (${alvo.tag})`, inline: true }] : []),\n      ],\n    });\n    return i.editReply(`🧹 ${n} mensagem(ns) apagada(s).${n < msgs.length ? ' (O Discord não deixa apagar em massa mensagens com mais de 14 dias.)' : ''}`);\n  },\n};\n\nconst opCanal = (o) => o.setName('canal').setDescription('Padrão: este canal').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement);\n\nconst trancar = {\n  data: new SlashCommandBuilder()\n    .setName('trancar')\n    .setDescription('Impede os membros de falar no canal')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageChannels)\n    .addChannelOption(opCanal)\n    .addStringOption((o) => opMotivo(o)),\n  async executar(i) {\n    const canal = i.options.getChannel('canal') ?? i.channel;\n    const ok = await tentar(\n      i,\n      () => canal.permissionOverwrites.edit(i.guild.roles.everyone, { SendMessages: false, SendMessagesInThreads: false, CreatePublicThreads: false }),\n      'Não consegui trancar. Preciso das permissões **Gerenciar canais** e **Gerenciar cargos** nesse canal.'\n    );\n    if (!ok) return;\n    const motivo = motivoDe(i);\n    await canal.send({ embeds: [embed(i.guildId).setDescription(`🔒 Canal trancado pela moderação.${motivo !== 'Sem motivo' ? `\\n**Motivo:** ${motivo}` : ''}`)] }).catch(() => {});\n    await registrar(i.guild, { acao: '🔒 Canal trancado', autor: i.user, motivo, extra: [{ name: 'Canal', value: `${canal}`, inline: true }] });\n    return responder(i, `${canal} foi trancado.`, 'sucesso');\n  },\n};\n\nconst destrancar = {\n  data: new SlashCommandBuilder()\n    .setName('destrancar')\n    .setDescription('Libera o canal de novo')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageChannels)\n    .addChannelOption(opCanal),\n  async executar(i) {\n    const canal = i.options.getChannel('canal') ?? i.channel;\n    const ok = await tentar(\n      i,\n      () => canal.permissionOverwrites.edit(i.guild.roles.everyone, { SendMessages: null, SendMessagesInThreads: null, CreatePublicThreads: null }),\n      'Não consegui liberar. Preciso das permissões **Gerenciar canais** e **Gerenciar cargos** nesse canal.'\n    );\n    if (!ok) return;\n    await canal.send({ embeds: [embed(i.guildId).setDescription('🔓 Canal liberado.')] }).catch(() => {});\n    await registrar(i.guild, { acao: '🔓 Canal liberado', cor: CORES.sucesso, autor: i.user, extra: [{ name: 'Canal', value: `${canal}`, inline: true }] });\n    return responder(i, `${canal} foi liberado.`, 'sucesso');\n  },\n};\n\nconst lentidao = {\n  data: new SlashCommandBuilder()\n    .setName('lentidao')\n    .setDescription('Define o modo lento do canal')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageChannels)\n    .addIntegerOption((o) => o.setName('segundos').setDescription('0 desliga (máximo 21600 = 6h)').setRequired(true).setMinValue(0).setMaxValue(21600))\n    .addChannelOption(opCanal),\n  async executar(i) {\n    const canal = i.options.getChannel('canal') ?? i.channel;\n    const s = i.options.getInteger('segundos');\n    const ok = await tentar(i, () => canal.setRateLimitPerUser(s, `por ${i.user.tag}`), 'Não consegui mudar o modo lento. Preciso da permissão **Gerenciar canais** nesse canal.');\n    if (!ok) return;\n    await registrar(i.guild, {\n      acao: '🐢 Modo lento',\n      autor: i.user,\n      extra: [\n        { name: 'Canal', value: `${canal}`, inline: true },\n        { name: 'Intervalo', value: s ? duracaoTexto(s * 1000) : 'desligado', inline: true },\n      ],\n    });\n    return responder(i, s ? `Modo lento de ${canal}: **${duracaoTexto(s * 1000)}** entre mensagens.` : `Modo lento de ${canal} desligado.`, 'sucesso');\n  },\n};\n\n// ---------------- /config moderacao ----------------\nconst config = {\n  grupo: 'moderacao',\n  montar: (g) =>\n    g\n      .setDescription('Moderação: canal de registro, aviso na DM e punição automática')\n      .addSubcommand((s) =>\n        s.setName('canal').setDescription('Canal onde as punições ficam registradas').addChannelOption((o) =>\n          o.setName('canal').setDescription('Deixe vazio para desligar').addChannelTypes(ChannelType.GuildText)\n        )\n      )\n      .addSubcommand((s) =>\n        s.setName('dm').setDescription('Avisar o membro na DM quando for punido').addBooleanOption((o) => o.setName('ativar').setDescription('Ligar ou desligar').setRequired(true))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('limite')\n          .setDescription('Punição automática ao juntar advertências')\n          .addIntegerOption((o) => o.setName('advertencias').setDescription('Quantas advertências (0 desliga)').setRequired(true).setMinValue(0).setMaxValue(20))\n          .addStringOption((o) =>\n            o.setName('acao').setDescription('O que fazer').addChoices(\n              { name: 'Castigo', value: 'castigo' },\n              { name: 'Expulsar', value: 'expulsar' },\n              { name: 'Banir', value: 'banir' },\n            )\n          )\n          .addStringOption((o) => o.setName('duracao').setDescription('Duração do castigo, ex.: 1h (padrão 1h)').setMaxLength(20))\n      ),\n  async executar(i, sub) {\n    const c = cfg(i.guildId);\n    if (sub === 'canal') {\n      const canal = i.options.getChannel('canal');\n      c.canalLog = canal?.id ?? null;\n      salvarAjustes();\n      return responder(i, canal ? `As punições serão registradas em ${canal}.` : 'Registro de punições desligado.', 'sucesso');\n    }\n    if (sub === 'dm') {\n      c.avisarDm = i.options.getBoolean('ativar');\n      salvarAjustes();\n      return responder(i, c.avisarDm ? 'Os membros serão avisados na DM.' : 'Aviso na DM desligado.', 'sucesso');\n    }\n    if (sub === 'limite') {\n      c.limite = i.options.getInteger('advertencias');\n      c.acaoLimite = i.options.getString('acao') ?? c.acaoLimite;\n      const d = i.options.getString('duracao');\n      if (d) {\n        const ms = lerDuracao(d);\n        if (!ms || ms > MAX_CASTIGO) return responder(i, 'Duração inválida (ex.: 30m, 1h, 1d; máximo 28d).', 'erro');\n        c.duracaoLimite = ms;\n      }\n      salvarAjustes();\n      return responder(\n        i,\n        c.limite ? `A cada **${c.limite}** advertências: **${c.acaoLimite}**${c.acaoLimite === 'castigo' ? ` de ${duracaoTexto(c.duracaoLimite)}` : ''}.` : 'Punição automática desligada.',\n        'sucesso'\n      );\n    }\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    return [\n      `Registro: ${c.canalLog ? `<#${c.canalLog}>` : 'desligado'}`,\n      `Aviso na DM: ${c.avisarDm ? 'sim' : 'não'}`,\n      `Punição automática: ${c.limite ? `a cada ${c.limite} advertências → ${c.acaoLimite}` : 'desligada'}`,\n    ];\n  },\n};\n\nexport default {\n  id: 'moderacao',\n  nome: 'Moderação',\n  comandos: [banir, desbanir, expulsar, castigo, removerCastigo, advertir, verAdvertencias, removerAdvertencia, limpar, trancar, destrancar, lentidao],\n  permissoes: [\n    PermissionFlagsBits.BanMembers,\n    PermissionFlagsBits.KickMembers,\n    PermissionFlagsBits.ModerateMembers,\n    PermissionFlagsBits.ManageMessages,\n    PermissionFlagsBits.ManageChannels,\n    PermissionFlagsBits.ManageRoles,\n  ],\n  config,\n};\n",
  "src/modules/niveis.js": "import { ChannelType, GatewayIntentBits, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, preencher, barra, fmt, sorteio, foiRemovida } from '../core/util.js';\n\n/**\n * Níveis: membros ganham XP conversando (com intervalo para não valer flood),\n * sobem de nível, recebem cargos de recompensa e aparecem no ranking.\n */\n\nconst xpDb = colecao('niveis');\nconst PADRAO = {\n  ativo: true,\n  xpMin: 15,\n  xpMax: 25,\n  intervalo: 60, // segundos entre mensagens que valem XP\n  canal: null, // null = avisa no mesmo canal\n  mensagem: '🎉 {usuario} subiu para o **nível {nivel}**!',\n  recompensas: {}, // nivel -> cargoId\n  ignorados: [],\n};\nconst cfg = (guildId) => ajustes(guildId, 'niveis', PADRAO);\n\n/** XP para passar do nível n para o n+1. */\nexport const xpDoNivel = (n) => 5 * n * n + 50 * n + 100;\n\nfunction nivelDe(xpTotal) {\n  let nivel = 0;\n  let resto = xpTotal;\n  while (resto >= xpDoNivel(nivel)) {\n    resto -= xpDoNivel(nivel);\n    nivel++;\n  }\n  return { nivel, atual: resto, precisa: xpDoNivel(nivel) };\n}\n\nfunction ranking(guildId) {\n  const g = xpDb.ler(guildId) ?? {};\n  return Object.entries(g)\n    .filter(([, d]) => d.xp > 0)\n    .sort((a, b) => b[1].xp - a[1].xp);\n}\n\nasync function darRecompensas(member, nivel) {\n  const c = cfg(member.guild.id);\n  const cargos = Object.entries(c.recompensas)\n    .filter(([n]) => Number(n) <= nivel)\n    .map(([, id]) => id)\n    .filter((id) => !member.roles.cache.has(id) && member.guild.roles.cache.get(id)?.editable);\n  if (cargos.length) await member.roles.add(cargos, `Recompensa de nível ${nivel}`).catch(() => {});\n}\n\nasync function aoMensagem(msg) {\n  if (!msg.inGuild() || msg.author.bot || !msg.member) return;\n  if (foiRemovida(msg.id)) return; // apagada pelo AutoMod: não vale XP\n  const c = cfg(msg.guildId);\n  if (!c.ativo || c.ignorados.includes(msg.channelId)) return;\n\n  const d = xpDb.de(msg.guildId, msg.author.id);\n  const agora = Date.now();\n  if (d.ultima && agora - d.ultima < c.intervalo * 1000) return;\n  d.ultima = agora;\n  const antes = nivelDe(d.xp ?? 0).nivel;\n  d.xp = (d.xp ?? 0) + sorteio(c.xpMin, c.xpMax);\n  xpDb.salvar();\n\n  const depois = nivelDe(d.xp).nivel;\n  if (depois <= antes) return;\n  await darRecompensas(msg.member, depois);\n  const canal = (c.canal && msg.guild.channels.cache.get(c.canal)) || msg.channel;\n  const texto = preencher(c.mensagem, { usuario: `${msg.author}`, nome: msg.member.displayName, nivel: depois, servidor: msg.guild.name });\n  await canal.send({ content: texto, allowedMentions: { users: [msg.author.id] } }).catch(() => {});\n}\n\n// ---------------- comandos ----------------\nconst rank = {\n  data: new SlashCommandBuilder()\n    .setName('rank')\n    .setDescription('Mostra o seu nível e XP')\n    .addUserOption((o) => o.setName('usuario').setDescription('Ver de outra pessoa')),\n  async executar(i) {\n    const user = i.options.getUser('usuario') ?? i.user;\n    const xp = xpDb.ler(i.guildId, user.id)?.xp ?? 0;\n    const { nivel, atual, precisa } = nivelDe(xp);\n    const pos = ranking(i.guildId).findIndex(([id]) => id === user.id) + 1;\n    await i.reply({\n      embeds: [\n        embed(i.guildId)\n          .setAuthor({ name: user.tag, iconURL: user.displayAvatarURL() })\n          .setThumbnail(user.displayAvatarURL({ size: 256 }))\n          .addFields(\n            { name: 'Nível', value: `**${nivel}**`, inline: true },\n            { name: 'Posição', value: pos ? `#${pos}` : '—', inline: true },\n            { name: 'XP total', value: fmt(xp), inline: true },\n            { name: `Progresso para o nível ${nivel + 1}`, value: `${barra(atual / precisa, 14)}  ${fmt(atual)}/${fmt(precisa)} XP` },\n          ),\n      ],\n    });\n  },\n};\n\nconst top = {\n  data: new SlashCommandBuilder().setName('top').setDescription('Ranking de XP do servidor'),\n  async executar(i) {\n    const lista = ranking(i.guildId).slice(0, 10);\n    if (!lista.length) return responder(i, 'Ninguém ganhou XP ainda. Converse no chat!', 'info');\n    const medalhas = ['🥇', '🥈', '🥉'];\n    const linhas = lista.map(([id, d], n) => `${medalhas[n] ?? `**${n + 1}.**`} <@${id}> · nível **${nivelDe(d.xp).nivel}** · ${fmt(d.xp)} XP`);\n    const minha = ranking(i.guildId).findIndex(([id]) => id === i.user.id) + 1;\n    await i.reply({\n      embeds: [\n        embed(i.guildId)\n          .setTitle(`🏆 Ranking de ${i.guild.name}`)\n          .setDescription(linhas.join('\\n'))\n          .setFooter({ text: minha ? `Sua posição: #${minha}` : 'Você ainda não tem XP' }),\n      ],\n      allowedMentions: { parse: [] },\n    });\n  },\n};\n\nconst xpAdmin = {\n  data: new SlashCommandBuilder()\n    .setName('xp')\n    .setDescription('Gerencia o XP dos membros')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('dar')\n        .setDescription('Dá XP a um membro')\n        .addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))\n        .addIntegerOption((o) => o.setName('quantidade').setDescription('Quanto XP').setRequired(true).setMinValue(1).setMaxValue(1_000_000))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('tirar')\n        .setDescription('Tira XP de um membro')\n        .addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))\n        .addIntegerOption((o) => o.setName('quantidade').setDescription('Quanto XP').setRequired(true).setMinValue(1).setMaxValue(1_000_000))\n    )\n    .addSubcommand((s) => s.setName('zerar').setDescription('Zera o XP de um membro').addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    const user = i.options.getUser('usuario');\n    if (user.bot) return responder(i, 'Bots não têm XP.', 'erro');\n    const d = xpDb.de(i.guildId, user.id);\n    const q = i.options.getInteger('quantidade') ?? 0;\n    if (sub === 'dar') d.xp = (d.xp ?? 0) + q;\n    if (sub === 'tirar') d.xp = Math.max(0, (d.xp ?? 0) - q);\n    if (sub === 'zerar') d.xp = 0;\n    xpDb.salvar();\n    const { nivel } = nivelDe(d.xp);\n    const membro = i.options.getMember('usuario');\n    if (membro) await darRecompensas(membro, nivel);\n    return responder(i, `**${user.tag}** agora tem **${fmt(d.xp)} XP** (nível ${nivel}).`, 'sucesso');\n  },\n};\n\n// ---------------- /config niveis ----------------\nconst config = {\n  grupo: 'niveis',\n  montar: (g) =>\n    g\n      .setDescription('Sistema de níveis e XP')\n      .addSubcommand((s) => s.setName('ativar').setDescription('Liga ou desliga o ganho de XP').addBooleanOption((o) => o.setName('ligado').setDescription('Ligado?').setRequired(true)))\n      .addSubcommand((s) =>\n        s\n          .setName('aviso')\n          .setDescription('Onde e como avisar quando alguém sobe de nível')\n          .addChannelOption((o) => o.setName('canal').setDescription('Vazio = no mesmo canal da mensagem').addChannelTypes(ChannelType.GuildText))\n          .addStringOption((o) => o.setName('mensagem').setDescription('Variáveis: {usuario} {nome} {nivel} {servidor}').setMaxLength(500))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('recompensa')\n          .setDescription('Cargo ganho ao chegar num nível (sem cargo = remove a recompensa)')\n          .addIntegerOption((o) => o.setName('nivel').setDescription('Nível').setRequired(true).setMinValue(1).setMaxValue(500))\n          .addRoleOption((o) => o.setName('cargo').setDescription('Cargo'))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('xp')\n          .setDescription('XP por mensagem e intervalo')\n          .addIntegerOption((o) => o.setName('minimo').setDescription('XP mínimo por mensagem').setRequired(true).setMinValue(1).setMaxValue(500))\n          .addIntegerOption((o) => o.setName('maximo').setDescription('XP máximo por mensagem').setRequired(true).setMinValue(1).setMaxValue(500))\n          .addIntegerOption((o) => o.setName('intervalo').setDescription('Segundos entre mensagens que valem XP (padrão 60)').setMinValue(0).setMaxValue(3600))\n      )\n      .addSubcommand((s) =>\n        s\n          .setName('ignorar-canal')\n          .setDescription('Canal onde não se ganha XP (usar de novo remove)')\n          .addChannelOption((o) => o.setName('canal').setDescription('Canal').setRequired(true).addChannelTypes(ChannelType.GuildText))\n      ),\n  async executar(i, sub) {\n    const c = cfg(i.guildId);\n    let msg;\n    if (sub === 'ativar') {\n      c.ativo = i.options.getBoolean('ligado');\n      msg = c.ativo ? 'Ganho de XP ligado.' : 'Ganho de XP desligado.';\n    } else if (sub === 'aviso') {\n      const canal = i.options.getChannel('canal');\n      c.canal = canal?.id ?? null;\n      const m = i.options.getString('mensagem');\n      if (m) c.mensagem = m;\n      msg = `Aviso de nível ${canal ? `em ${canal}` : 'no mesmo canal da mensagem'}.`;\n    } else if (sub === 'recompensa') {\n      const n = i.options.getInteger('nivel');\n      const r = i.options.getRole('cargo');\n      if (r) {\n        if (r.managed || r.id === i.guildId) return responder(i, 'Esse cargo não pode ser dado.', 'erro');\n        c.recompensas[n] = r.id;\n        msg = `Ao chegar no nível **${n}**, o membro ganha ${r}.${r.editable ? '' : ' ⚠️ Suba o meu cargo acima dele para funcionar.'}`;\n      } else {\n        delete c.recompensas[n];\n        msg = `Recompensa do nível ${n} removida.`;\n      }\n    } else if (sub === 'xp') {\n      const min = i.options.getInteger('minimo');\n      const max = i.options.getInteger('maximo');\n      if (min > max) return responder(i, 'O mínimo não pode ser maior que o máximo.', 'erro');\n      c.xpMin = min;\n      c.xpMax = max;\n      const iv = i.options.getInteger('intervalo');\n      if (iv !== null) c.intervalo = iv;\n      msg = `Cada mensagem vale de **${min} a ${max} XP**, uma vez a cada **${c.intervalo}s**.`;\n    } else if (sub === 'ignorar-canal') {\n      const ch = i.options.getChannel('canal');\n      const idx = c.ignorados.indexOf(ch.id);\n      if (idx >= 0) c.ignorados.splice(idx, 1);\n      else c.ignorados.push(ch.id);\n      msg = idx >= 0 ? `${ch} volta a dar XP.` : `${ch} não dá mais XP.`;\n    }\n    salvarAjustes();\n    return responder(i, msg, 'sucesso');\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    const rec = Object.entries(c.recompensas).sort((a, b) => a[0] - b[0]).map(([n, r]) => `${n}: <@&${r}>`);\n    return [\n      `Ganho de XP: ${c.ativo ? `ligado (${c.xpMin}–${c.xpMax} XP a cada ${c.intervalo}s)` : 'desligado'}`,\n      `Aviso: ${c.canal ? `<#${c.canal}>` : 'no mesmo canal'}`,\n      `Recompensas: ${rec.length ? rec.join(' · ') : 'nenhuma'}`,\n    ];\n  },\n};\n\nexport default {\n  id: 'niveis',\n  nome: 'Níveis',\n  intents: [GatewayIntentBits.GuildMessages],\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  comandos: [rank, top, xpAdmin],\n  eventos: { messageCreate: aoMensagem },\n  config,\n};\n",
  "src/modules/reputacao.js": "import { PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, fmt, duracaoTexto, cortar } from '../core/util.js';\n\n/**\n * Reputação: cada membro pode dar +1 de reputação para alguém uma vez por dia.\n * Ranking e cargos de recompensa por pontos.\n */\n\nconst rep = colecao('reputacao'); // guild -> user -> { pontos, deuEm }\nconst cfg = (guildId) => ajustes(guildId, 'reputacao', { recompensas: {} }); // pontos -> cargoId\nconst ESPERA = 24 * 3600e3;\nconst de = (guildId, userId) => {\n  const d = rep.de(guildId, userId);\n  d.pontos ??= 0;\n  return d;\n};\n\nasync function darRecompensas(guild, userId, pontos) {\n  const r = cfg(guild.id).recompensas;\n  const ganhar = Object.entries(r).filter(([p]) => pontos >= Number(p)).map(([, cargo]) => cargo);\n  if (!ganhar.length) return [];\n  const membro = await guild.members.fetch(userId).catch(() => null);\n  if (!membro) return [];\n  const novos = [];\n  for (const id of ganhar) {\n    const cargo = guild.roles.cache.get(id);\n    if (cargo?.editable && !membro.roles.cache.has(id)) {\n      const ok = await membro.roles.add(cargo, 'Recompensa de reputação').then(() => true, () => false);\n      if (ok) novos.push(cargo);\n    }\n  }\n  return novos;\n}\n\nconst repCmd = {\n  data: new SlashCommandBuilder()\n    .setName('rep')\n    .setDescription('Dá +1 de reputação para alguém (1 vez por dia)')\n    .addUserOption((o) => o.setName('usuario').setDescription('Quem merece').setRequired(true))\n    .addStringOption((o) => o.setName('motivo').setDescription('Por quê? (opcional)').setMaxLength(150)),\n  async executar(i) {\n    const alvo = i.options.getUser('usuario');\n    if (alvo.id === i.user.id) return responder(i, 'Não dá para dar reputação para você mesmo.', 'erro');\n    if (alvo.bot) return responder(i, 'Bots não têm reputação.', 'erro');\n    const eu = de(i.guildId, i.user.id);\n    const falta = (eu.deuEm ?? 0) + ESPERA - Date.now();\n    if (falta > 0) return responder(i, `Você já deu reputação hoje. Volte em **${duracaoTexto(falta)}**.`, 'aviso');\n    const ele = de(i.guildId, alvo.id);\n    ele.pontos += 1;\n    eu.deuEm = Date.now();\n    rep.salvar();\n    const novos = await darRecompensas(i.guild, alvo.id, ele.pontos);\n    const motivo = i.options.getString('motivo');\n    return i.reply({\n      embeds: [\n        embed(i.guildId).setDescription(\n          `👍 ${i.user} deu **+1 de reputação** para ${alvo}! Agora: **${fmt(ele.pontos)}**${motivo ? `\\n> ${cortar(motivo, 150)}` : ''}${novos.length ? `\\n🎁 Ganhou ${novos.join(', ')}` : ''}`\n        ),\n      ],\n      allowedMentions: { users: [alvo.id] },\n    });\n  },\n};\n\nconst reputacao = {\n  data: new SlashCommandBuilder()\n    .setName('reputacao')\n    .setDescription('Reputação dos membros')\n    .addSubcommand((s) =>\n      s\n        .setName('ver')\n        .setDescription('Pontos de alguém')\n        .addUserOption((o) => o.setName('usuario').setDescription('De quem (padrão: você)'))\n    )\n    .addSubcommand((s) => s.setName('ranking').setDescription('Os mais bem falados do servidor'))\n    .addSubcommand((s) =>\n      s\n        .setName('recompensa')\n        .setDescription('(Equipe) Cargo ao chegar em X pontos (sem cargo = remove)')\n        .addIntegerOption((o) => o.setName('pontos').setDescription('Pontos necessários').setRequired(true).setMinValue(1).setMaxValue(100000))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Cargo dado (deixe vazio para remover)'))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('definir')\n        .setDescription('(Equipe) Muda os pontos de alguém')\n        .addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true))\n        .addIntegerOption((o) => o.setName('pontos').setDescription('Novo total').setRequired(true).setMinValue(0).setMaxValue(1000000))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    if (sub === 'recompensa' || sub === 'definir') {\n      if (!i.member.permissions.has(PermissionFlagsBits.ManageGuild)) return responder(i, 'Só quem tem **Gerenciar servidor** pode fazer isso.', 'erro');\n      if (sub === 'definir') {\n        const u = i.options.getUser('usuario');\n        if (u.bot) return responder(i, 'Bots não têm reputação.', 'erro');\n        de(i.guildId, u.id).pontos = i.options.getInteger('pontos');\n        rep.salvar();\n        await darRecompensas(i.guild, u.id, i.options.getInteger('pontos'));\n        return responder(i, `${u} agora tem **${fmt(i.options.getInteger('pontos'))}** de reputação.`, 'sucesso');\n      }\n      const c = cfg(i.guildId);\n      const pontos = String(i.options.getInteger('pontos'));\n      const cargo = i.options.getRole('cargo');\n      if (!cargo) {\n        delete c.recompensas[pontos];\n        salvarAjustes();\n        return responder(i, `Recompensa de ${pontos} pontos removida.`, 'sucesso');\n      }\n      if (cargo.managed || cargo.permissions.has(PermissionFlagsBits.Administrator)) return responder(i, 'Escolha um cargo comum (sem administrador).', 'erro');\n      if (!cargo.editable) return responder(i, `Meu cargo precisa ficar acima de ${cargo}.`, 'erro');\n      c.recompensas[pontos] = cargo.id;\n      salvarAjustes();\n      return responder(i, `Com **${pontos}** de reputação a pessoa ganha ${cargo}.`, 'sucesso');\n    }\n    if (sub === 'ranking') {\n      const top = Object.entries(rep.ler(i.guildId) ?? {})\n        .filter(([, d]) => d.pontos > 0)\n        .sort((a, b) => b[1].pontos - a[1].pontos)\n        .slice(0, 15);\n      if (!top.length) return responder(i, 'Ninguém tem reputação ainda. Use `/rep`.', 'aviso');\n      return i.reply({\n        embeds: [embed(i.guildId).setTitle('👍 Ranking de reputação').setDescription(top.map(([id, d], k) => `**${k + 1}.** <@${id}> · ${fmt(d.pontos)}`).join('\\n'))],\n        allowedMentions: { parse: [] },\n      });\n    }\n    const u = i.options.getUser('usuario') ?? i.user;\n    const d = rep.ler(i.guildId, u.id);\n    const r = Object.entries(cfg(i.guildId).recompensas).sort((a, b) => Number(a[0]) - Number(b[0]));\n    const proxima = r.find(([p]) => Number(p) > (d?.pontos ?? 0));\n    return responder(i, `${u} tem **${fmt(d?.pontos ?? 0)}** de reputação.${proxima ? ` Próxima recompensa: <@&${proxima[1]}> com ${proxima[0]}.` : ''}`, 'info');\n  },\n};\n\nexport default {\n  id: 'reputacao',\n  nome: 'Reputação',\n  comandos: [repCmd, reputacao],\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  config: {\n    resumo(guild) {\n      const r = Object.entries(cfg(guild.id).recompensas);\n      return [r.length ? `Recompensas: ${r.map(([p, c]) => `${p} → <@&${c}>`).join(' · ')}` : 'Sem recompensas (`/reputacao recompensa`)'];\n    },\n  },\n};\n",
  "src/modules/sorteios.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { embed, responder, lerDuracao, ts, cortar, CORES } from '../core/util.js';\n\n/**\n * Sorteios: botão para participar, cargo obrigatório opcional, sorteio automático\n * no fim, encerrar antes da hora e sortear de novo.\n */\n\nconst sorteios = colecao('sorteios');\n\nfunction painel(guildId, s, encerrado = false) {\n  const e = embed(guildId)\n    .setTitle(`🎉 ${s.premio}`)\n    .setDescription(\n      [\n        s.descricao ? `${s.descricao}\\n` : '',\n        encerrado ? `Encerrado ${ts(s.fim)}` : `Termina ${ts(s.fim)} (${ts(s.fim, 'f')})`,\n        `Vencedores: **${s.vencedores}**`,\n        s.cargo ? `Só participa quem tem <@&${s.cargo}>` : '',\n        `Criado por <@${s.autor}>`,\n      ]\n        .filter(Boolean)\n        .join('\\n')\n    )\n    .setFooter({ text: `${s.participantes.length} participante(s)` });\n  if (encerrado) {\n    e.setColor(CORES.sucesso).addFields({ name: 'Ganhador(es)', value: s.ganhadores?.length ? s.ganhadores.map((id) => `<@${id}>`).join(', ') : 'Ninguém participou.' });\n  }\n  const row = new ActionRowBuilder().addComponents(\n    new ButtonBuilder()\n      .setCustomId('sr:entrar')\n      .setLabel(encerrado ? 'Encerrado' : `Participar (${s.participantes.length})`)\n      .setEmoji('🎉')\n      .setStyle(ButtonStyle.Primary)\n      .setDisabled(encerrado)\n  );\n  return { embeds: [e], components: [row] };\n}\n\nfunction sortear(lista, n) {\n  const copia = [...lista];\n  const out = [];\n  while (copia.length && out.length < n) out.push(copia.splice(Math.floor(Math.random() * copia.length), 1)[0]);\n  return out;\n}\n\nasync function finalizar(client, guildId, msgId) {\n  const s = sorteios.ler(guildId, msgId);\n  if (!s || s.encerrado) return;\n  s.encerrado = true;\n  s.fim = Math.min(s.fim, Date.now());\n  s.ganhadores = sortear(s.participantes, s.vencedores);\n  sorteios.salvar();\n  const canal = await client.channels.fetch(s.canal).catch(() => null);\n  const msg = await canal?.messages.fetch(msgId).catch(() => null);\n  if (msg) await msg.edit(painel(guildId, s, true)).catch(() => {});\n  if (canal?.isTextBased()) {\n    const texto = s.ganhadores.length\n      ? `🎉 Parabéns ${s.ganhadores.map((id) => `<@${id}>`).join(', ')}! Você${s.ganhadores.length > 1 ? 's ganharam' : ' ganhou'} **${s.premio}**!`\n      : `😕 O sorteio de **${s.premio}** terminou sem participantes.`;\n    await canal.send({ content: texto, reply: msg ? { messageReference: msg.id, failIfNotExists: false } : undefined, allowedMentions: { users: s.ganhadores } }).catch(() => {});\n  }\n}\n\nconst idDaMensagem = (t) => String(t).split('/').pop().replace(/\\D/g, '');\n\nconst sorteio = {\n  data: new SlashCommandBuilder()\n    .setName('sorteio')\n    .setDescription('Sorteios')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('criar')\n        .setDescription('Cria um sorteio')\n        .addStringOption((o) => o.setName('premio').setDescription('O que será sorteado').setRequired(true).setMaxLength(200))\n        .addStringOption((o) => o.setName('duracao').setDescription('Ex.: 1h, 2d, 1w').setRequired(true).setMaxLength(20))\n        .addIntegerOption((o) => o.setName('vencedores').setDescription('Quantos ganham (padrão 1)').setMinValue(1).setMaxValue(20))\n        .addChannelOption((o) => o.setName('canal').setDescription('Padrão: este canal').addChannelTypes(ChannelType.GuildText, ChannelType.GuildAnnouncement))\n        .addRoleOption((o) => o.setName('cargo').setDescription('Só quem tem este cargo participa'))\n        .addStringOption((o) => o.setName('descricao').setDescription('Detalhes do sorteio').setMaxLength(1000))\n    )\n    .addSubcommand((s) =>\n      s.setName('encerrar').setDescription('Encerra um sorteio agora').addStringOption((o) => o.setName('mensagem').setDescription('ID ou link da mensagem do sorteio').setRequired(true).setMaxLength(120))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('refazer')\n        .setDescription('Sorteia ganhadores de novo num sorteio encerrado')\n        .addStringOption((o) => o.setName('mensagem').setDescription('ID ou link da mensagem do sorteio').setRequired(true).setMaxLength(120))\n        .addIntegerOption((o) => o.setName('vencedores').setDescription('Quantos (padrão: o mesmo número)').setMinValue(1).setMaxValue(20))\n    )\n    .addSubcommand((s) => s.setName('lista').setDescription('Sorteios em andamento')),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    if (sub === 'criar') {\n      const ms = lerDuracao(i.options.getString('duracao'));\n      if (!ms || ms < 10_000 || ms > 60 * 86_400_000) return responder(i, 'Duração inválida (ex.: 1h, 2d; entre 10s e 60d).', 'erro');\n      const canal = i.options.getChannel('canal') ?? i.channel;\n      const s = {\n        premio: i.options.getString('premio'),\n        descricao: i.options.getString('descricao') || '',\n        vencedores: i.options.getInteger('vencedores') ?? 1,\n        cargo: i.options.getRole('cargo')?.id ?? null,\n        fim: Date.now() + ms,\n        canal: canal.id,\n        autor: i.user.id,\n        participantes: [],\n        encerrado: false,\n      };\n      const msg = await canal.send(painel(i.guildId, s)).catch(() => null);\n      if (!msg) return responder(i, `Não consegui enviar mensagens em ${canal}. Confira as minhas permissões.`, 'erro');\n      sorteios.de(i.guildId)[msg.id] = s;\n      sorteios.salvar();\n      return responder(i, `Sorteio criado em ${canal}! Termina ${ts(s.fim)}.`, 'sucesso');\n    }\n    if (sub === 'encerrar') {\n      const id = idDaMensagem(i.options.getString('mensagem'));\n      const s = sorteios.ler(i.guildId, id);\n      if (!s) return responder(i, 'Sorteio não encontrado.', 'erro');\n      if (s.encerrado) return responder(i, 'Esse sorteio já terminou. Use /sorteio refazer para sortear de novo.', 'aviso');\n      await i.deferReply({ flags: 64 });\n      await finalizar(i.client, i.guildId, id);\n      return i.editReply('✅ Sorteio encerrado.');\n    }\n    if (sub === 'refazer') {\n      const id = idDaMensagem(i.options.getString('mensagem'));\n      const s = sorteios.ler(i.guildId, id);\n      if (!s) return responder(i, 'Sorteio não encontrado.', 'erro');\n      if (!s.encerrado) return responder(i, 'Esse sorteio ainda não terminou.', 'aviso');\n      const n = i.options.getInteger('vencedores') ?? s.vencedores;\n      const novos = sortear(s.participantes, n);\n      if (!novos.length) return responder(i, 'Ninguém participou desse sorteio.', 'aviso');\n      return i.reply({ content: `🎉 Novo sorteio de **${cortar(s.premio, 100)}**: ${novos.map((u) => `<@${u}>`).join(', ')}!`, allowedMentions: { users: novos } });\n    }\n    if (sub === 'lista') {\n      const ativos = Object.entries(sorteios.ler(i.guildId) ?? {}).filter(([, s]) => !s.encerrado);\n      if (!ativos.length) return responder(i, 'Nenhum sorteio em andamento.', 'info');\n      const linhas = ativos.map(([id, s]) => `**${cortar(s.premio, 60)}** · <#${s.canal}> · termina ${ts(s.fim)} · ${s.participantes.length} participante(s) · ID \\`${id}\\``);\n      return i.reply({ embeds: [embed(i.guildId).setTitle('🎉 Sorteios em andamento').setDescription(linhas.join('\\n'))], flags: 64 });\n    }\n  },\n};\n\nconst componentes = {\n  async sr(i, [acao]) {\n    if (acao !== 'entrar') return;\n    const s = sorteios.ler(i.guildId, i.message.id);\n    if (!s || s.encerrado) return responder(i, 'Este sorteio já terminou.', 'aviso');\n    if (s.cargo && !i.member.roles.cache.has(s.cargo)) return responder(i, `Para participar você precisa do cargo <@&${s.cargo}>.`, 'erro');\n    const idx = s.participantes.indexOf(i.user.id);\n    if (idx >= 0) s.participantes.splice(idx, 1);\n    else s.participantes.push(i.user.id);\n    sorteios.salvar();\n    await i.update(painel(i.guildId, s));\n    await i.followUp({ content: idx >= 0 ? 'Você saiu do sorteio.' : '🎉 Você está participando! Clique de novo para sair.', flags: 64 });\n  },\n};\n\nexport default {\n  id: 'sorteios',\n  nome: 'Sorteios',\n  comandos: [sorteio],\n  componentes,\n  aoIniciar(client) {\n    const checar = async () => {\n      const agora = Date.now();\n      for (const [guildId, lista] of Object.entries(sorteios.raiz)) {\n        for (const [msgId, s] of Object.entries(lista)) {\n          if (!s.encerrado && s.fim <= agora) await finalizar(client, guildId, msgId);\n          if (s.encerrado && agora - s.fim > 30 * 86_400_000) delete lista[msgId];\n        }\n      }\n    };\n    checar();\n    setInterval(checar, 15_000);\n  },\n};\n",
  "src/modules/sugestoes.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, EmbedBuilder, MessageFlags, ModalBuilder, PermissionFlagsBits, SlashCommandBuilder, TextInputBuilder, TextInputStyle } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, ehStaff, cortar, CORES } from '../core/util.js';\n\n/**\n * Sugestões: /sugerir publica a ideia num canal com votos 👍/👎.\n * A equipe aprova ou recusa pelos botões, com um motivo.\n */\n\nconst sugestoes = colecao('sugestoes');\nconst PADRAO = { canal: null, contador: 0 };\nconst cfg = (guildId) => ajustes(guildId, 'sugestoes', PADRAO);\n\nfunction botoes(s, encerrada = false) {\n  return [\n    new ActionRowBuilder().addComponents(\n      new ButtonBuilder().setCustomId('sg:sim').setLabel(String(s.sim.length)).setEmoji('👍').setStyle(ButtonStyle.Success).setDisabled(encerrada),\n      new ButtonBuilder().setCustomId('sg:nao').setLabel(String(s.nao.length)).setEmoji('👎').setStyle(ButtonStyle.Danger).setDisabled(encerrada),\n      new ButtonBuilder().setCustomId('sg:analisar').setLabel('Equipe').setEmoji('🛡️').setStyle(ButtonStyle.Secondary).setDisabled(encerrada)\n    ),\n  ];\n}\n\nconst sugerir = {\n  data: new SlashCommandBuilder()\n    .setName('sugerir')\n    .setDescription('Envia uma sugestão para o servidor')\n    .addStringOption((o) => o.setName('sugestao').setDescription('A sua ideia').setRequired(true).setMinLength(10).setMaxLength(1500)),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const canal = c.canal && i.guild.channels.cache.get(c.canal);\n    if (!canal?.isTextBased()) return responder(i, 'O canal de sugestões não foi configurado. Avise a equipe (/config sugestoes canal).', 'erro');\n    c.contador += 1;\n    salvarAjustes();\n    const s = { autor: i.user.id, sim: [], nao: [], status: 'aberta', numero: c.contador, canal: canal.id };\n    const e = embed(i.guildId)\n      .setAuthor({ name: i.member.displayName, iconURL: i.user.displayAvatarURL() })\n      .setTitle(`💡 Sugestão #${s.numero}`)\n      .setDescription(i.options.getString('sugestao'))\n      .addFields({ name: 'Situação', value: '🕐 Em votação' })\n      .setTimestamp();\n    const msg = await canal.send({ embeds: [e], components: botoes(s) }).catch(() => null);\n    if (!msg) return responder(i, `Não consegui enviar em ${canal}. Avise a equipe para conferir as minhas permissões.`, 'erro');\n    sugestoes.de(i.guildId)[msg.id] = s;\n    sugestoes.salvar();\n    if (msg.channel.threads) await msg.startThread({ name: `Sugestão #${s.numero}`, autoArchiveDuration: 4320 }).catch(() => {});\n    return responder(i, `Sugestão enviada em ${canal}!`, 'sucesso');\n  },\n};\n\nasync function decidir(i, msgId, aprovada, motivo) {\n  if (!ehStaff(i.member)) return responder(i, 'Só a equipe pode decidir sugestões.', 'erro');\n  const s = sugestoes.ler(i.guildId, msgId);\n  if (!s) return responder(i, 'Sugestão não encontrada.', 'erro');\n  if (s.status !== 'aberta') return responder(i, `Esta sugestão já foi ${s.status}.`, 'aviso');\n  const canal = s.canal ? await i.client.channels.fetch(s.canal).catch(() => null) : i.channel;\n  const msg = await canal?.messages.fetch(msgId).catch(() => null);\n  if (!msg) return responder(i, 'Não achei a mensagem da sugestão.', 'erro');\n  s.status = aprovada ? 'aprovada' : 'recusada';\n  sugestoes.salvar();\n  const e = EmbedBuilder.from(msg.embeds[0])\n    .setColor(aprovada ? CORES.sucesso : CORES.erro)\n    .setFields(\n      { name: 'Situação', value: aprovada ? `✅ Aprovada por ${i.user}` : `❌ Recusada por ${i.user}` },\n      ...(motivo ? [{ name: 'Motivo', value: cortar(motivo, 1000) }] : []),\n      { name: 'Votos', value: `👍 ${s.sim.length} · 👎 ${s.nao.length}` },\n    );\n  await msg.edit({ embeds: [e], components: botoes(s, true) });\n  const autor = await i.client.users.fetch(s.autor).catch(() => null);\n  await autor\n    ?.send({ embeds: [embed(i.guildId).setDescription(`Sua sugestão #${s.numero} em **${i.guild.name}** foi **${s.status}**.${motivo ? `\\n**Motivo:** ${motivo}` : ''}`)] })\n    .catch(() => {});\n  return responder(i, `Sugestão #${s.numero} ${s.status}.`, 'sucesso');\n}\n\nconst componentes = {\n  async sg(i, [acao, msgId, decisao]) {\n    // formulário da equipe enviado\n    if (i.isModalSubmit() && acao === 'motivo') {\n      return decidir(i, msgId, decisao === 'aprovar', i.fields.getTextInputValue('motivo').trim());\n    }\n    // botões da equipe (resposta escondida com Aprovar/Recusar)\n    if (acao === 'aprovar' || acao === 'recusar') {\n      if (!ehStaff(i.member)) return responder(i, 'Só a equipe pode decidir sugestões.', 'erro');\n      return i.showModal(\n        new ModalBuilder()\n          .setCustomId(`sg:motivo:${msgId}:${acao}`)\n          .setTitle(acao === 'aprovar' ? 'Aprovar sugestão' : 'Recusar sugestão')\n          .addComponents(\n            new ActionRowBuilder().addComponents(\n              new TextInputBuilder().setCustomId('motivo').setLabel('Motivo (opcional)').setStyle(TextInputStyle.Paragraph).setRequired(false).setMaxLength(500)\n            )\n          )\n      );\n    }\n\n    const s = sugestoes.ler(i.guildId, i.message?.id);\n    if (!s) return responder(i, 'Esta sugestão não está mais no sistema.', 'erro');\n    if (s.status !== 'aberta') return responder(i, 'A votação desta sugestão já terminou.', 'aviso');\n\n    if (acao === 'analisar') {\n      if (!ehStaff(i.member)) return responder(i, 'Só a equipe pode usar este botão.', 'erro');\n      return i.reply({\n        content: 'O que fazer com esta sugestão?',\n        components: [\n          new ActionRowBuilder().addComponents(\n            new ButtonBuilder().setCustomId(`sg:aprovar:${i.message.id}`).setLabel('Aprovar').setEmoji('✅').setStyle(ButtonStyle.Success),\n            new ButtonBuilder().setCustomId(`sg:recusar:${i.message.id}`).setLabel('Recusar').setEmoji('❌').setStyle(ButtonStyle.Danger)\n          ),\n        ],\n        flags: MessageFlags.Ephemeral,\n      });\n    }\n\n    // voto: clicar de novo tira o voto; votar no outro lado troca\n    const lado = acao === 'sim' ? 'sim' : 'nao';\n    const outro = lado === 'sim' ? 'nao' : 'sim';\n    const id = i.user.id;\n    s[outro] = s[outro].filter((x) => x !== id);\n    if (s[lado].includes(id)) s[lado] = s[lado].filter((x) => x !== id);\n    else s[lado].push(id);\n    sugestoes.salvar();\n    return i.update({ components: botoes(s) });\n  },\n};\n\nconst config = {\n  grupo: 'sugestoes',\n  montar: (g) =>\n    g\n      .setDescription('Canal de sugestões')\n      .addSubcommand((s) =>\n        s.setName('canal').setDescription('Canal onde as sugestões são publicadas').addChannelOption((o) => o.setName('canal').setDescription('Vazio desliga').addChannelTypes(ChannelType.GuildText))\n      ),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    const ch = i.options.getChannel('canal');\n    c.canal = ch?.id ?? null;\n    salvarAjustes();\n    return responder(i, ch ? `Sugestões serão publicadas em ${ch}.` : 'Sugestões desligadas.', 'sucesso');\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    return [`Canal: ${c.canal ? `<#${c.canal}>` : 'não definido'}`, `Sugestões enviadas: ${c.contador}`];\n  },\n};\n\nexport default {\n  id: 'sugestoes',\n  nome: 'Sugestões',\n  comandos: [sugerir],\n  componentes,\n  permissoes: [PermissionFlagsBits.CreatePublicThreads],\n  config,\n};\n",
  "src/modules/tickets.js": "import {\n  ActionRowBuilder,\n  AttachmentBuilder,\n  ButtonBuilder,\n  ButtonStyle,\n  ChannelType,\n  EmbedBuilder,\n  GatewayIntentBits,\n  MessageFlags,\n  PermissionFlagsBits,\n  SlashCommandBuilder,\n} from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { ajustes, salvarAjustes, embed, responder, preencher, ehStaff, cortar, CORES, sinais } from '../core/util.js';\n\n/**\n * Tickets: painel com botão \"Abrir ticket\", canal privado para cada atendimento,\n * botões de fechar e assumir, e histórico (.txt) enviado ao canal de registro ao fechar.\n */\n\nconst tickets = colecao('tickets');\nconst PADRAO = {\n  categoria: null,\n  equipe: null, // se vazio, usa o cargo de /config staff\n  registro: null,\n  mensagem: 'Olá {usuario}! Descreva o que você precisa com o máximo de detalhes. A equipe já foi avisada e responde assim que puder.',\n  limite: 1,\n  contador: 0,\n};\nconst cfg = (guildId) => ajustes(guildId, 'tickets', PADRAO);\nconst dados = (guildId, canalId) => tickets.ler(guildId, canalId);\n\nfunction podeAtender(member) {\n  const c = cfg(member.guild.id);\n  return ehStaff(member) || (c.equipe && member.roles.cache.has(c.equipe));\n}\n\nconst botoesTicket = (assumido = false) =>\n  new ActionRowBuilder().addComponents(\n    new ButtonBuilder().setCustomId('tk:fechar').setLabel('Fechar').setEmoji('🔒').setStyle(ButtonStyle.Danger),\n    new ButtonBuilder().setCustomId('tk:assumir').setLabel(assumido ? 'Assumido' : 'Assumir').setEmoji('🙋').setStyle(ButtonStyle.Primary).setDisabled(assumido)\n  );\n\n// ---------------- abrir ----------------\nasync function abrir(i) {\n  await i.deferReply({ flags: MessageFlags.Ephemeral });\n  const c = cfg(i.guildId);\n  const g = tickets.de(i.guildId);\n\n  // limpa registros de canais que não existem mais\n  for (const canalId of Object.keys(g)) if (!i.guild.channels.cache.has(canalId)) delete g[canalId];\n  const abertos = Object.entries(g).filter(([, t]) => t.dono === i.user.id);\n  if (abertos.length >= c.limite) {\n    return i.editReply(`Você já tem ${abertos.length > 1 ? 'tickets abertos' : 'um ticket aberto'}: ${abertos.map(([id]) => `<#${id}>`).join(' ')}`);\n  }\n\n  const me = i.guild.members.me;\n  if (!me.permissions.has(PermissionFlagsBits.ManageChannels)) return i.editReply('❌ Preciso da permissão **Gerenciar canais** para abrir tickets.');\n\n  const equipe = c.equipe || ajustes(i.guildId, 'geral').staff;\n  const categoria = c.categoria && i.guild.channels.cache.get(c.categoria)?.type === ChannelType.GuildCategory ? c.categoria : null;\n\n  // o Discord só deixa o bot liberar no canal permissões que ele mesmo tem\n  const soAsMinhas = (lista) => lista.filter((p) => me.permissions.has(p));\n  const permitir = soAsMinhas([\n    PermissionFlagsBits.ViewChannel,\n    PermissionFlagsBits.SendMessages,\n    PermissionFlagsBits.ReadMessageHistory,\n    PermissionFlagsBits.AttachFiles,\n    PermissionFlagsBits.EmbedLinks,\n  ]);\n  const sobrescritas = [\n    { id: i.guild.roles.everyone.id, deny: [PermissionFlagsBits.ViewChannel] },\n    { id: i.user.id, allow: permitir },\n    { id: me.id, allow: soAsMinhas([...permitir, PermissionFlagsBits.ManageChannels, PermissionFlagsBits.ManageMessages]) },\n  ];\n  if (equipe && i.guild.roles.cache.has(equipe)) sobrescritas.push({ id: equipe, allow: soAsMinhas([...permitir, PermissionFlagsBits.ManageMessages]) });\n\n  const numero = String(c.contador + 1).padStart(4, '0');\n  let canal;\n  try {\n    canal = await i.guild.channels.create({\n      name: `ticket-${numero}`,\n      type: ChannelType.GuildText,\n      parent: categoria ?? undefined,\n      topic: `Ticket de ${i.user.tag} (${i.user.id})`,\n      permissionOverwrites: sobrescritas,\n      reason: `Ticket aberto por ${i.user.tag}`,\n    });\n  } catch (e) {\n    console.error('[tickets] não consegui criar o canal:', e.message);\n    return i.editReply('❌ Não consegui criar o canal do ticket. Avise a equipe: confira as minhas permissões (Gerenciar canais e Gerenciar cargos) e se a categoria não está cheia (máximo de 50 canais).');\n  }\n  c.contador += 1;\n  salvarAjustes();\n\n  g[canal.id] = { dono: i.user.id, numero, aberto: Date.now(), assumido: null };\n  tickets.salvar();\n\n  const e = embed(i.guildId)\n    .setTitle(`🎫 Ticket #${numero}`)\n    .setDescription(preencher(c.mensagem, { usuario: `${i.user}`, nome: i.member.displayName, servidor: i.guild.name }))\n    .addFields({ name: 'Aberto por', value: `${i.user}`, inline: true }, { name: 'Atendente', value: 'aguardando', inline: true })\n    .setTimestamp();\n  await canal.send({\n    content: `${i.user}${equipe ? ` <@&${equipe}>` : ''}`,\n    embeds: [e],\n    components: [botoesTicket()],\n    allowedMentions: { users: [i.user.id], roles: equipe ? [equipe] : [] },\n  });\n  return i.editReply(`✅ Ticket aberto: ${canal}`);\n}\n\n// ---------------- fechar ----------------\nasync function historico(canal) {\n  const todas = [];\n  let antes;\n  for (let n = 0; n < 10; n++) {\n    const lote = await canal.messages.fetch({ limit: 100, before: antes }).catch(() => null);\n    if (!lote?.size) break;\n    todas.push(...lote.values());\n    antes = lote.last().id;\n    if (lote.size < 100) break;\n  }\n  todas.reverse();\n  const data = (d) => d.toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });\n  return todas\n    .map((m) => {\n      const anexos = m.attachments.size ? ` [anexos: ${[...m.attachments.values()].map((a) => a.url).join(' ')}]` : '';\n      const embeds = !m.content && m.embeds.length ? ` [embed: ${m.embeds[0].title ?? m.embeds[0].description?.slice(0, 80) ?? ''}]` : '';\n      return `[${data(m.createdAt)}] ${m.author.tag}: ${m.content}${anexos}${embeds}`;\n    })\n    .join('\\n');\n}\n\nconst fechando = new Set(); // evita fechar o mesmo ticket duas vezes ao mesmo tempo\n\nasync function fechar(i, motivo = 'Sem motivo') {\n  const t = dados(i.guildId, i.channelId);\n  if (!t) return responder(i, 'Isto não é um ticket.', 'erro');\n  if (i.user.id !== t.dono && !podeAtender(i.member)) return responder(i, 'Só quem abriu ou a equipe pode fechar.', 'erro');\n  if (fechando.has(i.channelId)) return responder(i, 'Este ticket já está sendo fechado.', 'aviso');\n  fechando.add(i.channelId);\n  setTimeout(() => fechando.delete(i.channelId), 30_000);\n\n  await i.reply({ embeds: [embed(i.guildId).setColor(CORES.erro).setDescription(`🔒 Ticket fechado por ${i.user}. Este canal será apagado em 5 segundos.`)] });\n\n  const texto = await historico(i.channel);\n  const arquivo = () => new AttachmentBuilder(Buffer.from(texto || '(sem mensagens)', 'utf8'), { name: `ticket-${t.numero}.txt` });\n  const resumo = embed(i.guildId)\n    .setTitle(`🎫 Ticket #${t.numero} fechado`)\n    .addFields(\n      { name: 'Aberto por', value: `<@${t.dono}>`, inline: true },\n      { name: 'Fechado por', value: `${i.user}`, inline: true },\n      { name: 'Atendente', value: t.assumido ? `<@${t.assumido}>` : '—', inline: true },\n      { name: 'Aberto', value: `<t:${Math.floor(t.aberto / 1000)}:f>`, inline: true },\n      { name: 'Motivo', value: cortar(motivo, 1000) },\n    )\n    .setTimestamp();\n\n  const c = cfg(i.guildId);\n  const reg = c.registro && i.guild.channels.cache.get(c.registro);\n  if (reg?.isTextBased()) await reg.send({ embeds: [resumo], files: [arquivo()], allowedMentions: { parse: [] } }).catch(() => {});\n  const dono = await i.client.users.fetch(t.dono).catch(() => null);\n  if (dono) await dono.send({ embeds: [resumo.setDescription(`Seu ticket em **${i.guild.name}** foi fechado. O histórico está em anexo.`)], files: [arquivo()] }).catch(() => {});\n\n  // outros módulos (ex.: Avaliação de atendimento) ficam sabendo\n  sinais.emit('ticketFechado', { guild: i.guild, client: i.client, dono: t.dono, atendente: t.assumido, fechadoPor: i.user.id, numero: t.numero });\n\n  tickets.apagar(i.guildId, i.channelId);\n  setTimeout(() => i.channel.delete(`Ticket fechado por ${i.user.tag}`).catch(() => {}), 5000);\n}\n\n// ---------------- botões ----------------\nconst componentes = {\n  async tk(i, [acao]) {\n    if (acao === 'abrir') return abrir(i);\n    if (acao === 'fechar') {\n      const t = dados(i.guildId, i.channelId);\n      if (!t) return responder(i, 'Isto não é um ticket.', 'erro');\n      return i.reply({\n        content: 'Tem certeza que quer fechar este ticket?',\n        components: [new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('tk:confirmar').setLabel('Sim, fechar').setStyle(ButtonStyle.Danger))],\n        flags: MessageFlags.Ephemeral,\n      });\n    }\n    if (acao === 'confirmar') return fechar(i, 'Fechado pelo botão');\n    if (acao === 'assumir') {\n      const t = dados(i.guildId, i.channelId);\n      if (!t) return responder(i, 'Isto não é um ticket.', 'erro');\n      if (!podeAtender(i.member)) return responder(i, 'Só a equipe pode assumir tickets.', 'erro');\n      if (t.assumido) return responder(i, `Este ticket já é de <@${t.assumido}>.`, 'aviso');\n      t.assumido = i.user.id;\n      tickets.salvar();\n      const original = i.message.embeds[0];\n      const e = original ? EmbedBuilder.from(original) : embed(i.guildId);\n      if (original) e.setFields(original.fields.map((f) => (f.name === 'Atendente' ? { ...f, value: `${i.user}` } : f)));\n      await i.update({ embeds: [e], components: [botoesTicket(true)] });\n      return i.channel.send({ content: `🙋 ${i.user} assumiu este ticket.`, allowedMentions: { parse: [] } });\n    }\n  },\n};\n\n// ---------------- comando /ticket ----------------\nconst ticket = {\n  data: new SlashCommandBuilder()\n    .setName('ticket')\n    .setDescription('Sistema de tickets')\n    .addSubcommand((s) =>\n      s\n        .setName('painel')\n        .setDescription('Envia o painel com o botão de abrir ticket (equipe)')\n        .addChannelOption((o) => o.setName('canal').setDescription('Padrão: este canal').addChannelTypes(ChannelType.GuildText))\n        .addStringOption((o) => o.setName('titulo').setDescription('Título do painel').setMaxLength(100))\n        .addStringOption((o) => o.setName('descricao').setDescription('Texto do painel').setMaxLength(1500))\n        .addStringOption((o) => o.setName('botao').setDescription('Texto do botão').setMaxLength(60))\n    )\n    .addSubcommand((s) => s.setName('fechar').setDescription('Fecha este ticket').addStringOption((o) => o.setName('motivo').setDescription('Motivo').setMaxLength(500)))\n    .addSubcommand((s) => s.setName('adicionar').setDescription('Adiciona alguém a este ticket').addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true)))\n    .addSubcommand((s) => s.setName('remover').setDescription('Remove alguém deste ticket').addUserOption((o) => o.setName('usuario').setDescription('Quem').setRequired(true)))\n    .addSubcommand((s) =>\n      s.setName('renomear').setDescription('Muda o nome deste ticket').addStringOption((o) => o.setName('nome').setDescription('Novo nome').setRequired(true).setMaxLength(90))\n    ),\n  async executar(i) {\n    const sub = i.options.getSubcommand();\n    if (sub === 'painel') {\n      if (!i.member.permissions.has(PermissionFlagsBits.ManageGuild)) return responder(i, 'Só quem tem Gerenciar servidor pode enviar o painel.', 'erro');\n      const canal = i.options.getChannel('canal') ?? i.channel;\n      const e = embed(i.guildId)\n        .setTitle(i.options.getString('titulo') || '🎫 Atendimento')\n        .setDescription(i.options.getString('descricao') || 'Precisa de ajuda? Clique no botão abaixo e um canal privado será aberto para você falar com a equipe.');\n      const row = new ActionRowBuilder().addComponents(\n        new ButtonBuilder().setCustomId('tk:abrir').setLabel(i.options.getString('botao') || 'Abrir ticket').setEmoji('🎫').setStyle(ButtonStyle.Primary)\n      );\n      await canal.send({ embeds: [e], components: [row] });\n      return responder(i, `Painel enviado em ${canal}.`, 'sucesso');\n    }\n    if (sub === 'fechar') return fechar(i, i.options.getString('motivo') || 'Sem motivo');\n\n    const t = dados(i.guildId, i.channelId);\n    if (!t) return responder(i, 'Use este comando dentro de um ticket.', 'erro');\n    if (!podeAtender(i.member)) return responder(i, 'Só a equipe pode fazer isso.', 'erro');\n    if (sub === 'adicionar') {\n      const u = i.options.getUser('usuario');\n      const ok = await i.channel.permissionOverwrites\n        .edit(u.id, { ViewChannel: true, SendMessages: true, ReadMessageHistory: true, AttachFiles: true })\n        .then(() => true, () => false);\n      if (!ok) return responder(i, 'Não consegui adicionar. Preciso da permissão **Gerenciar cargos** para mexer nas permissões do canal.', 'erro');\n      return i.reply({ content: `➕ ${u} foi adicionado(a) ao ticket por ${i.user}.`, allowedMentions: { users: [u.id] } });\n    }\n    if (sub === 'remover') {\n      const u = i.options.getUser('usuario');\n      if (u.id === t.dono) return responder(i, 'Não dá para remover quem abriu o ticket.', 'erro');\n      await i.channel.permissionOverwrites.delete(u.id).catch(() => {});\n      return i.reply({ content: `➖ ${u} foi removido(a) do ticket.`, allowedMentions: { parse: [] } });\n    }\n    if (sub === 'renomear') {\n      const nome = i.options.getString('nome').toLowerCase().replace(/\\s+/g, '-');\n      // o Discord só deixa renomear um canal 2 vezes a cada 10 minutos: responde antes de esperar\n      await i.deferReply({ flags: MessageFlags.Ephemeral });\n      const ok = await i.channel.setName(nome).then(() => true, () => false);\n      return i.editReply(ok ? `✅ Ticket renomeado para **${nome}**.` : '❌ Não consegui renomear agora.');\n    }\n  },\n};\n\n// ---------------- /config tickets ----------------\nconst config = {\n  grupo: 'tickets',\n  montar: (g) =>\n    g\n      .setDescription('Sistema de tickets')\n      .addSubcommand((s) =>\n        s.setName('categoria').setDescription('Categoria onde os tickets são criados').addChannelOption((o) => o.setName('categoria').setDescription('Vazio = sem categoria').addChannelTypes(ChannelType.GuildCategory))\n      )\n      .addSubcommand((s) => s.setName('equipe').setDescription('Cargo que atende os tickets').addRoleOption((o) => o.setName('cargo').setDescription('Vazio = usa /config staff')))\n      .addSubcommand((s) =>\n        s.setName('registro').setDescription('Canal que recebe o histórico dos tickets fechados').addChannelOption((o) => o.setName('canal').setDescription('Vazio desliga').addChannelTypes(ChannelType.GuildText))\n      )\n      .addSubcommand((s) =>\n        s.setName('mensagem').setDescription('Mensagem de boas-vindas do ticket').addStringOption((o) => o.setName('texto').setDescription('Variáveis: {usuario} {nome} {servidor}').setRequired(true).setMaxLength(1500))\n      )\n      .addSubcommand((s) =>\n        s.setName('limite').setDescription('Tickets abertos ao mesmo tempo por pessoa').addIntegerOption((o) => o.setName('quantidade').setDescription('De 1 a 5').setRequired(true).setMinValue(1).setMaxValue(5))\n      ),\n  async executar(i, sub) {\n    const c = cfg(i.guildId);\n    let msg;\n    if (sub === 'categoria') {\n      const cat = i.options.getChannel('categoria');\n      c.categoria = cat?.id ?? null;\n      msg = cat ? `Os tickets serão criados em **${cat.name}**.` : 'Os tickets serão criados sem categoria.';\n    } else if (sub === 'equipe') {\n      const r = i.options.getRole('cargo');\n      c.equipe = r?.id ?? null;\n      msg = r ? `${r} atende os tickets.` : 'Os tickets usam o cargo de /config staff.';\n    } else if (sub === 'registro') {\n      const ch = i.options.getChannel('canal');\n      c.registro = ch?.id ?? null;\n      msg = ch ? `Histórico dos tickets vai para ${ch}.` : 'Registro de tickets desligado.';\n    } else if (sub === 'mensagem') {\n      c.mensagem = i.options.getString('texto');\n      msg = 'Mensagem do ticket atualizada.';\n    } else if (sub === 'limite') {\n      c.limite = i.options.getInteger('quantidade');\n      msg = `Cada pessoa pode ter até **${c.limite}** ticket(s) aberto(s).`;\n    }\n    salvarAjustes();\n    return responder(i, msg, 'sucesso');\n  },\n  resumo(guild) {\n    const c = cfg(guild.id);\n    const abertos = Object.keys(tickets.ler(guild.id) ?? {}).length;\n    return [\n      `Categoria: ${c.categoria ? `<#${c.categoria}>` : 'nenhuma'}`,\n      `Equipe: ${c.equipe ? `<@&${c.equipe}>` : 'cargo de /config staff'}`,\n      `Registro: ${c.registro ? `<#${c.registro}>` : 'desligado'}`,\n      `Abertos agora: ${abertos} · Limite por pessoa: ${c.limite}`,\n    ];\n  },\n};\n\nexport default {\n  id: 'tickets',\n  nome: 'Tickets',\n  // o conteúdo das mensagens é necessário para salvar o histórico ao fechar\n  intents: [GatewayIntentBits.GuildMessages, GatewayIntentBits.MessageContent],\n  permissoes: [PermissionFlagsBits.ManageChannels, PermissionFlagsBits.ManageRoles, PermissionFlagsBits.ManageMessages],\n  comandos: [ticket],\n  componentes,\n  config,\n};\n",
  "src/modules/utilidades.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, SlashCommandBuilder } from 'discord.js';\nimport { colecao } from '../core/db.js';\nimport { embed, responder, lerDuracao, duracaoTexto, ts, fmt, cortar } from '../core/util.js';\n\n/** Utilidades: informações de membros e do servidor, avatar e lembretes. */\n\nconst lembretes = colecao('lembretes');\nconst VERIFICACAO = ['Nenhuma', 'Baixa', 'Média', 'Alta', 'Muito alta'];\n\nconst userinfo = {\n  data: new SlashCommandBuilder()\n    .setName('userinfo')\n    .setDescription('Informações de um membro')\n    .addUserOption((o) => o.setName('usuario').setDescription('Padrão: você')),\n  async executar(i) {\n    const user = await (i.options.getUser('usuario') ?? i.user).fetch().catch(() => i.options.getUser('usuario') ?? i.user);\n    const membro = i.options.getMember('usuario') ?? (user.id === i.user.id ? i.member : null);\n    const e = embed(i.guildId)\n      .setAuthor({ name: user.tag, iconURL: user.displayAvatarURL() })\n      .setThumbnail(user.displayAvatarURL({ size: 256 }))\n      .addFields(\n        { name: 'ID', value: user.id, inline: true },\n        { name: 'Conta criada', value: `${ts(user.createdTimestamp, 'd')} (${ts(user.createdTimestamp)})`, inline: true },\n      );\n    if (membro) {\n      const cargos = membro.roles.cache.filter((r) => r.id !== i.guildId).sort((a, b) => b.position - a.position);\n      e.addFields(\n        { name: 'Entrou no servidor', value: `${ts(membro.joinedTimestamp, 'd')} (${ts(membro.joinedTimestamp)})`, inline: true },\n        { name: 'Apelido', value: membro.nickname || '—', inline: true },\n        { name: `Cargos (${cargos.size})`, value: cortar(cargos.map((r) => `${r}`).join(' ') || 'nenhum', 1024) },\n      );\n      if (membro.premiumSince) e.addFields({ name: 'Impulsiona desde', value: ts(membro.premiumSinceTimestamp, 'd'), inline: true });\n      if (membro.displayHexColor !== '#000000') e.setColor(membro.displayColor);\n    }\n    if (user.bannerURL()) e.setImage(user.bannerURL({ size: 1024 }));\n    await i.reply({ embeds: [e], allowedMentions: { parse: [] } });\n  },\n};\n\nconst serverinfo = {\n  data: new SlashCommandBuilder().setName('serverinfo').setDescription('Informações do servidor'),\n  async executar(i) {\n    const g = await i.guild.fetch();\n    const canais = g.channels.cache;\n    const conta = (...t) => canais.filter((c) => t.includes(c.type)).size;\n    const dono = await g.fetchOwner().catch(() => null);\n    const e = embed(i.guildId)\n      .setTitle(g.name)\n      .setThumbnail(g.iconURL({ size: 256 }))\n      .addFields(\n        { name: 'Dono', value: dono ? `${dono.user}` : '—', inline: true },\n        { name: 'Criado em', value: `${ts(g.createdTimestamp, 'd')} (${ts(g.createdTimestamp)})`, inline: true },\n        { name: 'ID', value: g.id, inline: true },\n        { name: 'Membros', value: `${fmt(g.memberCount)}${g.approximatePresenceCount ? ` · ${fmt(g.approximatePresenceCount)} online` : ''}`, inline: true },\n        {\n          name: 'Canais',\n          value: `${conta(ChannelType.GuildText, ChannelType.GuildAnnouncement, ChannelType.GuildForum)} texto · ${conta(ChannelType.GuildVoice, ChannelType.GuildStageVoice)} voz · ${conta(ChannelType.GuildCategory)} categorias`,\n          inline: true,\n        },\n        { name: 'Cargos', value: fmt(g.roles.cache.size - 1), inline: true },\n        { name: 'Emojis', value: fmt(g.emojis.cache.size), inline: true },\n        { name: 'Impulsos', value: `${g.premiumSubscriptionCount ?? 0} (nível ${g.premiumTier})`, inline: true },\n        { name: 'Verificação', value: VERIFICACAO[g.verificationLevel] ?? '—', inline: true },\n      );\n    if (g.description) e.setDescription(g.description);\n    if (g.bannerURL()) e.setImage(g.bannerURL({ size: 1024 }));\n    await i.reply({ embeds: [e], allowedMentions: { parse: [] } });\n  },\n};\n\nconst avatar = {\n  data: new SlashCommandBuilder()\n    .setName('avatar')\n    .setDescription('Mostra o avatar de alguém')\n    .addUserOption((o) => o.setName('usuario').setDescription('Padrão: você')),\n  async executar(i) {\n    const user = i.options.getUser('usuario') ?? i.user;\n    const membro = i.options.getMember('usuario') ?? (user.id === i.user.id ? i.member : null);\n    const url = (membro?.avatar ? membro.displayAvatarURL({ size: 1024 }) : null) ?? user.displayAvatarURL({ size: 1024 });\n    const row = new ActionRowBuilder().addComponents(\n      new ButtonBuilder().setStyle(ButtonStyle.Link).setLabel('Abrir no navegador').setURL(url),\n      ...(membro?.avatar ? [new ButtonBuilder().setStyle(ButtonStyle.Link).setLabel('Avatar global').setURL(user.displayAvatarURL({ size: 1024 }))] : [])\n    );\n    await i.reply({ embeds: [embed(i.guildId).setTitle(`Avatar de ${user.username}`).setImage(url)], components: [row] });\n  },\n};\n\nconst lembrete = {\n  data: new SlashCommandBuilder()\n    .setName('lembrete')\n    .setDescription('O bot te lembra de algo depois')\n    .addStringOption((o) => o.setName('tempo').setDescription('Daqui a quanto tempo: 10m, 2h, 1d').setRequired(true).setMaxLength(20))\n    .addStringOption((o) => o.setName('texto').setDescription('Do que lembrar').setRequired(true).setMaxLength(500)),\n  async executar(i) {\n    const ms = lerDuracao(i.options.getString('tempo'));\n    if (!ms || ms < 30_000 || ms > 365 * 86_400_000) return responder(i, 'Tempo inválido (ex.: 10m, 2h, 1d; entre 30s e 1 ano).', 'erro');\n    const meus = Object.values(lembretes.raiz).filter((l) => l.usuario === i.user.id).length;\n    if (meus >= 20) return responder(i, 'Você já tem 20 lembretes pendentes.', 'erro');\n    const id = `${Date.now().toString(36)}${Math.random().toString(36).slice(2, 6)}`;\n    lembretes.raiz[id] = { usuario: i.user.id, canal: i.channelId, texto: i.options.getString('texto'), quando: Date.now() + ms, criado: Date.now() };\n    lembretes.salvar();\n    return responder(i, `Combinado! Te lembro ${ts(Date.now() + ms)} (em ${duracaoTexto(ms)}).`, 'sucesso');\n  },\n};\n\nexport default {\n  id: 'utilidades',\n  nome: 'Utilidades',\n  comandos: [userinfo, serverinfo, avatar, lembrete],\n  aoIniciar(client) {\n    const checar = async () => {\n      const agora = Date.now();\n      for (const [id, l] of Object.entries(lembretes.raiz)) {\n        if (l.quando > agora) continue;\n        delete lembretes.raiz[id];\n        lembretes.salvar();\n        const texto = `⏰ <@${l.usuario}>, você pediu para eu te lembrar (${ts(l.criado)}):\\n> ${cortar(l.texto, 500)}`;\n        const user = await client.users.fetch(l.usuario).catch(() => null);\n        const foiDm = await user?.send(texto).then(() => true).catch(() => false);\n        if (!foiDm) {\n          const canal = await client.channels.fetch(l.canal).catch(() => null);\n          await canal?.send({ content: texto, allowedMentions: { users: [l.usuario] } }).catch(() => {});\n        }\n      }\n    };\n    checar();\n    setInterval(checar, 15_000);\n  },\n};\n",
  "src/modules/verificacao.js": "import { ActionRowBuilder, ButtonBuilder, ButtonStyle, ChannelType, MessageFlags, PermissionFlagsBits, SlashCommandBuilder } from 'discord.js';\nimport { ajustes, salvarAjustes, embed, responder, sorteio, CORES } from '../core/util.js';\n\n/**\n * Verificação: painel com o botão \"Verificar\". A pessoa resolve um desafio simples\n * (clicar no número certo) e ganha o cargo de membro. Segura contas de bots e raids.\n * Opcional: idade mínima da conta e cargo removido ao verificar.\n */\n\nconst PADRAO = { cargo: null, remover: null, registro: null, idadeMinima: 0 };\nconst cfg = (guildId) => ajustes(guildId, 'verificacao', PADRAO);\n\n// desafios em andamento: \"guild:user\" -> { opcoes, resposta, expira, erros } (a resposta fica só aqui, não no botão)\nconst desafios = new Map();\nconst chave = (i) => `${i.guildId}:${i.user.id}`;\nconst EMOJIS = ['🍎', '🐶', '🚗', '⭐', '🎈', '🍕', '⚽', '🌙', '🔑', '🎧'];\n\nasync function registrar(guild, texto, cor = CORES.sucesso) {\n  const id = cfg(guild.id).registro;\n  const canal = id && guild.channels.cache.get(id);\n  if (canal?.isTextBased()) await canal.send({ embeds: [embed(guild.id).setColor(cor).setDescription(texto).setTimestamp()], allowedMentions: { parse: [] } }).catch(() => {});\n}\n\nfunction novoDesafio(i) {\n  const opcoes = [...EMOJIS].sort(() => Math.random() - 0.5).slice(0, 5);\n  const resposta = opcoes[sorteio(0, opcoes.length - 1)];\n  const antigo = desafios.get(chave(i));\n  desafios.set(chave(i), { opcoes, resposta, expira: Date.now() + 2 * 60_000, erros: antigo?.erros ?? 0 });\n  return {\n    embeds: [embed(i.guildId).setTitle('🔐 Verificação').setDescription(`Para provar que você não é um robô, clique em **${resposta}**.\\n\\nVocê tem 2 minutos.`)],\n    components: [\n      new ActionRowBuilder().addComponents(\n        opcoes.map((e, n) => new ButtonBuilder().setCustomId(`vf:r:${n}`).setEmoji(e).setStyle(ButtonStyle.Secondary))\n      ),\n    ],\n    flags: MessageFlags.Ephemeral,\n  };\n}\n\nconst componentes = {\n  async vf(i, [acao, indice]) {\n    const c = cfg(i.guildId);\n    const cargo = c.cargo && i.guild.roles.cache.get(c.cargo);\n    if (!cargo) return responder(i, 'A verificação ainda não foi configurada. Avise a equipe.', 'erro');\n\n    if (acao === 'iniciar') {\n      if (i.member.roles.cache.has(cargo.id)) return responder(i, 'Você já está verificado(a)!', 'sucesso');\n      const dias = (Date.now() - i.user.createdTimestamp) / 86400e3;\n      if (c.idadeMinima && dias < c.idadeMinima) {\n        await registrar(i.guild, `⛔ ${i.user} (${i.user.tag}) tentou se verificar com uma conta de ${Math.floor(dias)} dia(s).`, CORES.aviso);\n        return responder(i, `Sua conta do Discord precisa ter pelo menos **${c.idadeMinima} dia(s)** para entrar aqui. Tente de novo mais tarde.`, 'erro');\n      }\n      return i.reply(novoDesafio(i));\n    }\n\n    if (acao === 'r') {\n      const d = desafios.get(chave(i));\n      if (!d || d.expira < Date.now()) {\n        desafios.delete(chave(i));\n        return i.update({ content: '⏱️ O tempo acabou. Clique em **Verificar** de novo.', embeds: [], components: [] });\n      }\n      if (d.opcoes[Number(indice)] !== d.resposta) {\n        d.erros += 1;\n        if (d.erros >= 3) {\n          desafios.delete(chave(i));\n          await registrar(i.guild, `⚠️ ${i.user} (${i.user.tag}) errou a verificação 3 vezes.`, CORES.aviso);\n          return i.update({ content: '❌ Você errou 3 vezes. Espere um pouco e clique em **Verificar** de novo.', embeds: [], components: [] });\n        }\n        const proximo = novoDesafio(i);\n        return i.update({ content: '❌ Não foi esse. Tente de novo:', embeds: proximo.embeds, components: proximo.components });\n      }\n      desafios.delete(chave(i));\n      if (!cargo.editable) return i.update({ content: '❌ Não consigo dar o cargo (o meu cargo está abaixo dele). Avise a equipe.', embeds: [], components: [] });\n      const ok = await i.member.roles.add(cargo, 'Verificação').then(() => true, () => false);\n      if (!ok) return i.update({ content: '❌ Não consegui te dar o cargo. Avise a equipe.', embeds: [], components: [] });\n      const remover = c.remover && i.guild.roles.cache.get(c.remover);\n      if (remover?.editable && i.member.roles.cache.has(remover.id)) await i.member.roles.remove(remover, 'Verificação').catch(() => {});\n      await registrar(i.guild, `✅ ${i.user} (${i.user.tag}) se verificou.`);\n      return i.update({ content: `✅ Verificado(a)! Você recebeu ${cargo}. Bem-vindo(a)!`, embeds: [], components: [] });\n    }\n  },\n};\n\nconst verificacao = {\n  data: new SlashCommandBuilder()\n    .setName('verificacao')\n    .setDescription('Configura a verificação de novos membros')\n    .setDefaultMemberPermissions(PermissionFlagsBits.ManageGuild)\n    .addSubcommand((s) =>\n      s\n        .setName('configurar')\n        .setDescription('Cargo que a pessoa ganha ao se verificar e outras opções')\n        .addRoleOption((o) => o.setName('cargo').setDescription('Cargo dado ao verificar').setRequired(true))\n        .addRoleOption((o) => o.setName('remover').setDescription('Cargo tirado ao verificar (ex.: \"Não verificado\")'))\n        .addIntegerOption((o) => o.setName('idade-minima').setDescription('Idade mínima da conta, em dias (0 = sem limite)').setMinValue(0).setMaxValue(365))\n        .addChannelOption((o) => o.setName('registro').setDescription('Canal para registrar as verificações').addChannelTypes(ChannelType.GuildText))\n    )\n    .addSubcommand((s) =>\n      s\n        .setName('painel')\n        .setDescription('Envia o painel com o botão \"Verificar\"')\n        .addChannelOption((o) => o.setName('canal').setDescription('Onde enviar (padrão: aqui)').addChannelTypes(ChannelType.GuildText))\n        .addStringOption((o) => o.setName('mensagem').setDescription('Texto do painel').setMaxLength(1500))\n    ),\n  async executar(i) {\n    const c = cfg(i.guildId);\n    if (i.options.getSubcommand() === 'configurar') {\n      const cargo = i.options.getRole('cargo');\n      if (cargo.managed || cargo.id === i.guildId) return responder(i, 'Escolha um cargo comum (não pode ser @everyone nem cargo de bot).', 'erro');\n      if (cargo.permissions.has(PermissionFlagsBits.Administrator)) return responder(i, 'Por segurança, o cargo de verificação não pode ser de administrador.', 'erro');\n      if (!cargo.editable) return responder(i, `Meu cargo precisa ficar acima de ${cargo} em Configurações do servidor → Cargos.`, 'erro');\n      c.cargo = cargo.id;\n      const remover = i.options.getRole('remover');\n      if (remover !== null) c.remover = remover?.id ?? null;\n      const idade = i.options.getInteger('idade-minima');\n      if (idade !== null) c.idadeMinima = idade;\n      const reg = i.options.getChannel('registro');\n      if (reg) c.registro = reg.id;\n      salvarAjustes();\n      return responder(\n        i,\n        `Verificação configurada: ganha ${cargo}${c.remover ? `, perde <@&${c.remover}>` : ''}${c.idadeMinima ? `, conta com pelo menos ${c.idadeMinima} dia(s)` : ''}.\\nAgora use \\`/verificacao painel\\`.`,\n        'sucesso'\n      );\n    }\n\n    if (!c.cargo) return responder(i, 'Primeiro use `/verificacao configurar` para escolher o cargo.', 'erro');\n    const canal = i.options.getChannel('canal') ?? i.channel;\n    const texto = i.options.getString('mensagem') || 'Clique no botão abaixo para se verificar e liberar o servidor.';\n    const msg = await canal\n      .send({\n        embeds: [embed(i.guildId).setTitle('🔐 Verificação').setDescription(texto)],\n        components: [new ActionRowBuilder().addComponents(new ButtonBuilder().setCustomId('vf:iniciar').setLabel('Verificar').setEmoji('✅').setStyle(ButtonStyle.Success))],\n      })\n      .catch(() => null);\n    if (!msg) return responder(i, `Não consegui enviar em ${canal}. Confira as minhas permissões.`, 'erro');\n    return responder(i, `Painel enviado em ${canal}.`, 'sucesso');\n  },\n};\n\n// limpa desafios vencidos\nsetInterval(() => {\n  const agora = Date.now();\n  for (const [k, d] of desafios) if (d.expira < agora) desafios.delete(k);\n}, 5 * 60_000).unref();\n\nexport default {\n  id: 'verificacao',\n  nome: 'Verificação',\n  comandos: [verificacao],\n  componentes,\n  permissoes: [PermissionFlagsBits.ManageRoles],\n  config: {\n    resumo(guild) {\n      const c = cfg(guild.id);\n      if (!c.cargo) return ['Não configurada (`/verificacao configurar`)'];\n      return [\n        `Cargo: <@&${c.cargo}>${c.remover ? ` · remove <@&${c.remover}>` : ''}`,\n        `Idade mínima da conta: ${c.idadeMinima ? `${c.idadeMinima} dia(s)` : 'sem limite'}`,\n        `Registro: ${c.registro ? `<#${c.registro}>` : 'não definido'}`,\n      ];\n    },\n  },\n};\n",
};
